51	function fileSize(bytes: number | null): string | null {
52	  if (!bytes || bytes <= 0) return null;
53	  return bytes >= 1024 ** 3 ? `${(bytes / 1024 ** 3).toFixed(1)} GB` : bytes >= 1024 * 1024 ? `${Math.round(bytes / 1024 / 1024)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;
54	}
55	function downloadCount(n: number | null): string | null {
56	  if (!n || n < 1) return null;
57	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M downloads`;
58	  if (n >= 1_000) return `${Math.round(n / 1000)}k downloads`;
59	  return `${n} downloads`;
60	}
