/** Latest upstream version for each installed engine mod (on demand, capped). */
export async function checkModUpdates(serverId: string): Promise<{ error?: string; updates?: Record<string, string | null> }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  if (throttled(user.id, "mod-updates", 4)) return { error: "Checked very recently — try again in a minute." };
  const rows = await db.serverMod.findMany({ where: { serverId, status: { in: ["INSTALLED", "DISABLED"] } }, include: { mod: true }, take: 15 });
  const facts = serverFacts(server, family);
  const work = rows.filter((r) => engineInstallerFor(family, r.mod.source));
  const out: Record<string, string | null> = {};
  let i = 0;
  await Promise.all(
    Array.from({ length: 3 }, async () => {
      while (i < work.length) {
        const r = work[i++];
        const inst = engineInstallerFor(family, r.mod.source)!;
        const p = await previewResolve(inst, catalogFacts(r.mod), facts, safeFetch, PREVIEW_LAYOUT(facts.pinnedVersion)).catch(() => null);
        const root = p && p.ok ? p.packages.find((x) => x.root) : null;
        out[r.modId] = root ? root.version : null;
      }
    }),
  );
  return { updates: out };
}

/**
 * License policy for the local mirror. We ONLY store a mod's FILE when its
 * declared license grants redistribution. Everything else is metadata +
 * link-through. Conservative by design: unknown/empty/"all rights reserved"
 * => not redistributable.
 */

const OPEN_SPDX = new Set([
  "mit", "mit-0", "apache-2.0", "bsd-2-clause", "bsd-3-clause", "bsd-3-clause-clear", "isc", "unlicense",
  "cc0-1.0", "zlib", "0bsd", "mpl-2.0", "lgpl-2.1", "lgpl-2.1-only", "lgpl-2.1-or-later", "lgpl-3.0",
  "lgpl-3.0-only", "lgpl-3.0-or-later", "gpl-2.0", "gpl-2.0-only", "gpl-2.0-or-later", "gpl-3.0",
  "gpl-3.0-only", "gpl-3.0-or-later", "agpl-3.0", "agpl-3.0-only", "agpl-3.0-or-later", "cc-by-4.0",
  "cc-by-sa-4.0", "cc-by-3.0", "cc-by-sa-3.0", "artistic-2.0", "bsl-1.0", "epl-2.0", "eupl-1.2",
]);

/** Free-text names some providers use (Hangar's license.type) mapped to the SPDX family. */
const NAME_ALIASES: Record<string, string> = {
  mit: "mit", "mit license": "mit", apache: "apache-2.0", "apache 2.0": "apache-2.0", "apache-2.0": "apache-2.0",
  gpl: "gpl-3.0", gplv3: "gpl-3.0", "gpl-3.0": "gpl-3.0", gplv2: "gpl-2.0", lgpl: "lgpl-3.0", agpl: "agpl-3.0",
  bsd: "bsd-3-clause", "bsd-3": "bsd-3-clause", mpl: "mpl-2.0", unlicense: "unlicense", cc0: "cc0-1.0", isc: "isc",
};

export function normalizeLicense(raw: string | null | undefined): string | null {
  const t = (raw ?? "").trim();
  return t ? t : null;
}

export function isRedistributable(license: string | null | undefined): boolean {
  const t = normalizeLicense(license)?.toLowerCase();
  if (!t) return false;
  if (t.includes("licenseref") || t.includes("reserved") || t.includes("proprietary") || t === "other" || t === "custom") return false;
  if (OPEN_SPDX.has(t)) return true;
  const alias = NAME_ALIASES[t];
  return !!alias && OPEN_SPDX.has(alias);
}
/**
 * Icon/screenshot cache. Downloads an upstream image (https only, size-capped,
 * content-type checked), resizes + converts to WebP with sharp, stores it
