/**
 * Only http(s) allowed, https FORCED (audit: "force https on embedded
 * images"). Protocol-relative `//host/img.png` gets an https: prefix.
 * Anything else (data:, javascript:, blob:, bare text) is rejected — the
 * caller drops the element entirely rather than render a broken/unsafe one.
 */
function safeImageSrc(u: string | null | undefined): string | null {
  if (!u) return null;
  const t = u.trim();
  if (/^https:\/\//i.test(t)) return t;
  if (/^http:\/\//i.test(t)) return `https://${t.slice(7)}`;
  if (/^\/\//.test(t)) return `https:${t}`;
  return null;
