  if (!u) return "#";
  const t = u.trim();
  if (/^https:\/\//i.test(t)) return t;
  if (/^http:\/\//i.test(t)) return `https://${t.slice(7)}`;
  if (/^\/(?!\/|\\)/.test(t)) return t;
  return "#";
