    if (!safe) return "";
    // escAttrPostEscaped, not escAttr — `s` (and therefore `u`/`alt`) is
    // already-escaped text at this point (see this function's first line);
    // see that helper's own doc comment for why a second full `esc()` pass
    // here would both double-encode AND (found in review, 2026-09-24) is
    // NOT what was neutralizing the `"` that lets a crafted URL break out
    // of this attribute — omitting it here entirely was the real bug.
    return `<img class="${CLS.img}" src="${escAttrPostEscaped(safe)}" alt="${escAttrPostEscaped(alt)}" loading="lazy" />`;
  });
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
    const safe = safeLinkHref(u);
    const ext = safe.startsWith("http");
    return `<a class="${CLS.a}" href="${escAttrPostEscaped(safe)}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${t}</a>`;
  });
  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
  return s;
}

/**
 * Cut raw markdown SOURCE at a real paragraph/line boundary at or before
 * `maxChars`, never mid-word/mid-tag — replaces the old
 * `longDescription.slice(0, 6000)` raw character slice, which could (and,
 * on real bodies, did) cut in the middle of a markdown construct or a raw
 * HTML tag. Returns the untruncated text unchanged when it already fits.
 */

/**
 * NxLabs — the public + in-portal mod/plugin catalogue read layer.
 *
 * This is a thin, presentation-agnostic layer over the REAL `GameMod` table
 * (seeded rows, enriched by scripts/verify-gamemods.ts). It backs three call
 * sites that must never disagree about what a mod "is":
 *   - app/(marketing)/mods (public browse + detail pages, anonymous-visible)
 *   - app/dashboard/nxlabs (logged-in catalogue with "Add to my server")
 *   - app/sitemap.ts (which detail pages get indexed)
 *
 * Deliberately NOT here: install/uninstall. Those stay exactly where they are
 * — lib/actions-mods.ts's installMod/uninstallMod — this module only reads.
 *
 * HONESTY: a mod only appears in the public/portal catalogue when
 * `active && upstreamOk`. `upstreamOk: false` is scripts/verify-gamemods.ts's
 * (or an admin's manual toggle's) way of saying "no longer supported" — it is
 * excluded rather than shown with a broken badge, matching how
 * lib/actions-mods.ts's getServerMods already filters for the per-server
 * panel. Fields the source never published (gameVersions, license, ...) stay
 * empty and the UI says so — never a guess.
 *
 * REAL PAGINATION (2026-09-19): every comment in this file used to say "small
 * catalogue (~124 rows), the whole set is returned in one shot, filters run
 * client-side" — true when this was hand-seeded, false the moment a real
 * bulk import (scripts/import-modrinth-catalog.ts) landed 32,000+ real
 * Modrinth rows in the `minecraft` family alone. A hard 400-row cap
 * (`CATALOG_LIST_CAP`, since removed) used to mean the other ~31,850 mods in
 * that family were permanently unreachable — no page 2 existed. `queryCatalogMods`
 * replaces `listCatalogMods`/`searchCatalogMods` with real server-side,
 * DB-level pagination (`skip`/`take` + a real `count()`), and search/sort/
 * category-filter all run as part of the SAME query rather than over an
 * in-memory array — see StoreBrowser.tsx's own header comment for why search
 * specifically had to move server-side (its placeholder text promises to
 * search the whole catalogue, not just whatever page happens to be loaded).
 */
import { unstable_cache } from "next/cache";
import { db } from "./db";
import { Prisma, type GameMod, type GamePlan } from "@prisma/client";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { paginate } from "./pagination";

/**
 * Real revalidate window for the two whole-catalogue aggregates below
 * (`listCatalogFamilies`, `totalDownloadsFor`) — both are cheap in isolation
 * today (~25-30ms, confirmed live 2026-09-21) but recomputed from scratch on
 * EVERY /mods, /mods/games/[family], /dashboard/nxlabs, and
 * /dashboard/nxlabs/games/[family] request (these pages are `force-dynamic`,
 * so nothing about the route itself is cached). Neither number needs
 * second-by-second freshness — a mod's `featured`/`downloads` values only
 * change via periodic backfill scripts (scripts/verify-gamemods.ts and
 * friends), never a live user action — so wrapping them in Next's real data
 * cache with a 10-minute window cuts real, repeated DB round trips under
 * concurrent traffic without ever showing stale-by-more-than-10-minutes data.
 */
const CATALOG_AGGREGATE_REVALIDATE_SECONDS = 600;

/** Real page size for StoreBrowser — no longer a total-catalogue ceiling. */
const CATALOG_PAGE_SIZE = 24;

export type ModSummary = {
  id: string;
  gameFamily: string;
  gameFamilyLabel: string;
  name: string;
  slug: string;
  category: string;
  source: string;
  iconUrl: string | null;
  description: string | null;
  downloads: number | null;
  featured: boolean;
  paid: boolean;
  verified: boolean;
  impact: string;
  createdAt: string; // ISO — client components get plain data, not Date objects
  /** Real computed average (1-5) from ModRating, null when nobody has rated it yet. */
  avgRating: number | null;
  /** Real count backing avgRating — 0 means "no ratings", never hidden behind a fake avg. */
  ratingCount: number;
  /**
   * The three fields resolveDownloadUrl() needs — carried on the summary too
   * (not just ModDetail) so a browse grid's cards can resolve the same real,
   * per-source download destination as the detail page without a second
   * query: queryCatalogMods already loads the full GameMod row internally,
   * so exposing these costs nothing extra.
   */
  url: string | null;
  sourceId: string | null;
  appliesToVariant: string | null;
  /**
   * The mod's REAL last-shipped timestamp on its own upstream source (ISO —
   * see GameMod.upstreamUpdatedAt's own comment for the confirmed per-source
   * field this is populated from). Null means "not backfilled/verified yet",
   * never a guess — listRecentlyUpdatedMods filters those rows out entirely
   * rather than showing them.
   */
  upstreamUpdatedAt: string | null;
  /** First real gallery screenshot (GameMod.galleryUrls[0]) — a card banner.
   *  Null when the source published none; cards fall back to category art. */
  banner?: string | null;
  /** Real loaders/platforms the source lists (may be empty). */
  loaders?: string[];
};

export type ModDetail = ModSummary & {
  url: string | null;
  sourceId: string | null;
  license: string | null;
  gameVersions: string[];
  loaders: string[];
  fileBytes: number | null;
  dependencyCount: number;
  serverSide: string | null;
  impactNote: string | null;
  appliesToVariant: string | null;
  verifiedAt: Date | null;
  upstreamOk: boolean;
  upstreamNote: string | null;
  galleryUrls: string[];
  authorName: string | null;
  authorAvatarUrl: string | null;
  /** Source's own longer project-page body (Modrinth's `body`), when backfilled — see GameMod.longDescription. */
  longDescription: string | null;
};

export type ModComment = {
  id: string;
  rating: number;
  comment: string;
  createdAt: string;
  userId: string;
  userName: string;
};

function familyLabel(family: string): string {
  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
}

type RatingAgg = { avg: number | null; count: number };

/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
  if (modIds.length === 0) return new Map();
  const rows = await db.modRating.groupBy({
    by: ["gameModId"],
    where: { gameModId: { in: modIds } },
    _avg: { rating: true },
    _count: { rating: true },
  });
  return new Map(rows.map((r) => [r.gameModId, { avg: r._avg.rating, count: r._count.rating }]));
}

function toSummary(m: GameMod, agg?: RatingAgg): ModSummary {
  return {
    id: m.id,
    gameFamily: m.gameFamily,
    gameFamilyLabel: familyLabel(m.gameFamily),
    name: m.name,
    slug: m.slug,
    category: m.category,
    source: m.source,
    iconUrl: m.iconUrl,
    description: m.description,
    downloads: m.downloads,
    featured: m.featured,
    paid: m.paid,
    verified: m.verifiedAt !== null,
    impact: m.impact,
    createdAt: m.createdAt.toISOString(),
    avgRating: agg?.avg ?? null,
    ratingCount: agg?.count ?? 0,
    url: m.url,
    sourceId: m.sourceId,
    appliesToVariant: m.appliesToVariant,
    upstreamUpdatedAt: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
    banner: m.galleryUrls[0] ?? null,
    loaders: m.loaders,
  };
}

function toDetail(m: GameMod, agg?: RatingAgg): ModDetail {
  return {
    ...toSummary(m, agg),
    url: m.url,
    sourceId: m.sourceId,
    license: m.license,
    gameVersions: m.gameVersions,
    loaders: m.loaders,
    fileBytes: m.fileBytes,
    dependencyCount: m.dependencyCount,
    serverSide: m.serverSide,
    impactNote: m.impactNote,
    appliesToVariant: m.appliesToVariant,
    verifiedAt: m.verifiedAt,
    upstreamOk: m.upstreamOk,
    upstreamNote: m.upstreamNote,
    galleryUrls: m.galleryUrls,
    authorName: m.authorName,
    authorAvatarUrl: m.authorAvatarUrl,
    longDescription: m.longDescription,
  };
}

/** Real, publicly-listable families — active mods with a real upstream today. */
export const listCatalogFamilies = unstable_cache(
  async (): Promise<{ family: string; label: string; count: number }[]> => {
    const rows = await db.gameMod.groupBy({
      by: ["gameFamily"],
      where: { active: true, upstreamOk: true },
      _count: true,
      orderBy: { gameFamily: "asc" },
    });
    return rows
      .map((r) => ({ family: r.gameFamily, label: familyLabel(r.gameFamily), count: r._count }))
      .sort((a, b) => b.count - a.count);
  },
  ["mods-catalog:listCatalogFamilies"],
  { revalidate: CATALOG_AGGREGATE_REVALIDATE_SECONDS }
);

/** "updated" = the mod's real last upstream release (upstreamUpdatedAt),
 *  never-verified rows last; "latest" = newest in NxLabs (createdAt). */
export type CatalogSort = "featured" | "downloads" | "latest" | "rating" | "updated";

export type CatalogPage = {
  mods: ModSummary[];
  total: number;
  page: number;
  totalPages: number;
  perPage: number;
};

/**
 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
 * the one honest exception: avgRating is computed from a separate ModRating
 * table with no cached column on GameMod, and Prisma's relation-aggregate
 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
 * and re-sorting by rating WITHIN each page (below) is a documented
 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
 * re-ordered by rating, not the true 25th-48th highest-rated mods
 * catalogue-wide. That is honest and fine at today's rating volumes (a small
 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
 * the rating mutation) and give this its own real orderBy.
 */
const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
  featured: [{ featured: "desc" }, { downloads: { sort: "desc", nulls: "last" } }, { popularity: "desc" }, { name: "asc" }],
  downloads: [{ downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }],
  latest: [{ createdAt: "desc" }],
  updated: [{ upstreamUpdatedAt: { sort: "desc", nulls: "last" } }, { name: "asc" }],
  rating: [{ downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }],
};

/**
 * Real, server-side, paginated + searched + sorted catalogue query — the
 * single data source behind every StoreBrowser instance (marketing and
 * portal, cross-game and per-family). Replaces the old
 * `listCatalogMods`/`searchCatalogMods` pair, which fetched (at most)
 * `CATALOG_LIST_CAP` rows once and left every control on top of it running
 * over that fixed in-memory array — fine at ~124 hand-seeded rows, silently
 * capping the catalogue at families with thousands+ of real imported rows.
 */
export async function queryCatalogMods(opts: {
  family?: string;
  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
  category?: string;
  q?: string;
  sort?: CatalogSort;
  page?: number;
  perPage?: number;
  /** Only mods whose source lists this loader/platform (GameMod.loaders). */
  loader?: string;
  /** Only mods whose source lists this game version (GameMod.gameVersions). */
  gameVersion?: string;
}): Promise<CatalogPage> {
  const sort = opts.sort ?? "featured";
  const q = (opts.q ?? "").trim();
  const where: Prisma.GameModWhereInput = {
    active: true,
    upstreamOk: true,
    ...(opts.family ? { gameFamily: opts.family } : {}),
    ...(opts.category ? { category: opts.category } : {}),
    ...(opts.loader ? { loaders: { has: opts.loader } } : {}),
    ...(opts.gameVersion ? { gameVersions: { has: opts.gameVersion } } : {}),
    ...(q
      ? {
          OR: [
            { name: { contains: q, mode: "insensitive" } },
            { category: { contains: q, mode: "insensitive" } },
            { description: { contains: q, mode: "insensitive" } },
          ],
        }
      : {}),
  };

  const total = await db.gameMod.count({ where });
  const { skip, take, page, pages, perPage } = paginate(
    { page: opts.page != null ? String(opts.page) : undefined },
    total,
    opts.perPage ?? CATALOG_PAGE_SIZE
  );

  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
  if (sort === "rating") {
    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
  }

  return { mods, total, page, totalPages: pages, perPage };
}

