    const qm = p.node && p.vmid ? await ssh(p.node, `qm status ${p.vmid} 2>&1 | head -1`) : "n/a";
    const rules = p.node && p.chain ? await ssh(p.node, `iptables -t nat -S ${p.chain} | grep -cE -- '--dport (${p.pubPorts.join("|") || "0"})( |$)'; true`) : "n/a";
    const dns = p.sub ? [await sh("dig", ["+short", "SRV", `_minecraft._tcp.${p.sub}.play.nxeon.cloud`]).then((r) => r.stdout.trim()).catch(() => "?"), await sh("dig", ["+short", "A", `${p.sub}.play.nxeon.cloud`]).then((r) => r.stdout.trim()).catch(() => "?")].join("").trim() : "n/a";
    const clean = (!srv || srv.status === "DELETED") && fwdLeft === 0 && /does not exist/.test(qm) && (rules === "0" || rules === "n/a") && (!dns || dns === "n/a");
    lines.push(`${clean ? "CLEAN " : "LEAK? "} ${p.host} server=${srv ? srv.status : "row-gone"} fwdRows=${fwdLeft} vm="${qm}" natRules=${rules} dnsSRV="${dns}"`);
  }
  const leftovers = await ssh((servers[0]?.node?.publicIp) ?? "54.39.132.159", "qm list 2>/dev/null | grep qa-sweep || echo none");
  const text = `\n### Teardown\n${lines.join("\n")}\nVMs named qa-sweep still on node: ${leftovers}\n`;
  appendFileSync(`${OUT}/SUMMARY.md`, text);
  console.log(text);
}
main().then(() => process.exit(0)).catch((e) => { console.error("FATAL", e.message); process.exit(1); });

