  const s = Math.round((d.getTime() - Date.now()) / 1000);
  if (s <= 0) return "due";
  if (s < 3600) return `in ${Math.ceil(s / 60)}m`;
  if (s < 86400) return `in ${Math.round(s / 3600)}h`;
