type Action = "pause" | "resume" | "run-now" | "reset-cursor" | "enable" | "disable";

export function NxLabsSyncControls({ providerKey, paused, enabled }: { providerKey: string; paused: boolean; enabled: boolean }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const go = (a: Action, confirmText?: string) => {
    if (confirmText && !window.confirm(confirmText)) return;
    start(async () => {
      const r = await adminModsyncControl(providerKey, a);
      setMsg(r.error ?? null);
    });
  };
  return (
    <div className="flex flex-wrap items-center gap-2">
      {msg && <span className="text-xs text-red-400">{msg}</span>}
      <button className="btn-primary py-1 text-xs" disabled={pending || !enabled} onClick={() => go("run-now")}>Run now</button>
      {paused ? (
        <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => go("resume")}>Resume</button>
      ) : (
        <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => go("pause")}>Pause</button>
      )}
      <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => go(enabled ? "disable" : "enable")}>{enabled ? "Disable" : "Enable"}</button>
      <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => go("reset-cursor", `Reset ${providerKey}'s crawl position? The next run starts from the beginning.`)}>Reset cursor</button>
    </div>
