}

import fs from "node:fs/promises";
import path from "node:path";

/** Root of the NX Labs local store (mod files + cached images). On this host: a quota'd dataset on the 3 TB `tank` pool, NOT the 49 GB root disk. */
export function mirrorDir(): string {
  return process.env.NXLABS_MIRROR_DIR || "/tank/nxlabs-mirror";
}
/** Total bytes of mod FILES we allow ourselves (the owner's ~100 GB). Images are budgeted separately and are tiny. */
export function mirrorMaxBytes(): number {
  const v = Number(process.env.NXLABS_MIRROR_MAX_BYTES);
  return Number.isFinite(v) && v > 0 ? v : 100 * 1024 ** 3;
}
/** Hard per-file ceiling: bigger artifacts (modpacks) are link-through only. */
export function mirrorMaxFileBytes(): number {
  const v = Number(process.env.NXLABS_MIRROR_MAX_FILE_BYTES);
  return Number.isFinite(v) && v > 0 ? v : 150 * 1024 ** 2;
}
export const filesRoot = () => path.join(mirrorDir(), "files");
export const imagesRoot = () => path.join(mirrorDir(), "img");
export const tmpRoot = () => path.join(mirrorDir(), "tmp");

let readyCache: { at: number; ok: boolean } | null = null;
/**
 * The mirror root must ALREADY EXIST (provisioned by the owner as its own quota'd
 * dataset). We never mkdir it ourselves: on a host where /tank is not mounted that
 * would silently fill the 49 GB root disk. When it is missing, image caching and
 * file mirroring are skipped (metadata + hotlinks keep working).
 */
export async function mirrorReady(): Promise<boolean> {
  if (readyCache && Date.now() - readyCache.at < 30_000) return readyCache.ok;
  let ok = false;
  try {
    ok = (await fs.stat(mirrorDir())).isDirectory();
  } catch {}
  readyCache = { at: Date.now(), ok };
  return ok;
}
