// ── Nxeon Verified (K5 mod browser, 2026-10-01; ALL additive) ────────────────
// Deliberately NO Prisma relations to GameMod/ModVersion: those models are
// being extended in parallel (K3 providers, K4 auto-update) and a back-relation
// field on them would be a guaranteed merge conflict. Ids are plain indexed
// strings; lib/mod-verify/* joins by id and tolerates a missing mod/version
// (an orphaned row simply never renders a badge).

/// One verification verdict for ONE mod build on ONE game version (+ loader).
/// "Nxeon Verified" is shown only for status=VERIFIED with expiresAt in the
/// future — the badge can never go stale. VERIFIED is only reachable when every
/// automated check passed AND the install smoke test passed on a throwaway
/// server (lib/mod-verify/status.ts). It is NOT a security guarantee and the UI
/// never says it is.
model ModVerification {
  id            String    @id @default(cuid())
  gameModId     String
  /// ModVersion.id of the exact build checked (null for families whose
  /// catalogue has no per-version rows yet — those can never be VERIFIED).
  modVersionId  String?
  /// Snapshot of the version label at check time (ModVersion.versionNumber).
  versionNumber String?
  gameFamily    String
  /// Game version the build was checked against ("1.21.1"); "any" for games
  /// whose servers have no version pin (expiry is the only freshness then).
  gameVersion   String
  /// Loader/variant the smoke test used ("paper", "fabric", "bepinex"; "" = n/a).
  loader        String    @default("")
  /// UNVERIFIED | VERIFIED | FLAGGED | REVOKED
  status        String    @default("UNVERIFIED")
  /// { [checkName]: { result: "pass"|"fail"|"warn"|"pending"|"skipped", detail, at } }
  checks        Json      @default("{}")
  verifiedAt    DateTime?
  expiresAt     DateTime?
  /// "system" (automated) or the admin user id that flagged/revoked it.
  verifiedBy    String?
  notes         String?
  revokedAt     DateTime?
  revokedReason String?
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt

  @@unique([gameModId, gameVersion, loader, modVersionId])
  @@index([gameModId, status, expiresAt])
  @@index([status, expiresAt])
  @@index([gameFamily, status])
}

/// Work queue for verification: PREFLIGHT (download + hash + archive + licence
/// checks, network only) and SMOKE (install on a throwaway test server, start
/// the game, confirm the mod loaded, tear down). Processed ONLY by
/// scripts/mod-verify.ts, run by the owner — never by the web app.
model ModVerifyTask {
  id           String    @id @default(cuid())
  kind         String // PREFLIGHT | SMOKE
  gameModId    String
  modVersionId String?
  gameFamily   String
  gameVersion  String
  loader       String    @default("")
  /// QUEUED | RUNNING | PASSED | FAILED | ERROR | CANCELLED
  status       String    @default("QUEUED")
  requestedBy  String?
  attempts     Int       @default(0)
  /// Throwaway server used by a SMOKE run (torn down afterwards).
  serverId     String?
  result       Json?
  error        String?
  startedAt    DateTime?
  finishedAt   DateTime?
  createdAt    DateTime  @default(now())
  updatedAt    DateTime  @updatedAt

  @@index([status, kind, createdAt])
  @@index([gameModId, createdAt(sort: Desc)])
}

/// Known-bad file hashes. A build whose hash is listed is FLAGGED and its
/// verification revoked; installers can consult this too.
model ModBlockedHash {
  id        String   @id @default(cuid())
  /// lowercase hex; algo inferred from length (40 sha1, 64 sha256, 128 sha512)
  hash      String   @unique
  reason    String
  addedBy   String?
  createdAt DateTime @default(now())
}
EOF
