 * network): every input is passed in, so each check is unit-tested in
 * test/mod-verify.test.ts and the runner (lib/mod-verify/preflight.ts,
 * scripts/mod-verify.ts) is just plumbing around them.
 *
 * What "verified" is allowed to mean is deliberately narrow and honest:
 *  - the licence the source declares permits use/redistribution,
 *  - the file comes from an allow-listed source over an allow-listed host,
 *  - the bytes we downloaded match the checksum the source published,
 *  - the archive is structurally safe (no traversal, no links, no bombs) and
 *    carries only file types that make sense for the game,
 *  - the hash is not on our known-bad list,
 *  - the listing is complete enough for a customer to know what it is,
 *  - the build declares support for the game version it was checked on,
 *  - and (separately, lib/mod-verify/smoke.ts) it installed and the game
 *    started with it loaded on a throwaway server.
 * It is NOT a code audit or a malware guarantee and nothing may say it is.
 *
 * Result vocabulary:
 *   pass    — the check succeeded
 *   fail    — the check found something actively wrong (hash mismatch, unsafe
 *             archive, blocked hash, crash on start). Any fail => FLAGGED.
 *   unmet   — we can't confirm it (no published hash, restrictive licence,
 *             missing metadata). Blocks VERIFIED; does NOT flag.
 *   warn    — informational; never blocks.
 *   pending — not run yet (the smoke test, before the owner runs it).
 *   skipped — not applicable.
 */
import { isRedistributable, normalizeLicense } from "../modsync/license";
import { readZip, isZip, ArchiveError, type ArchiveLimits } from "../mods/archive";
import { hostAllowed, MOD_HOSTS } from "../mods/safe-fetch";

export type CheckResult = "pass" | "fail" | "unmet" | "warn" | "pending" | "skipped";
export type CheckOutcome = { result: CheckResult; detail: string; at?: string };

export const CHECK_NAMES = ["license", "source", "integrity", "archive", "blocklist", "metadata", "compat", "smoke"] as const;
export type CheckName = (typeof CHECK_NAMES)[number];
export type Checks = Partial<Record<CheckName, CheckOutcome>>;

/** Customer-facing labels, in the order the popover lists them. */
export const CHECK_LABEL: Record<CheckName, string> = {
  smoke: "Installed and started on a test server",
  license: "Licence permits use",
  integrity: "File matches the source's checksum",
  source: "Downloaded from an approved source",
  archive: "Archive structure and file types checked",
  blocklist: "Not on our known-bad file list",
  compat: "Declares support for this game version",
  metadata: "Listing is complete",
};

/**
 * Sources whose files we fetch from a first-party API with stable ids. A mod
 * from anywhere else (manual links, scraped pages) can still be listed and
 * installed by hand, but is never eligible for the badge.
 */
export const VERIFIABLE_SOURCES = new Set(["modrinth", "hangar", "thunderstore", "umod", "github", "factorio_portal", "ficsit"]);

/** Families whose servers run a specific, comparable game version string. */
export const VERSIONED_FAMILIES = new Set(["minecraft", "factorio"]);

const now = () => new Date().toISOString();
const o = (result: CheckResult, detail: string): CheckOutcome => ({ result, detail, at: now() });

// ── licence ──────────────────────────────────────────────────────────────────
export function checkLicense(license: string | null | undefined): CheckOutcome {
  const l = normalizeLicense(license);
  if (!l) return o("unmet", "The source doesn't publish a licence for this project.");
  if (isRedistributable(l)) return o("pass", `${l} — an open licence that permits use and redistribution.`);
  return o("unmet", `${l} — not an open licence we can confirm permits redistribution.`);
}

// ── source ───────────────────────────────────────────────────────────────────
export function checkSource(source: string, fileUrl: string | null | undefined, allow: readonly string[] = MOD_HOSTS): CheckOutcome {
  if (!VERIFIABLE_SOURCES.has(source)) return o("unmet", `${source} isn't one of the sources we verify files from.`);
  if (!fileUrl) return o("unmet", "The source lists no direct download for this build.");
  let u: URL;
  try {
    u = new URL(fileUrl);
  } catch {
    return o("fail", "The build's download link isn't a valid URL.");
  }
  if (u.protocol !== "https:") return o("fail", "The build's download link isn't HTTPS.");
  if (!hostAllowed(u.hostname, allow)) return o("fail", `The download host ${u.hostname} isn't on our allow-list for ${source}.`);
  return o("pass", `Fetched over HTTPS from ${u.hostname}.`);
}

// ── integrity ────────────────────────────────────────────────────────────────
export type HashSet = { sha1?: string | null; sha256?: string | null; sha512?: string | null };

/** Compare what the source published with what we computed from the bytes. */
export function checkIntegrity(declared: HashSet, computed: { sha1: string; sha256: string; sha512: string } | null): CheckOutcome {
  if (!computed) return o("pending", "The file hasn't been downloaded and hashed yet.");
  const pairs = (["sha512", "sha256", "sha1"] as const).filter((k) => !!declared[k]);
  if (pairs.length === 0) return o("unmet", "The source publishes no checksum for this file, so its integrity can't be confirmed.");
  for (const k of pairs) {
    if (String(declared[k]).toLowerCase() !== computed[k]) return o("fail", `${k.toUpperCase()} mismatch — the downloaded file is not what the source published.`);
  }
  return o("pass", `${pairs.map((k) => k.toUpperCase()).join(" + ")} match the source's published checksum.`);
}

// ── blocklist ────────────────────────────────────────────────────────────────
export function checkBlocklist(computed: { sha1: string; sha256: string; sha512: string } | null, declared: HashSet, blocked: ReadonlySet<string>): CheckOutcome {
  const all = [computed?.sha1, computed?.sha256, computed?.sha512, declared.sha1, declared.sha256, declared.sha512]
    .filter((x): x is string => !!x)
    .map((x) => x.toLowerCase());
  if (all.length === 0) return o("pending", "No hash to compare yet.");
  const hit = all.find((h) => blocked.has(h));
  if (hit) return o("fail", `This file's hash (${hit.slice(0, 12)}…) is on our known-bad list.`);
  return o("pass", "Not on our known-bad file list.");
}

// ── archive safety ───────────────────────────────────────────────────────────
/** Top-level file types a family's installer is expected to place. */
const TOP_LEVEL: Record<string, string[]> = {
  minecraft: [".jar", ".zip", ".mrpack"],
  valheim: [".zip", ".dll"],
  rust: [".cs", ".zip"],
  cs2: [".zip", ".dll", ".so"],
  factorio: [".zip"],
  satisfactory: [".smod", ".zip"],
  vintagestory: [".zip", ".cs", ".dll"],
};
/** Native code that a family's mods legitimately ship (else: warn). */
const NATIVE_OK: Record<string, string[]> = {
  valheim: [".dll"],
  cs2: [".dll", ".so"],
  vintagestory: [".dll"],
  satisfactory: [".dll", ".pak", ".utoc", ".ucas"],
};
/** Never expected inside a game-server mod; blocks the badge (not a flag — some packs ship launch scripts). */
const SCRIPT_EXEC = [".exe", ".bat", ".cmd", ".ps1", ".vbs", ".scr", ".msi", ".com", ".sh", ".command", ".jse", ".wsf"];
const NATIVE_ANY = [".dll", ".so", ".dylib"];

const ext = (n: string) => {
  const i = n.lastIndexOf(".");
  return i > n.lastIndexOf("/") && i >= 0 ? n.slice(i).toLowerCase() : "";
};

/** Entry names that would escape a folder if anything ever extracted them. */
export function isTraversalName(name: string): boolean {
  const n = name.replace(/\\/g, "/");
  return n.startsWith("/") || /^[A-Za-z]:/.test(n) || n.split("/").some((s) => s === "..") || n.includes("\0");
}

export const VERIFY_ARCHIVE_LIMITS: ArchiveLimits = {
  maxEntries: 20_000,
  maxEntryBytes: 256 * 1024 * 1024,
  maxTotalBytes: 768 * 1024 * 1024,
  maxRatio: 250,
};

/**
 * Structural + content-type check of the downloaded file. `names` is an
 * injectable lister (tests); by default the ZIP central directory is parsed
 * with lib/mods/archive.ts (CRC, bombs, links, ratio caps all enforced there).
 */
export function checkArchive(family: string, fileName: string | null | undefined, bytes: Buffer | null, limits: ArchiveLimits = VERIFY_ARCHIVE_LIMITS): CheckOutcome {
  if (!bytes) return o("pending", "The file hasn't been downloaded yet.");
  const top = ext(fileName ?? "");
  const allowedTop = TOP_LEVEL[family];
  if (allowedTop && top && !allowedTop.includes(top)) return o("unmet", `A ${top} file isn't a type we expect for ${family} mods.`);
  if (SCRIPT_EXEC.includes(top)) return o("unmet", `The download is an executable/script (${top}).`);
  if (!isZip(bytes)) {
    // Single non-archive files (a uMod .cs plugin, a bare .dll) — nothing to unpack.
    return o("pass", `Single ${top || "file"} (${bytes.length.toLocaleString()} bytes), nothing to unpack.`);
  }
  let names: string[];
  try {
    // strictPaths:false so we can REPORT a traversal name instead of a generic error;
    // links, bombs, CRC and size caps are still enforced by readZip.
    names = readZip(bytes, limits, { strictPaths: false, only: () => false }).map((e) => e.path.join("/"));
  } catch (e) {
    const msg = e instanceof ArchiveError ? e.message : "unreadable archive";
    return o("fail", `Archive rejected: ${msg}.`);
  }
  const bad = names.find(isTraversalName);
  if (bad) return o("fail", `Archive contains a path that escapes its folder (${bad.slice(0, 80)}).`);
  const scripts = names.filter((n) => SCRIPT_EXEC.includes(ext(n)));
  if (scripts.length) return o("unmet", `Archive ships ${scripts.length} executable/script file(s) (e.g. ${scripts[0].slice(0, 60)}).`);
  const natives = names.filter((n) => NATIVE_ANY.includes(ext(n)) && !(NATIVE_OK[family] ?? []).includes(ext(n)));
  if (natives.length) return o("warn", `${names.length.toLocaleString()} entries checked; includes ${natives.length} native librar${natives.length === 1 ? "y" : "ies"} (common for bundled database drivers).`);
  return o("pass", `${names.length.toLocaleString()} entries checked: no traversal, links or oversized entries.`);
}

// ── metadata completeness ────────────────────────────────────────────────────
export type MetaInput = {
  name?: string | null;
  description?: string | null;
  license?: string | null;
  authorName?: string | null;
  iconUrl?: string | null;
  iconKey?: string | null;
  versionNumber?: string | null;
  fileName?: string | null;
  fileBytes?: number | null;
};
export function checkMetadata(m: MetaInput): CheckOutcome {
  const missing: string[] = [];
  if (!m.name?.trim()) missing.push("name");
  if (!m.description?.trim()) missing.push("summary");
  if (!m.license?.trim()) missing.push("licence");
  if (!m.authorName?.trim()) missing.push("author");
  if (!m.iconUrl && !m.iconKey) missing.push("icon");
  if (!m.versionNumber?.trim()) missing.push("version");
  if (!m.fileName?.trim()) missing.push("file name");
  if (!m.fileBytes || m.fileBytes <= 0) missing.push("file size");
  if (missing.length === 0) return o("pass", "Name, summary, licence, author, icon, version and file details are all present.");
  return o("unmet", `Missing from the listing: ${missing.join(", ")}.`);
}

// ── version compatibility ────────────────────────────────────────────────────
export function checkCompat(family: string, gameVersion: string, versionGameVersions: string[], loader: string, versionLoaders: string[], acceptedLoaders: string[] = loader ? [loader] : []): CheckOutcome {
  const versioned = VERSIONED_FAMILIES.has(family);
  if (versioned) {
    if (!gameVersion || gameVersion === "any") return o("unmet", "No game version chosen to verify against.");
    if (!versionGameVersions.includes(gameVersion)) return o("unmet", `This build doesn't declare support for ${gameVersion}.`);
  }
  if (loader && versionLoaders.length > 0 && !versionLoaders.some((l) => acceptedLoaders.includes(l) || l === "datapack")) {
    return o("unmet", `This build targets ${versionLoaders.slice(0, 4).join(", ")}, not ${loader}.`);
  }
  return o("pass", versioned ? `Declares ${gameVersion}${loader ? ` on ${loader}` : ""}.` : "This game has no version list; the install test is the compatibility check.");
}

// ── smoke test (recorded by lib/mod-verify/smoke.ts) ─────────────────────────
export function smokeOutcome(r: { installed: boolean; started: boolean; loaded: boolean | null; crashed: boolean; detail: string }): CheckOutcome {
  if (r.crashed) return o("fail", `Server crashed with the mod installed: ${r.detail}`);
  if (!r.installed) return o("unmet", `Install did not complete: ${r.detail}`);
  if (!r.started) return o("fail", `Game did not start with the mod installed: ${r.detail}`);
  if (r.loaded === false) return o("unmet", `Game started but we couldn't see the mod load: ${r.detail}`);
  return o("pass", r.detail);
}

export const PENDING_SMOKE: CheckOutcome = { result: "pending", detail: "Waiting for the install test on a throwaway server." };

