  let names: string[];
  try {
    // strictPaths:false so we can REPORT a traversal name instead of a generic error;
    // links, bombs, CRC and size caps are still enforced by readZip.
    names = readZip(bytes, limits, { strictPaths: false, only: () => false }).map((e) => e.path.join("/"));
  } catch (e) {
    const msg = e instanceof ArchiveError ? e.message : "unreadable archive";
    return o("fail", `Archive rejected: ${msg}.`);
  }
  const bad = names.find(isTraversalName);
  if (bad) return o("fail", `Archive contains a path that escapes its folder (${bad.slice(0, 80)}).`);
  const scripts = names.filter((n) => SCRIPT_EXEC.includes(ext(n)));
  if (scripts.length) return o("unmet", `Archive ships ${scripts.length} executable/script file(s) (e.g. ${scripts[0].slice(0, 60)}).`);
  const natives = names.filter((n) => NATIVE_ANY.includes(ext(n)) && !(NATIVE_OK[family] ?? []).includes(ext(n)));
  if (natives.length) return o("warn", `${names.length.toLocaleString()} entries checked; includes ${natives.length} native librar${natives.length === 1 ? "y" : "ies"} (common for bundled database drivers).`);
  return o("pass", `${names.length.toLocaleString()} entries checked: no traversal, links or oversized entries.`);
}

// ── metadata completeness ────────────────────────────────────────────────────
export type MetaInput = {
  name?: string | null;
  description?: string | null;
  license?: string | null;
  authorName?: string | null;
  iconUrl?: string | null;
  iconKey?: string | null;
  versionNumber?: string | null;
  fileName?: string | null;
  fileBytes?: number | null;
};
export function checkMetadata(m: MetaInput): CheckOutcome {
  const missing: string[] = [];
  if (!m.name?.trim()) missing.push("name");
  if (!m.description?.trim()) missing.push("summary");
  if (!m.license?.trim()) missing.push("licence");
  if (!m.authorName?.trim()) missing.push("author");
  if (!m.iconUrl && !m.iconKey) missing.push("icon");
  if (!m.versionNumber?.trim()) missing.push("version");
  if (!m.fileName?.trim()) missing.push("file name");
  if (!m.fileBytes || m.fileBytes <= 0) missing.push("file size");
  if (missing.length === 0) return o("pass", "Name, summary, licence, author, icon, version and file details are all present.");
  return o("unmet", `Missing from the listing: ${missing.join(", ")}.`);
}

// ── version compatibility ────────────────────────────────────────────────────
export function checkCompat(family: string, gameVersion: string, versionGameVersions: string[], loader: string, versionLoaders: string[], acceptedLoaders: string[] = loader ? [loader] : []): CheckOutcome {
  const versioned = VERSIONED_FAMILIES.has(family);
  if (versioned) {
    if (!gameVersion || gameVersion === "any") return o("unmet", "No game version chosen to verify against.");
    if (!versionGameVersions.includes(gameVersion)) return o("unmet", `This build doesn't declare support for ${gameVersion}.`);
  }
  if (loader && versionLoaders.length > 0 && !versionLoaders.some((l) => acceptedLoaders.includes(l) || l === "datapack")) {
    return o("unmet", `This build targets ${versionLoaders.slice(0, 4).join(", ")}, not ${loader}.`);
  }
  return o("pass", versioned ? `Declares ${gameVersion}${loader ? ` on ${loader}` : ""}.` : "This game has no version list; the install test is the compatibility check.");
}

// ── smoke test (recorded by lib/mod-verify/smoke.ts) ─────────────────────────
export function smokeOutcome(r: { installed: boolean; started: boolean; loaded: boolean | null; crashed: boolean; detail: string }): CheckOutcome {
  if (r.crashed) return o("fail", `Server crashed with the mod installed: ${r.detail}`);
  if (!r.installed) return o("unmet", `Install did not complete: ${r.detail}`);
  if (!r.started) return o("fail", `Game did not start with the mod installed: ${r.detail}`);
  if (r.loaded === false) return o("unmet", `Game started but we couldn't see the mod load: ${r.detail}`);
  return o("pass", r.detail);
}

export const PENDING_SMOKE: CheckOutcome = { result: "pending", detail: "Waiting for the install test on a throwaway server." };

