/**
 * Nxeon Verified — status derivation, expiry and the exact badge copy.
 * Pure: shared by the runner, the admin queue, the customer browser and the
 * marketing pages, so all of them agree on what the badge means.
 */
import { CHECK_LABEL, CHECK_NAMES, type CheckName, type CheckOutcome, type Checks } from "./checks";

export type VerifyStatus = "UNVERIFIED" | "VERIFIED" | "FLAGGED" | "REVOKED";
export const VERIFY_STATUSES: readonly VerifyStatus[] = ["UNVERIFIED", "VERIFIED", "FLAGGED", "REVOKED"];

/** A verification lapses after this long even if nothing changed upstream. */
export const VERIFY_TTL_DAYS = 30;

/** Every one of these must be "pass" (warn is allowed only where noted) for VERIFIED. */
export const REQUIRED_CHECKS: readonly CheckName[] = CHECK_NAMES;

/**
 * VERIFIED only when every required check passed (archive may be "warn") and
 * the smoke test passed. Any "fail" => FLAGGED for review. REVOKED is sticky:
 * only an admin clears it, never a re-run.
 */
export function deriveStatus(checks: Checks, prev?: VerifyStatus | string | null): VerifyStatus {
  if (prev === "REVOKED") return "REVOKED";
  const vals = Object.values(checks).filter(Boolean) as CheckOutcome[];
  if (vals.some((c) => c.result === "fail")) return "FLAGGED";
  const ok = REQUIRED_CHECKS.every((k) => {
    const r = checks[k]?.result;
    return r === "pass" || (k === "archive" && r === "warn");
  });
  return ok ? "VERIFIED" : "UNVERIFIED";
}

export function expiryFrom(verifiedAt: Date, days = VERIFY_TTL_DAYS): Date {
  return new Date(verifiedAt.getTime() + days * 86_400_000);
}

export type BadgeRow = {
  status: string;
  gameVersion: string;
  loader?: string | null;
  verifiedAt: Date | string | null;
  expiresAt: Date | string | null;
  versionNumber?: string | null;
  checks?: unknown;
};

const toDate = (d: Date | string | null | undefined) => (d ? (d instanceof Date ? d : new Date(d)) : null);

/** The badge renders ONLY for a VERIFIED row that has not expired. */
export function isBadgeLive(v: BadgeRow | null | undefined, at: Date = new Date()): boolean {
  if (!v || v.status !== "VERIFIED") return false;
  const exp = toDate(v.expiresAt);
  const ver = toDate(v.verifiedAt);
  return !!exp && !!ver && exp.getTime() > at.getTime();
}

export function fmtDate(d: Date | string | null | undefined): string {
  const x = toDate(d);
  return x ? x.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" }) : "";
}

/**
 * The ONE sentence the badge is allowed to say. It names exactly what was
 * done, on what, and when — and stops there. Not a security guarantee.
 */
export function badgeSentence(gameName: string, v: BadgeRow): string {
  const ver = v.gameVersion && v.gameVersion !== "any" ? ` ${v.gameVersion}` : "";
  const loader = v.loader ? ` (${v.loader})` : "";
  return `Nxeon Verified: installed and started successfully on ${gameName}${ver}${loader} on ${fmtDate(v.verifiedAt)}; licence and file integrity checked.`;
}

export const BADGE_DISCLAIMER =
  "This is a compatibility and integrity check, not a security audit of the mod's code. It expires automatically and is re-checked when the game or the mod updates.";

/** Ordered, labelled checks for the popover / admin view (unknown keys ignored). */
export function checkList(raw: unknown): { key: CheckName; label: string; result: string; detail: string }[] {
  const c = (raw && typeof raw === "object" ? raw : {}) as Record<string, CheckOutcome | undefined>;
  const order: CheckName[] = ["smoke", "license", "integrity", "source", "archive", "blocklist", "compat", "metadata"];
  return order
    .filter((k) => c[k] && typeof c[k] === "object")
    .map((k) => ({ key: k, label: CHECK_LABEL[k], result: String(c[k]!.result ?? "pending"), detail: String(c[k]!.detail ?? "").slice(0, 400) }));
}

/** Days until expiry (negative once lapsed), for admin stats. */
export function daysLeft(v: BadgeRow, at: Date = new Date()): number | null {
  const e = toDate(v.expiresAt);
  return e ? Math.floor((e.getTime() - at.getTime()) / 86_400_000) : null;
}

