/**
 * Nxeon Verified — INSTALL SMOKE TEST harness.
 *
 * SPEC (what one smoke run does, in order; every step is bounded and logged):
 *   1. provision  — order a throwaway game server of the mod's family on a
 *                   NON-primary node through the normal order path (the same
 *                   placeGameOrder + PROVISION job the QA sweep uses), owned by
 *                   the internal QA account, hostname prefixed `qa-modverify-`.
 *   2. pin        — set the server's variant/loader + game version to the
 *                   verification target and let the worker apply it.
 *   3. install    — queue the real GAME_MOD_SYNC install (lib/mods/queue.ts),
 *                   exactly what a customer's Install button does, and wait.
 *   4. start      — queue GAME_POWER restart and wait for it.
 *   5. probe      — read the game's own logs (lib/game-control.ts readGameLogs)
 *                   and decide started / loaded / crashed (evaluateSmokeLog).
 *   6. teardown   — ALWAYS (finally): DELETE job for the throwaway server.
 *   7. record     — write the `smoke` check (lib/mod-verify/store.ts), which is
 *                   what can flip a row to VERIFIED.
 *
 * The orchestration takes its infrastructure as an interface (SmokeInfra) so
 * the sequence — including "teardown runs even when install throws" — is unit
 * tested without touching a node. The real implementation lives in
 * scripts/mod-verify.ts and is run BY THE OWNER, never by the web app.
 */
import { smokeOutcome, type CheckOutcome } from "./checks";

export type SmokeTarget = {
  taskId: string;
  gameModId: string;
  modName: string;
  modSlug: string;
  /** Upstream id when it differs from slug (Modrinth project id, Thunderstore Owner-Name). */
  sourceId: string | null;
  family: string;
  gameVersion: string;
  loader: string;
};

export interface SmokeInfra {
  provision(t: SmokeTarget): Promise<{ serverId: string } | { error: string }>;
  install(serverId: string, t: SmokeTarget): Promise<{ ok: true; detail: string } | { ok: false; error: string }>;
  restart(serverId: string): Promise<{ ok: true } | { ok: false; error: string }>;
  readLog(serverId: string, family: string): Promise<string>;
  teardown(serverId: string): Promise<void>;
  log?(msg: string): void;
}

export type SmokeReport = {
  serverId: string | null;
  installed: boolean;
  started: boolean;
  loaded: boolean | null;
  crashed: boolean;
  detail: string;
  steps: { step: string; ok: boolean; note?: string; ms: number }[];
  outcome: CheckOutcome;
  tornDown: boolean;
};

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

type Probe = { started: RegExp[]; crash: RegExp[]; loaded: (t: SmokeTarget) => RegExp[] };

/** Per-family log markers. Families without one can't be smoke-tested yet. */
export const SMOKE_PROBES: Record<string, Probe> = {
  minecraft: {
    started: [/Done \([\d.,]+s\)! For help, type/],
    crash: [/This crash report has been saved/i, /Encountered an unexpected exception/i, /Exception in server tick loop/i, /Failed to start the minecraft server/i],
    loaded: (t) => {
      const n = esc(t.modName);
      const s = esc(t.modSlug);
      return [
        new RegExp(`\\[${n}\\] Enabling ${n}`, "i"), // Bukkit/Paper plugin enable
        new RegExp(`Loading server plugin ${n}\\b`, "i"),
        new RegExp(`^\\s*-\\s*${s}\\s+[0-9]`, "mi"), // Fabric "Loading N mods:" list
        new RegExp(`^\\s*-\\s*${s.replace(/-/g, "_")}\\s+[0-9]`, "mi"),
        new RegExp(`Mod\\s+${s}\\s`, "i"), // Forge mod list
      ];
    },
  },
  valheim: {
    started: [/Game server connected/i, /Session ".*" with join code/i, /Opened Steam server/i],
    crash: [/Crash!!!/, /Unhandled exception/i],
    loaded: (t) => [new RegExp(`Loading \\[${esc(t.modName)}\\s`, "i"), new RegExp(`Loading \\[${esc((t.sourceId ?? "").split("-").slice(1).join("-") || t.modName)}\\s`, "i")],
  },
  rust: {
    started: [/Server startup complete/i, /SteamServer Connected/i],
    crash: [/Unhandled Exception/i, /Crash in/i],
    loaded: (t) => [new RegExp(`Loaded plugin ${esc(t.modName)}\\b`, "i"), new RegExp(`Loaded plugin ${esc(t.sourceId ?? t.modSlug)}\\b`, "i")],
  },
};

/** Decide started / loaded / crashed from the game's own log text. Pure. */
export function evaluateSmokeLog(t: SmokeTarget, log: string): { started: boolean; loaded: boolean | null; crashed: boolean; detail: string } {
  const p = SMOKE_PROBES[t.family];
  if (!p) return { started: false, loaded: null, crashed: false, detail: `No load probe for ${t.family} yet.` };
  const crashed = p.crash.some((r) => r.test(log));
  const started = p.started.some((r) => r.test(log));
  const loadedLine = log.split(/\r?\n/).find((l) => p.loaded(t).some((r) => r.test(l)) && !/\b(error|failed|could not|exception)\b/i.test(l));
  const loaded = loadedLine ? true : false;
  const detail = crashed
    ? (log.split(/\r?\n/).find((l) => p.crash.some((r) => r.test(l))) ?? "crash marker in log").trim().slice(0, 200)
    : started && loaded
      ? `Server reached ready state and logged: ${loadedLine!.trim().slice(0, 160)}`
      : started
        ? "Server reached ready state, but no load line for this mod was found."
        : "Server never logged its ready line.";
  return { started, loaded, crashed, detail };
}

export function smokeSupported(family: string): boolean {
  return !!SMOKE_PROBES[family];
}

/** Run one smoke test. Teardown always runs once a server exists. */
export async function runSmoke(t: SmokeTarget, infra: SmokeInfra): Promise<SmokeReport> {
  const steps: SmokeReport["steps"] = [];
  const step = async <T>(name: string, fn: () => Promise<T>, ok: (r: T) => boolean, note?: (r: T) => string | undefined): Promise<T> => {
    const t0 = Date.now();
    const r = await fn();
    steps.push({ step: name, ok: ok(r), note: note?.(r), ms: Date.now() - t0 });
    infra.log?.(`[smoke ${t.taskId}] ${name}: ${ok(r) ? "ok" : "FAILED"}${note?.(r) ? ` — ${note(r)}` : ""}`);
    return r;
  };
  const rep: SmokeReport = { serverId: null, installed: false, started: false, loaded: null, crashed: false, detail: "", steps, outcome: { result: "pending", detail: "" }, tornDown: false };

  if (!smokeSupported(t.family)) {
    rep.detail = `No load probe for ${t.family} yet.`;
