/**
 * Nxeon Verified — persistence. The only module that writes ModVerification /
 * ModVerifyTask / ModBlockedHash. Callers: scripts/mod-verify.ts (runner),
 * lib/actions-admin-mod-verify.ts (admin queue), lib/mods-browse.ts (reads).
 */
import type { Prisma } from "@prisma/client";
import { db } from "../db";
import type { Checks } from "./checks";
import { deriveStatus, expiryFrom, isBadgeLive, type BadgeRow, type VerifyStatus } from "./status";

export type VerifyKey = { gameModId: string; modVersionId: string | null; gameVersion: string; loader: string };

/** Normalise the key the same way everywhere ("" for no loader, "any" for no version). */
export function normKey(k: { gameModId: string; modVersionId?: string | null; gameVersion?: string | null; loader?: string | null }): VerifyKey {
  return {
    gameModId: k.gameModId,
    modVersionId: k.modVersionId ?? null,
    gameVersion: (k.gameVersion ?? "").trim() || "any",
    loader: (k.loader ?? "").trim().toLowerCase(),
  };
}

async function findRow(k: VerifyKey) {
  return db.modVerification.findFirst({ where: { gameModId: k.gameModId, modVersionId: k.modVersionId, gameVersion: k.gameVersion, loader: k.loader } });
}

/**
 * Merge new check outcomes into the row for this key and re-derive status.
 * VERIFIED stamps verifiedAt/expiresAt; leaving VERIFIED clears them.
 */
export async function recordChecks(
  key: VerifyKey,
  meta: { gameFamily: string; versionNumber?: string | null; by?: string },
  checks: Checks,
): Promise<{ id: string; status: VerifyStatus }> {
  const prev = await findRow(key);
  const merged: Checks = { ...((prev?.checks as Checks | null) ?? {}), ...checks };
  const status = deriveStatus(merged, prev?.status);
  const now = new Date();
  const becameVerified = status === "VERIFIED" && (prev?.status !== "VERIFIED" || !isBadgeLive(prev as BadgeRow));
  const data = {
    checks: merged as Prisma.InputJsonValue,
    status,
    versionNumber: meta.versionNumber ?? prev?.versionNumber ?? null,
    gameFamily: meta.gameFamily,
    verifiedBy: meta.by ?? "system",
    ...(status === "VERIFIED"
      ? becameVerified || checks.smoke
        ? { verifiedAt: now, expiresAt: expiryFrom(now) }
        : {}
      : { verifiedAt: null, expiresAt: null }),
  };
  if (prev) {
    const r = await db.modVerification.update({ where: { id: prev.id }, data, select: { id: true, status: true } });
    return { id: r.id, status: r.status as VerifyStatus };
  }
  const r = await db.modVerification.create({ data: { ...key, ...data }, select: { id: true, status: true } });
  return { id: r.id, status: r.status as VerifyStatus };
}

export async function revokeVerification(id: string, reason: string, by: string) {
  return db.modVerification.update({
    where: { id },
    data: { status: "REVOKED", revokedAt: new Date(), revokedReason: reason.slice(0, 500), verifiedBy: by, expiresAt: new Date() },
  });
}

export async function flagVerification(id: string, reason: string, by: string) {
  const row = await db.modVerification.findUnique({ where: { id } });
  if (!row) return null;
  const checks = { ...((row.checks as Checks | null) ?? {}) };
  return db.modVerification.update({
    where: { id },
    data: { status: "FLAGGED", notes: `Flagged by admin: ${reason}`.slice(0, 1000), verifiedBy: by, expiresAt: null, verifiedAt: null, checks: checks as Prisma.InputJsonValue },
  });
}

/** Clear a revoke/flag: back to UNVERIFIED with the smoke test reset — it must re-earn the badge. */
export async function resetVerification(id: string, by: string) {
  const row = await db.modVerification.findUnique({ where: { id } });
  if (!row) return null;
  const checks = { ...((row.checks as Checks | null) ?? {}) };
  delete checks.smoke;
  return db.modVerification.update({
    where: { id },
    data: { status: "UNVERIFIED", revokedAt: null, revokedReason: null, verifiedAt: null, expiresAt: null, verifiedBy: by, checks: checks as Prisma.InputJsonValue },
  });
}

/**
 * Lapse every live badge for a game (optionally one version) — call when the
 * game itself updates so a badge earned on the old build never shows on the
 * new one. Returns how many badges were lapsed.
 */
export async function lapseForGameUpdate(gameFamily: string, gameVersion?: string, note = "Game updated — needs re-verification"): Promise<number> {
  const r = await db.modVerification.updateMany({
    where: { gameFamily, status: "VERIFIED", expiresAt: { gt: new Date() }, ...(gameVersion ? { gameVersion } : {}) },
    data: { expiresAt: new Date(), notes: note },
  });
  return r.count;
}

/** Lapse every badge for one mod (its upstream published a new build). */
export async function lapseForMod(gameModId: string, note = "New upstream build — needs re-verification") {
  return db.modVerification.updateMany({ where: { gameModId, status: "VERIFIED", expiresAt: { gt: new Date() } }, data: { expiresAt: new Date(), notes: note } });
}

// ── queue ────────────────────────────────────────────────────────────────────
export type TaskKind = "PREFLIGHT" | "SMOKE";

/** Queue a task unless an identical one is already waiting/running. */
export async function enqueueVerifyTask(kind: TaskKind, k: VerifyKey & { gameFamily: string }, requestedBy: string | null): Promise<{ id: string; created: boolean }> {
  const dup = await db.modVerifyTask.findFirst({
    where: { kind, gameModId: k.gameModId, modVersionId: k.modVersionId, gameVersion: k.gameVersion, loader: k.loader, status: { in: ["QUEUED", "RUNNING"] } },
    select: { id: true },
  });
  if (dup) return { id: dup.id, created: false };
  const t = await db.modVerifyTask.create({
    data: { kind, gameModId: k.gameModId, modVersionId: k.modVersionId, gameFamily: k.gameFamily, gameVersion: k.gameVersion, loader: k.loader, requestedBy },
    select: { id: true },
  });
  return { id: t.id, created: true };
}

/** Atomically claim the oldest QUEUED task of a kind (safe with several runners). */
export async function claimTask(kind: TaskKind, family?: string) {
  const cand = await db.modVerifyTask.findFirst({ where: { kind, status: "QUEUED", ...(family ? { gameFamily: family } : {}) }, orderBy: { createdAt: "asc" } });
  if (!cand) return null;
  const c = await db.modVerifyTask.updateMany({ where: { id: cand.id, status: "QUEUED" }, data: { status: "RUNNING", startedAt: new Date(), attempts: { increment: 1 } } });
  return c.count === 1 ? { ...cand, status: "RUNNING" } : null;
}

export async function finishTask(id: string, status: "PASSED" | "FAILED" | "ERROR", result: unknown, error?: string | null, serverId?: string | null) {
  return db.modVerifyTask.update({
    where: { id },
    data: { status, result: (result ?? null) as Prisma.InputJsonValue, error: error ? error.slice(0, 1000) : null, finishedAt: new Date(), ...(serverId !== undefined ? { serverId } : {}) },
  });
}

// ── blocklist ────────────────────────────────────────────────────────────────
export async function blockedHashes(): Promise<Set<string>> {
  const rows = await db.modBlockedHash.findMany({ select: { hash: true } });
  return new Set(rows.map((r) => r.hash.toLowerCase()));
}

export const HASH_RE = /^(?:[a-f0-9]{40}|[a-f0-9]{64}|[a-f0-9]{128})$/;

// ── reads for the browser / marketing ────────────────────────────────────────
export type LiveBadge = BadgeRow & { id: string; gameModId: string; gameFamily: string; checks: unknown };

/**
 * Live (VERIFIED + unexpired) verifications for these mods. With `gameVersion`
 * only rows for that version (or "any") count; with `loaders` a row pinned to
 * a loader must be one of them. Newest first per mod.
 */
export async function liveBadges(modIds: string[], opts: { gameVersion?: string | null; loaders?: string[] } = {}): Promise<Map<string, LiveBadge>> {
  if (modIds.length === 0) return new Map();
  const rows = await db.modVerification.findMany({
    where: {
      gameModId: { in: modIds },
      status: "VERIFIED",
      expiresAt: { gt: new Date() },
      ...(opts.gameVersion ? { gameVersion: { in: [opts.gameVersion, "any"] } } : {}),
    },
    orderBy: { verifiedAt: "desc" },
  });
  const out = new Map<string, LiveBadge>();
  for (const r of rows) {
    if (opts.loaders && r.loader && !opts.loaders.includes(r.loader)) continue;
    if (!out.has(r.gameModId)) out.set(r.gameModId, r as LiveBadge);
  }
  return out;
}

/** Mod ids with a live badge for a family (bounded: verification is expensive, the set is small). */
export async function liveVerifiedModIds(gameFamily: string, opts: { gameVersion?: string | null; loaders?: string[] } = {}): Promise<string[]> {
  const rows = await db.modVerification.findMany({
    where: { gameFamily, status: "VERIFIED", expiresAt: { gt: new Date() }, ...(opts.gameVersion ? { gameVersion: { in: [opts.gameVersion, "any"] } } : {}) },
    select: { gameModId: true, loader: true },
    take: 5000,
  });
  return [...new Set(rows.filter((r) => !opts.loaders || !r.loader || opts.loaders.includes(r.loader)).map((r) => r.gameModId))];
}

