/**
 * Nxeon Verified — PREFLIGHT: everything that can be checked without a game
 * server. Downloads the build once (allow-listed hosts only, size-capped, via
 * the installer's own safeFetch), hashes it, inspects the archive, and records
 * the license/source/integrity/archive/blocklist/metadata/compat checks.
 *
 * When every preflight check passes (archive may warn) a SMOKE task is queued
 * for the same key — the owner's runner (scripts/mod-verify.ts) picks it up.
 * Network only; never touches a node. Runs from scripts/mod-verify.ts.
 */
import type { GameMod, ModVersion } from "@prisma/client";
import { db } from "../db";
import { hashAll, type Fetcher } from "../mods/safe-fetch";
import { acceptedLoaders } from "../mods/installers/minecraft";
import {
  checkArchive,
  checkBlocklist,
  checkCompat,
  checkIntegrity,
  checkLicense,
  checkMetadata,
  checkSource,
  PENDING_SMOKE,
  VERSIONED_FAMILIES,
  type Checks,
} from "./checks";
import { blockedHashes, enqueueVerifyTask, recordChecks, normKey, type VerifyKey } from "./store";

const MAX_DOWNLOAD = 150 * 1024 * 1024;

/** Loaders a smoke server of `loader` would accept (Minecraft has a real ladder; others: itself). */
export function loadersFor(family: string, loader: string): string[] {
  if (!loader) return [];
  return family === "minecraft" ? acceptedLoaders(loader) : [loader];
}

/** Pick the newest build that declares the target game version + loader. */
export function pickVersion(versions: Pick<ModVersion, "id" | "gameVersions" | "loaders" | "channel" | "publishedAt">[], family: string, gameVersion: string, loader: string) {
  const acc = loadersFor(family, loader);
  const ok = versions.filter(
    (v) =>
      (!VERSIONED_FAMILIES.has(family) || gameVersion === "any" || v.gameVersions.includes(gameVersion)) &&
      (!loader || v.loaders.length === 0 || v.loaders.some((l) => acc.includes(l) || l === "datapack")),
  );
  const rank = (c: string) => (c === "release" ? 0 : c === "beta" ? 1 : 2);
  return ok.sort((a, b) => rank(a.channel) - rank(b.channel) || (b.publishedAt?.getTime() ?? 0) - (a.publishedAt?.getTime() ?? 0))[0] ?? null;
}

export type PreflightResult = { key: VerifyKey; status: string; checks: Checks; smokeQueued: boolean; error?: string };

export async function runPreflight(
  input: { gameModId: string; modVersionId?: string | null; gameVersion: string; loader: string; requestedBy?: string | null },
  deps: { fetcher: Fetcher; blocked?: Set<string> },
): Promise<PreflightResult> {
  const mod = (await db.gameMod.findUnique({ where: { id: input.gameModId } })) as GameMod | null;
  if (!mod) throw new Error("mod not found");
  const versions = await db.modVersion.findMany({ where: { gameModId: mod.id }, orderBy: { publishedAt: "desc" }, take: 200 });
  const version = input.modVersionId ? versions.find((v) => v.id === input.modVersionId) ?? null : pickVersion(versions, mod.gameFamily, input.gameVersion, input.loader);
  const key = normKey({ gameModId: mod.id, modVersionId: version?.id ?? null, gameVersion: input.gameVersion, loader: input.loader });
  const checks: Checks = {};

  checks.license = checkLicense(mod.license);
  checks.metadata = checkMetadata({ ...mod, versionNumber: version?.versionNumber ?? null, fileName: version?.fileName ?? null, fileBytes: version?.fileBytes ?? null });
  if (!version) {
    const why = versions.length ? `No build of this mod declares ${input.gameVersion}${input.loader ? ` on ${input.loader}` : ""}.` : "We hold no per-build records for this mod yet, so there is no exact file to verify.";
    checks.compat = { result: "unmet", detail: why, at: new Date().toISOString() };
    checks.source = { result: "unmet", detail: "No build selected.", at: new Date().toISOString() };
    checks.smoke = PENDING_SMOKE;
    const r = await recordChecks(key, { gameFamily: mod.gameFamily }, checks);
    return { key, status: r.status, checks, smokeQueued: false };
  }
  checks.compat = checkCompat(mod.gameFamily, key.gameVersion, version.gameVersions, key.loader, version.loaders, loadersFor(mod.gameFamily, key.loader));
  checks.source = checkSource(mod.source, version.fileUrl);

  let bytes: Buffer | null = null;
  let computed: ReturnType<typeof hashAll> | null = null;
  let error: string | undefined;
  if (checks.source.result === "pass" && version.fileUrl) {
    try {
      const res = await deps.fetcher(version.fileUrl, { maxBytes: MAX_DOWNLOAD, timeoutMs: 120_000 });
      bytes = res.bytes;
      computed = { sha1: res.sha1, sha256: res.sha256, sha512: res.sha512 };
    } catch (e) {
      error = e instanceof Error ? e.message : String(e);
    }
  }
  const declared = { sha1: version.sha1, sha256: version.sha256, sha512: version.sha512 };
  checks.integrity = error ? { result: "unmet", detail: `Download failed: ${error.slice(0, 160)}`, at: new Date().toISOString() } : checkIntegrity(declared, computed);
  checks.blocklist = checkBlocklist(computed, declared, deps.blocked ?? (await blockedHashes()));
  checks.archive = checkArchive(mod.gameFamily, version.fileName, bytes);
  // A preflight re-run never discards an earlier smoke result for the SAME build.
  const existing = await db.modVerification.findFirst({ where: { ...key }, select: { checks: true } });
  if (!(existing?.checks as Checks | null)?.smoke) checks.smoke = PENDING_SMOKE;

  const r = await recordChecks(key, { gameFamily: mod.gameFamily, versionNumber: version.versionNumber }, checks);
  const preOk = (["license", "source", "integrity", "blocklist", "metadata", "compat"] as const).every((k) => checks[k]?.result === "pass") && ["pass", "warn"].includes(checks.archive!.result);
  let smokeQueued = false;
  if (preOk && r.status !== "REVOKED") {
    const t = await enqueueVerifyTask("SMOKE", { ...key, gameFamily: mod.gameFamily }, input.requestedBy ?? null);
    smokeQueued = t.created;
  }
  return { key, status: r.status, checks, smokeQueued, error };
}

export { hashAll };

