/**
 * Second, independent safety pass for third-party mod HTML before it reaches
 * `dangerouslySetInnerHTML` in the mod preview modal.
 *
 * The first pass is lib/mod-markdown.ts (escape-everything-then-restore-an-
 * allow-list; it produces GameMod.bodyHtml at ingest). That output is STORED
 * in the database, so by the time we render it, it is just a string — this
 * pass re-parses it and rebuilds every tag from a strict allow-list, so a
 * future renderer bug, a hand-edited row or another ingest path can't smuggle
 * markup through. It never trusts input:
 *   - tags outside ALLOWED are dropped (their text is kept, escaped); tags in
 *     DROP_WITH_CONTENT (script/style/iframe/…) are dropped WITH their content;
 *   - only a handful of attributes survive, rebuilt from validated values:
 *     href (https:, or a site-relative /path), src (https: only), alt, title;
 *   - every external link gets target=_blank rel="noopener noreferrer nofollow ugc";
 *   - images get loading=lazy + referrerpolicy=no-referrer;
 *   - any `<`/`>` not part of a rebuilt tag is escaped.
 * No `class`, `style`, `on*` or `id` attributes are ever emitted (the modal
 * styles the body with its own scoped CSS).
 */

const ALLOWED = new Set([
  "p", "div", "span", "h3", "h4", "ul", "ol", "li", "a", "img", "strong", "b", "em", "i", "u", "s",
  "sub", "sup", "code", "pre", "blockquote", "hr", "br", "details", "summary", "table", "thead", "tbody", "tr", "th", "td",
]);
const VOID = new Set(["img", "hr", "br"]);
const DROP_WITH_CONTENT = new Set(["script", "style", "iframe", "object", "embed", "noscript", "template", "svg", "math", "textarea", "select", "form", "frameset", "frame"]);
/** h1/h2 from a mod author would outrank the modal's own headings. */
const RENAME: Record<string, string> = { h1: "h3", h2: "h3", h5: "h4", h6: "h4", b: "strong", i: "em", center: "div", font: "span", strike: "s" };

const TAG_RE = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)\b([^<>]*)>/g;
const ATTR_RE = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;

function escText(s: string): string {
  return s.replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
function escAttr(s: string): string {
  return s.replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
/** Decode the few entities that could hide a scheme (`&#106;avascript:`), for VALIDATION only. */
function decodeForCheck(s: string): string {
  return s
    .replace(/&#x([0-9a-f]+);?/gi, (_m, h: string) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);?/g, (_m, d: string) => String.fromCharCode(Number(d)))
    .replace(/&colon;/gi, ":")
    .replace(/&(amp|tab|newline);/gi, (_m, n: string) => (n.toLowerCase() === "amp" ? "&" : ""))
    .replace(/[\u0000-\u0020]/g, "");
}

export function safeHref(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const v = raw.trim();
  const d = decodeForCheck(v).toLowerCase();
  if (d.startsWith("https://")) return v;
  if (d.startsWith("http://")) return "https://" + v.replace(/^\s*http:\/\//i, "");
  if (/^\/(?![/\\])/.test(d)) return v;
  if (d.startsWith("#") && /^#[a-z0-9_-]{1,80}$/i.test(v)) return v;
  return null;
}
export function safeSrc(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const v = raw.trim();
  const d = decodeForCheck(v).toLowerCase();
  if (d.startsWith("https://")) return v;
  if (/^\/api\/nxlabs\/img\/[a-f0-9]{64}$/.test(d)) return v;
  return null;
}

function attrs(raw: string): Map<string, string> {
  const m = new Map<string, string>();
  ATTR_RE.lastIndex = 0;
  let x: RegExpExecArray | null;
  while ((x = ATTR_RE.exec(raw))) {
    const name = x[1].toLowerCase();
    if (!m.has(name)) m.set(name, x[2] ?? x[3] ?? x[4] ?? "");
  }
  return m;
}

export function hardenModHtml(html: string | null | undefined, maxLen = 200_000): string {
  if (!html) return "";
  const src = html.length > maxLen ? html.slice(0, maxLen) : html;
  let out = "";
  let last = 0;
  let dropDepth = 0;
  let dropTag = "";
  const open: string[] = [];
  TAG_RE.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = TAG_RE.exec(src))) {
    const text = src.slice(last, m.index);
    last = TAG_RE.lastIndex;
    if (dropDepth === 0) out += escText(text);
    const closing = m[1] === "/";
    let tag = m[2].toLowerCase();
    if (dropDepth > 0) {
      if (tag === dropTag) dropDepth += closing ? -1 : 1;
      continue;
    }
    if (DROP_WITH_CONTENT.has(tag)) {
      if (!closing && !/\/\s*$/.test(m[3])) {
        dropDepth = 1;
        dropTag = tag;
      }
      continue;
    }
    tag = RENAME[tag] ?? tag;
    if (!ALLOWED.has(tag)) continue;
    if (closing) {
      if (VOID.has(tag)) continue;
      const i = open.lastIndexOf(tag);
      if (i === -1) continue; // stray close: drop
      while (open.length > i) out += `</${open.pop()}>`;
      continue;
    }
    const a = attrs(m[3]);
    if (tag === "a") {
      const href = safeHref(a.get("href"));
      const title = a.get("title");
      const ext = !!href && /^https:/i.test(decodeForCheck(href));
      out += `<a${href ? ` href="${escAttr(href)}"` : ""}${title ? ` title="${escAttr(title.slice(0, 200))}"` : ""}${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>`;
      open.push("a");
    } else if (tag === "img") {
      const s = safeSrc(a.get("src"));
      if (!s) continue;
      const alt = (a.get("alt") ?? "").slice(0, 200);
      out += `<img src="${escAttr(s)}" alt="${escAttr(alt)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" />`;
    } else if (VOID.has(tag)) {
      out += `<${tag} />`;
    } else {
      out += `<${tag}>`;
      open.push(tag);
    }
  }
  if (dropDepth === 0) out += escText(src.slice(last));
  while (open.length) out += `</${open.pop()}>`;
  return out;
}

