/** Real category breakdown for one family, for the per-family page's chips — a DB-wide groupBy, not just what's on the current page. */
export async function listCategoryCounts(family: string): Promise<{ category: string; count: number }[]> {
  const rows = await db.gameMod.groupBy({
    by: ["category"],
    where: { active: true, upstreamOk: true, gameFamily: family },
    _count: true,
  });
  return rows.map((r) => ({ category: r.category, count: r._count })).sort((a, b) => b.count - a.count);
}

/**
 * Real loader/platform facet for the portal's NxLabs filters — every value the
 * sources list in GameMod.loaders, with how many public mods carry it. Cached
 * like the other whole-catalogue aggregates (one unnest over the family).
 */
export const listLoaderCounts = unstable_cache(
  async (family?: string): Promise<{ loader: string; count: number }[]> => {
    const rows = await db.$queryRaw<{ loader: string; count: bigint }[]>(Prisma.sql`
      SELECT l AS loader, count(*) AS count
      FROM "GameMod", unnest("loaders") AS l
      WHERE "active" = true AND "upstreamOk" = true
      ${family ? Prisma.sql`AND "gameFamily" = ${family}` : Prisma.empty}
      GROUP BY l ORDER BY count(*) DESC LIMIT 40`);
    return rows.map((r) => ({ loader: r.loader, count: Number(r.count) }));
  },
  ["mods-catalog:listLoaderCounts"],
  { revalidate: CATALOG_AGGREGATE_REVALIDATE_SECONDS }
);

/**
 * Real game-version facet for one family: release-style versions only
 * ("1.21.1", "26.3" — snapshots/pre-releases dropped, they'd swamp the list),
 * newest first, each with its real mod count. Families whose sources publish
 * no version list return [] and the filter simply isn't offered.
 */
export const listGameVersionCounts = unstable_cache(
  async (family: string, take = 24): Promise<{ version: string; count: number }[]> => {
    const rows = await db.$queryRaw<{ version: string; count: bigint }[]>(Prisma.sql`
      SELECT v AS version, count(*) AS count
      FROM "GameMod", unnest("gameVersions") AS v
      WHERE "active" = true AND "upstreamOk" = true AND "gameFamily" = ${family}
        AND v ~ '^[0-9]+(\\.[0-9]+){1,2}$'
      GROUP BY v`);
    const key = (v: string) => v.split(".").map((x) => x.padStart(5, "0")).join(".");
    return rows
      .map((r) => ({ version: r.version, count: Number(r.count) }))
      .sort((a, b) => key(b.version).localeCompare(key(a.version)))
      .slice(0, take);
  },
  ["mods-catalog:listGameVersionCounts"],
  { revalidate: CATALOG_AGGREGATE_REVALIDATE_SECONDS }
);

/** Real total downloads across a whole family (or the whole catalogue) — a DB aggregate, not a reduce over one loaded page. */
export const totalDownloadsFor = unstable_cache(
  async (family?: string): Promise<number> => {
    const agg = await db.gameMod.aggregate({
      where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
      _sum: { downloads: true },
    });
    return agg._sum.downloads ?? 0;
  },
  ["mods-catalog:totalDownloadsFor"],
  { revalidate: CATALOG_AGGREGATE_REVALIDATE_SECONDS }
);

