/**
 * Mod BROWSER + PREVIEW data layer (K5, 2026-10-01).
 *
 * Backs the customer browser in the server's Mods & Plugins tab
 * (components/customer/mods/browser/*) via lib/actions-mod-browse.ts. It reads
 * the same GameMod / ModVersion rows as everything else (lib/mods-catalog.ts
 * for the public catalogue, lib/actions-mod-installs.ts for the installer
 * actions) and adds:
 *   - server-side paginated search with game-version / loader / category /
 *     Nxeon-Verified-only filters and "compatible with my server" (default on),
 *   - per-card compat for THIS server, install state, and the live
 *     Nxeon Verified badge (lib/mod-verify/*),
 *   - the preview: gallery (our mirrored WebP first), sanitised long
 *     description, versions with per-version compat, dependencies resolved to
 *     catalogue entries, changelogs, links, licence, client-side warning.
 *
 * GRACEFUL DEGRADATION: parallel work (K3) is adding richer GameMod columns
 * (client_side, issues/wiki/discord links, authors…). Prisma returns every
 * scalar column of a row, so this module reads those through `opt()` — when a
 * column doesn't exist yet the value is simply undefined and the UI hides that
 * row. Nothing here needs a schema change to pick them up once they land.
 *
 * HONESTY: every number is the source's own or absent. Nothing is estimated.
 */
import type { GameMod, ModVersion, Prisma } from "@prisma/client";
import { db } from "./db";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { modCompat } from "./mod-load";
import { installSupport } from "./mod-install-support";
import { ENGINE_INSTALLERS, engineInstallerFor, familyCoverage } from "./mods/installers";
import { acceptedLoaders } from "./mods/installers/minecraft";
import { catalogFacts } from "./mods/facts";
import type { Compat, ServerFacts } from "./mods/types";
import { modGallerySrc, modIconSrc } from "./modsync/urls";
import { renderModBody, renderModMarkdown, truncateMarkdown } from "./mod-markdown";
import { hardenModHtml } from "./mod-html-harden";
import { liveBadges, liveVerifiedModIds, type LiveBadge } from "./mod-verify/store";
import { badgeSentence, checkList, fmtDate, BADGE_DISCLAIMER } from "./mod-verify/status";
import { fetchJson, safeFetch } from "./mods/safe-fetch";
import { VERSIONED_FAMILIES } from "./mod-verify/checks";

// ── optional (K3) columns ────────────────────────────────────────────────────
/** Read a column that may not exist on this deployment's GameMod yet. */
export function opt<T = unknown>(row: object, key: string): T | undefined {
  const v = (row as Record<string, unknown>)[key];
  return v === null || v === undefined ? undefined : (v as T);
}
const optStr = (row: object, ...keys: string[]): string | null => {
  for (const k of keys) {
    const v = opt(row, k);
    if (typeof v === "string" && v.trim()) return v.trim();
  }
  return null;
};
const httpsUrl = (u: string | null | undefined) => (u && /^https?:\/\//i.test(u) ? u.replace(/^http:/i, "https:") : null);

export function gameName(family: string): string {
  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
}

// ── server context ───────────────────────────────────────────────────────────
export type BrowseServer = {
  serverId: string;
  family: string;
  facts: ServerFacts;
  /** Loaders this server accepts (Minecraft's ladder; [] = n/a or vanilla). */
  accepted: string[];
};

export function browseServerCtx(serverId: string, family: string, facts: ServerFacts): BrowseServer {
  return { serverId, family, facts, accepted: family === "minecraft" ? acceptedLoaders(facts.variant ?? "vanilla") : facts.variant ? [facts.variant.toLowerCase()] : [] };
}

function compatFor(family: string, m: GameMod, facts: ServerFacts): Compat {
  const inst = engineInstallerFor(family, m.source) ?? ENGINE_INSTALLERS[family];
  if (inst) return inst.compat(catalogFacts(m), facts);
  const c = modCompat({ gameVersions: m.gameVersions, loaders: m.loaders, serverSide: m.serverSide }, { gameVersion: facts.pinnedVersion, variant: facts.variant });
  return c.verdict === "unknown" ? { verdict: "unknown", detail: c.detail, reason: c.reason } : (c as Compat);
}

// ── query ────────────────────────────────────────────────────────────────────
export const BROWSE_SORTS = ["popular", "downloads", "updated", "name", "light"] as const;
export type BrowseSort = (typeof BROWSE_SORTS)[number];

export type BrowseQuery = {
  q?: string;
  category?: string;
  sort?: BrowseSort;
  compatibleOnly?: boolean;
  verifiedOnly?: boolean;
  /** Override the server's own version (e.g. to shop before upgrading). */
  gameVersion?: string;
  loader?: string;
  page?: number;
};

export const BROWSE_PAGE_SIZE = 24;
const CLIENT_ONLY_CATS = ["Resource Packs", "Shaders"];

/** Validate/normalise untrusted query input (server actions receive raw JSON). */
export function normQuery(q: BrowseQuery | null | undefined): Required<Omit<BrowseQuery, "gameVersion" | "loader">> & { gameVersion: string | null; loader: string | null } {
  const s = (x: unknown, n: number) => (typeof x === "string" ? x.trim().slice(0, n) : "");
  const token = (x: unknown) => {
    const v = s(x, 40);
    return v && /^[0-9A-Za-z.\-+_]{1,40}$/.test(v) ? v : null;
  };
  return {
    q: s(q?.q, 80),
    category: s(q?.category, 60) || "all",
    sort: (BROWSE_SORTS as readonly string[]).includes(String(q?.sort)) ? (q!.sort as BrowseSort) : "popular",
    compatibleOnly: q?.compatibleOnly !== false,
    verifiedOnly: q?.verifiedOnly === true,
    gameVersion: token(q?.gameVersion),
    loader: token(q?.loader)?.toLowerCase() ?? null,
    page: Math.max(1, Math.min(400, Math.floor(Number(q?.page) || 1))),
  };
}

/** Pure: the Prisma `where` for a browse query. Exported for tests. */
export function buildBrowseWhere(family: string, q: ReturnType<typeof normQuery>, ctx: { variant: string | null; pinnedVersion: string | null } | null, verifiedIds: string[] | null): Prisma.GameModWhereInput {
  const and: Prisma.GameModWhereInput[] = [{ gameFamily: family, active: true, upstreamOk: true }];
  if (q.q) {
    and.push({
      OR: [
        { name: { contains: q.q, mode: "insensitive" } },
        { slug: { contains: q.q.toLowerCase().replace(/\s+/g, "-") } },
        { description: { contains: q.q, mode: "insensitive" } },
        { authorName: { contains: q.q, mode: "insensitive" } },
      ],
    });
  }
  if (q.category !== "all") and.push({ category: q.category });
  if (q.loader) and.push({ loaders: { has: q.loader } });
  const version = q.gameVersion ?? (q.compatibleOnly ? ctx?.pinnedVersion ?? null : null);
  if (version && VERSIONED_FAMILIES.has(family)) and.push({ OR: [{ gameVersions: { has: version } }, { gameVersions: { isEmpty: true } }] });
  if (q.compatibleOnly && ctx) {
    const inst = ENGINE_INSTALLERS[family];
    if (inst) and.push({ source: { in: [...inst.sources] } });
    and.push({ OR: [{ serverSide: null }, { NOT: { serverSide: "unsupported" } }] });
    if (family === "minecraft") {
      const acc = acceptedLoaders(ctx.variant ?? "vanilla");
      and.push({ category: { notIn: CLIENT_ONLY_CATS } });
      if (acc.length) and.push({ OR: [{ loaders: { hasSome: [...acc, "datapack"] } }, { category: "Datapacks" }] });
      else and.push({ OR: [{ category: "Datapacks" }, { loaders: { has: "datapack" } }] });
    }
  }
  if (verifiedIds) and.push({ id: { in: verifiedIds } });
  return { AND: and };
}

const ORDER: Record<BrowseSort, Prisma.GameModOrderByWithRelationInput[]> = {
  popular: [{ featured: "desc" }, { downloads: { sort: "desc", nulls: "last" } }, { popularity: "desc" }, { name: "asc" }],
  downloads: [{ downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }],
  updated: [{ upstreamUpdatedAt: { sort: "desc", nulls: "last" } }, { name: "asc" }],
  name: [{ name: "asc" }],
  light: [{ fileBytes: { sort: "asc", nulls: "last" } }, { downloads: { sort: "desc", nulls: "last" } }],
};

/* A count over a 30k-row family is the slowest half of a search (~50-140 ms on
 * real data, 2026-10-01). Paging through the same query re-asks the same count,
 * so it is memoised briefly per where-clause. */
const countCache = new Map<string, { at: number; n: number }>();
async function cachedCount(where: Prisma.GameModWhereInput): Promise<number> {
  const k = JSON.stringify(where);
  const hit = countCache.get(k);
  if (hit && Date.now() - hit.at < 60_000) return hit.n;
  const n = await db.gameMod.count({ where });
  if (countCache.size > 500) countCache.clear();
  countCache.set(k, { at: Date.now(), n });
  return n;
}

// ── cards ────────────────────────────────────────────────────────────────────
export type BadgeView = {
  sentence: string;
  gameVersion: string;
  loader: string;
  versionNumber: string | null;
  verifiedAt: string;
  expiresAt: string;
  checks: { key: string; label: string; result: string; detail: string }[];
  disclaimer: string;
};

export function badgeView(family: string, b: LiveBadge | null | undefined): BadgeView | null {
  if (!b || !b.verifiedAt || !b.expiresAt) return null;
  return {
    sentence: badgeSentence(gameName(family), b),
    gameVersion: b.gameVersion,
    loader: b.loader ?? "",
    versionNumber: b.versionNumber ?? null,
    verifiedAt: fmtDate(b.verifiedAt),
    expiresAt: fmtDate(b.expiresAt),
    checks: checkList(b.checks),
    disclaimer: BADGE_DISCLAIMER,
  };
}

export type BrowseCard = {
  id: string;
  slug: string;
  name: string;
  author: string | null;
  summary: string | null;
  icon: string | null;
  category: string;
  source: string;
  downloads: number | null;
  updatedAt: string | null;
  fileBytes: number | null;
  featured: boolean;
  paid: boolean;
  impact: string;
  compat: Compat | null;
  manualInstall: string | null;
  status: string | null;
  version: string | null;
  error: string | null;
  verified: BadgeView | null;
  clientRequired: boolean | null;
  dependencyCount: number;
  latestVersion: string | null;
};

type State = { status: string; version: string | null; error: string | null };

function toCard(m: GameMod, ctx: BrowseServer | null, st: State | undefined, badge: LiveBadge | undefined): BrowseCard {
  const fam = m.gameFamily;
  const cov = familyCoverage(fam);
  const sup = installSupport(fam, m.source);
  const compat = ctx ? compatFor(fam, m, ctx.facts) : null;
  return {
    id: m.id,
    slug: m.slug,
    name: m.name,
    author: m.authorName,
    summary: m.description,
    icon: modIconSrc(m),
    category: m.category,
    source: m.source,
    downloads: m.downloads,
    updatedAt: (m.upstreamUpdatedAt ?? null)?.toISOString() ?? null,
    fileBytes: m.fileBytes,
    featured: m.featured,
    paid: m.paid,
    impact: m.impact,
    compat,
    manualInstall: cov.mode === "unavailable" ? cov.reason : !sup.ok ? sup.message : compat?.verdict === "unsupported" ? compat.detail : null,
    status: st?.status ?? null,
    version: st?.version ?? null,
    error: st?.error ?? null,
    verified: badgeView(fam, badge),
    clientRequired: clientRequired(m),
    dependencyCount: m.dependencyCount,
    latestVersion: m.latestVersion,
  };
}

/** true = players must install it too; false = server-only; null = the source doesn't say. */
export function clientRequired(m: object): boolean | null {
  const cs = optStr(m, "clientSide", "client_side");
  if (cs === "required") return true;
  if (cs === "unsupported" || cs === "optional") return false;
  const flag = opt<boolean>(m, "clientRequired");
  return typeof flag === "boolean" ? flag : null;
}

export type BrowsePage = { items: BrowseCard[]; total: number; page: number; pageSize: number; hasMore: boolean; appliedVersion: string | null };

export async function browseMods(family: string, query: BrowseQuery, ctx: BrowseServer | null): Promise<BrowsePage> {
  const q = normQuery(query);
  const version = q.gameVersion ?? ctx?.facts.pinnedVersion ?? null;
  const verifiedIds = q.verifiedOnly ? await liveVerifiedModIds(family, { gameVersion: VERSIONED_FAMILIES.has(family) ? version : null, loaders: ctx?.accepted.length ? ctx.accepted : undefined }) : null;
  const where = buildBrowseWhere(family, q, ctx ? { variant: ctx.facts.variant, pinnedVersion: ctx.facts.pinnedVersion } : null, verifiedIds);
  const skip = (q.page - 1) * BROWSE_PAGE_SIZE;
  const [total, rows, states] = await Promise.all([
    cachedCount(where),
    db.gameMod.findMany({ where, orderBy: ORDER[q.sort], skip, take: BROWSE_PAGE_SIZE }),
    ctx ? db.serverMod.findMany({ where: { serverId: ctx.serverId }, select: { modId: true, status: true, version: true, error: true } }) : Promise.resolve([]),
  ]);
  const badges = await liveBadges(rows.map((r) => r.id), { gameVersion: VERSIONED_FAMILIES.has(family) ? version : null, loaders: ctx?.accepted.length ? ctx.accepted : undefined });
  const st = new Map(states.map((s) => [s.modId, s]));
  return {
    items: rows.map((m) => toCard(m, ctx, st.get(m.id), badges.get(m.id))),
    total,
    page: q.page,
    pageSize: BROWSE_PAGE_SIZE,
    hasMore: skip + rows.length < total,
    appliedVersion: VERSIONED_FAMILIES.has(family) ? (q.gameVersion ?? (q.compatibleOnly ? ctx?.facts.pinnedVersion ?? null : null)) : null,
  };
}

// ── preview ──────────────────────────────────────────────────────────────────
export type DepView = {
  kind: "required" | "optional" | "incompatible" | "embedded";
  name: string;
  /** Catalogue entry for one-click install, when we have one. */
  modId: string | null;
  slug: string | null;
  icon: string | null;
  url: string | null;
  status: string | null;
};

export type VersionView = {
  id: string;
  number: string;
  channel: string;
  gameVersions: string[];
  loaders: string[];
  publishedAt: string | null;
  fileName: string | null;
  fileBytes: number | null;
  downloads: number | null;
  /** For THIS server: "ok" | "mismatch" | "unknown". */
  fit: "ok" | "mismatch" | "unknown";
  fitDetail: string;
  changelogHtml: string | null;
  hasHash: boolean;
};

export type ModPreview = {
  card: BrowseCard;
  family: string;
  gameName: string;
  bodyHtml: string | null;
  bodyTruncated: boolean;
  gallery: { src: string; alt: string }[];
  license: string | null;
  licenseUrl: string | null;
  authors: { name: string; avatar: string | null }[];
  links: { label: string; href: string }[];
  categories: string[];
  loaders: string[];
  gameVersions: string[];
  versions: VersionView[];
  deps: DepView[];
  depsNote: string | null;
  badges: BadgeView[];
  bestVersionId: string | null;
  followers: number | null;
};

const LINK_KEYS: [string, string[]][] = [
  ["Source code", ["sourceUrl"]],
  ["Issues", ["issuesUrl", "issueUrl", "bugTrackerUrl"]],
  ["Wiki", ["wikiUrl", "docsUrl"]],
  ["Discord", ["discordUrl"]],
];

function versionFit(family: string, v: Pick<ModVersion, "gameVersions" | "loaders">, ctx: BrowseServer | null): { fit: VersionView["fit"]; detail: string } {
  if (!ctx) return { fit: "unknown", detail: "" };
  const pinned = ctx.facts.pinnedVersion;
  const loaderOk = !ctx.accepted.length || !v.loaders.length || v.loaders.some((l) => ctx.accepted.includes(l) || l === "datapack");
  if (!loaderOk) return { fit: "mismatch", detail: `Built for ${v.loaders.slice(0, 3).join(", ")} — your server runs ${ctx.facts.variant ?? "vanilla"}.` };
  if (VERSIONED_FAMILIES.has(family)) {
    if (!pinned) return { fit: "unknown", detail: "Your server isn't pinned to a version — the right build is chosen at install time." };
    if (!v.gameVersions.includes(pinned)) return { fit: "mismatch", detail: `Doesn't list ${pinned}.` };
    return { fit: "ok", detail: `Lists ${pinned}${ctx.facts.variant ? ` on ${ctx.facts.variant}` : ""}.` };
  }
  return { fit: loaderOk ? "ok" : "mismatch", detail: "" };
}

/* Modrinth dependencies reference project ids; our rows are keyed by slug. One
 * bulk lookup (cached) turns ids into slugs/titles. Failure => raw ids shown. */
const mrCache = new Map<string, { at: number; slug: string; title: string; icon: string | null }>();
async function modrinthProjects(ids: string[]): Promise<Map<string, { slug: string; title: string; icon: string | null }>> {
  const out = new Map<string, { slug: string; title: string; icon: string | null }>();
  const need = ids.filter((id) => {
    const c = mrCache.get(id);
    if (c && Date.now() - c.at < 6 * 3600_000) {
      out.set(id, c);
      return false;
    }
    return /^[A-Za-z0-9]{6,12}$/.test(id);
  });
  if (need.length) {
    try {
      const rows = await fetchJson<{ id: string; slug: string; title: string; icon_url: string | null }[]>(
        safeFetch,
        `https://api.modrinth.com/v2/projects?ids=${encodeURIComponent(JSON.stringify(need.slice(0, 40)))}`,
        { maxBytes: 4 * 1024 * 1024, headers: { "User-Agent": "nxeon-mod-browser (support@nxeon.cloud)" } },
      );
      for (const r of rows) {
        const v = { at: Date.now(), slug: r.slug, title: r.title, icon: r.icon_url };
        mrCache.set(r.id, v);
        out.set(r.id, v);
      }
    } catch {
      /* offline / rate-limited: caller falls back to ids */
    }
  }
  return out;
}

type RawDep = { kind: DepView["kind"]; name: string; projectId?: string; url?: string | null };

/** Pure: normalise a ModVersion.dependencies JSON blob from any provider. Exported for tests. */
export function parseDeps(source: string, raw: unknown, variant?: string | null): RawDep[] {
  const out: RawDep[] = [];
  if (Array.isArray(raw)) {
    for (const d of raw) {
      if (d && typeof d === "object" && "dependency_type" in d) {
        const x = d as { project_id?: string | null; dependency_type?: string; file_name?: string | null };
        const kind = (["required", "optional", "incompatible", "embedded"].includes(String(x.dependency_type)) ? x.dependency_type : "optional") as DepView["kind"];
        if (x.project_id) out.push({ kind, name: x.project_id, projectId: x.project_id });
        else if (x.file_name) out.push({ kind, name: x.file_name });
      } else if (typeof d === "string") {
        // Factorio style: "? name >= 1.0", "! name", "~ name", "name >= 1"
        const m = /^\s*([?!~(]|\(\?\))?\s*([A-Za-z0-9_\- ]+?)\s*(?:[<>=].*)?$/.exec(d);
        if (m && m[2] && m[2] !== "base") out.push({ kind: m[1] === "!" ? "incompatible" : m[1]?.includes("?") ? "optional" : "required", name: m[2].trim() });
      } else if (d && typeof d === "object" && ("mod_reference" in d || "mod_id" in d)) {
        const x = d as { mod_reference?: string; mod_id?: string; optional?: boolean };
        out.push({ kind: x.optional ? "optional" : "required", name: String(x.mod_reference ?? x.mod_id) });
      }
    }
  } else if (raw && typeof raw === "object") {
    // Hangar: { PAPER: [{ name, required, externalUrl }], VELOCITY: [...] }
    const plat = (variant ?? "paper").toUpperCase();
    const groups = raw as Record<string, unknown>;
    const list = (groups[plat] ?? groups.PAPER ?? Object.values(groups)[0]) as unknown;
    if (Array.isArray(list)) {
      for (const d of list as { name?: string; required?: boolean; externalUrl?: string | null }[]) {
        if (d?.name) out.push({ kind: d.required ? "required" : "optional", name: d.name, url: httpsUrl(d.externalUrl ?? null) });
      }
    }
  }
  const seen = new Set<string>();
  return out.filter((d) => {
    const k = `${d.kind}:${d.name.toLowerCase()}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

const slugify = (s: string) => s.toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80);

async function resolveDeps(mod: GameMod, raw: RawDep[], ctx: BrowseServer | null): Promise<{ deps: DepView[]; note: string | null }> {
  if (!raw.length) return { deps: [], note: null };
  let note: string | null = null;
  const mr = mod.source === "modrinth" ? await modrinthProjects(raw.filter((d) => d.projectId).map((d) => d.projectId!)) : new Map();
  if (mod.source === "modrinth" && raw.some((d) => d.projectId && !mr.has(d.projectId))) note = "Some dependency names couldn't be looked up right now — the installer resolves them against the source either way.";
  const named = raw.map((d) => {
    const p = d.projectId ? mr.get(d.projectId) : undefined;
    return { ...d, name: p?.title ?? d.name, slug: p?.slug ?? slugify(d.name), icon: p?.icon ?? null, url: d.url ?? (d.projectId ? `https://modrinth.com/project/${p?.slug ?? d.projectId}` : null) };
  });
  const slugs = [...new Set(named.map((d) => d.slug).filter(Boolean))];
  const local = slugs.length
    ? await db.gameMod.findMany({ where: { gameFamily: mod.gameFamily, active: true, upstreamOk: true, OR: [{ slug: { in: slugs } }, { sourceId: { in: slugs } }] }, select: { id: true, slug: true, sourceId: true, iconKey: true, iconUrl: true, name: true } })
    : [];
  const bySlug = new Map<string, (typeof local)[number]>();
  for (const l of local) {
    bySlug.set(l.slug, l);
    if (l.sourceId) bySlug.set(l.sourceId.toLowerCase(), l);
  }
  const states = ctx && local.length ? await db.serverMod.findMany({ where: { serverId: ctx.serverId, modId: { in: local.map((l) => l.id) } }, select: { modId: true, status: true } }) : [];
  const st = new Map(states.map((s) => [s.modId, s.status]));
  return {
    deps: named.map((d) => {
      const l = bySlug.get(d.slug);
      return { kind: d.kind, name: l?.name ?? d.name, modId: l?.id ?? null, slug: l?.slug ?? null, icon: l ? modIconSrc(l) : httpsUrl(d.icon), url: httpsUrl(d.url), status: l ? st.get(l.id) ?? null : null };
    }),
    note,
  };
}

export async function getModPreview(family: string, idOrSlug: string, ctx: BrowseServer | null): Promise<ModPreview | null> {
  const key = String(idOrSlug).slice(0, 120);
  const mod = await db.gameMod.findFirst({ where: { gameFamily: family, active: true, OR: [{ id: key }, { slug: key }] } });
  if (!mod) return null;
  const [versions, state, allBadges] = await Promise.all([
    db.modVersion.findMany({ where: { gameModId: mod.id }, orderBy: [{ publishedAt: { sort: "desc", nulls: "last" } }], take: 40 }),
    ctx ? db.serverMod.findUnique({ where: { serverId_modId: { serverId: ctx.serverId, modId: mod.id } }, select: { status: true, version: true, error: true } }) : Promise.resolve(null),
    db.modVerification.findMany({ where: { gameModId: mod.id, status: "VERIFIED", expiresAt: { gt: new Date() } }, orderBy: { verifiedAt: "desc" }, take: 12 }),
  ]);
  const serverVersion = ctx?.facts.pinnedVersion ?? null;
  const forThis = allBadges.find((b) => (!VERSIONED_FAMILIES.has(family) || !serverVersion || b.gameVersion === serverVersion || b.gameVersion === "any") && (!ctx?.accepted.length || !b.loader || ctx.accepted.includes(b.loader)));
  const card = toCard(mod, ctx, state ?? undefined, (ctx ? forThis : allBadges[0]) as LiveBadge | undefined);

  // Body: stored sanitised HTML (ingest) > render the raw long description now > nothing.
  let bodyHtml: string | null = null;
  let bodyTruncated = false;
  if (mod.bodyHtml) bodyHtml = hardenModHtml(mod.bodyHtml);
  else if (mod.longDescription) {
    const r = renderModBody(mod.longDescription, mod.source === "modrinth" ? "modrinth" : mod.source === "thunderstore" ? "thunderstore" : mod.source === "steam_workshop" ? "steam_workshop" : "other", 12000);
    bodyHtml = hardenModHtml(r.html);
    bodyTruncated = r.truncated;
  }

  const gallerySrc = modGallerySrc(mod).slice(0, 12);
  const gallery = gallerySrc.filter((s) => s.startsWith("/api/nxlabs/img/") || /^https:\/\//.test(s)).map((src, i) => ({ src, alt: `${mod.name} screenshot ${i + 1}` }));

  const links: { label: string; href: string }[] = [];
  const project = httpsUrl(mod.url);
  if (project) links.push({ label: "Project page", href: project });
  for (const [label, keys] of LINK_KEYS) {
    const v = httpsUrl(optStr(mod, ...keys));
    if (v && !links.some((l) => l.href === v)) links.push({ label, href: v });
  }

  const authorsOpt = opt<unknown>(mod, "authors");
  const authors: { name: string; avatar: string | null }[] = Array.isArray(authorsOpt)
    ? (authorsOpt as unknown[]).map((a) => (typeof a === "string" ? { name: a, avatar: null } : a && typeof a === "object" && "name" in a ? { name: String((a as { name: unknown }).name), avatar: httpsUrl(String((a as { avatar?: unknown }).avatar ?? "")) } : null)).filter((x): x is { name: string; avatar: string | null } => !!x?.name).slice(0, 8)
    : mod.authorName
      ? [{ name: mod.authorName, avatar: httpsUrl(mod.authorAvatarUrl) }]
      : [];

  const vviews: VersionView[] = versions.map((v) => {
    const f = versionFit(family, v, ctx);
    let changelogHtml: string | null = null;
    if (v.changelog?.trim()) {
      const t = truncateMarkdown(v.changelog, 4000);
      changelogHtml = hardenModHtml(renderModMarkdown(t.text));
    }
    return {
      id: v.id,
      number: v.versionNumber,
      channel: v.channel,
      gameVersions: v.gameVersions.slice(-12),
      loaders: v.loaders.slice(0, 6),
      publishedAt: v.publishedAt?.toISOString() ?? null,
      fileName: v.fileName,
      fileBytes: v.fileBytes,
      downloads: v.downloads,
      fit: f.fit,
      fitDetail: f.detail,
      changelogHtml,
      hasHash: !!(v.sha512 || v.sha256 || v.sha1),
    };
  });
  const best = vviews.find((v) => v.fit === "ok" && v.channel === "release") ?? vviews.find((v) => v.fit === "ok") ?? vviews.find((v) => v.fit !== "mismatch") ?? null;
  const depSourceVersion = versions.find((v) => v.id === best?.id) ?? versions[0];
  const { deps, note } = await resolveDeps(mod, depSourceVersion ? parseDeps(mod.source, depSourceVersion.dependencies, ctx?.facts.variant) : [], ctx);

  return {
    card,
    family,
    gameName: gameName(family),
    bodyHtml: bodyHtml && bodyHtml.trim() ? bodyHtml : null,
    bodyTruncated,
    gallery,
    license: mod.license,
    licenseUrl: httpsUrl(mod.licenseUrl),
    authors,
    links,
    categories: [...new Set([mod.category, ...mod.categories])].filter(Boolean).slice(0, 8),
    loaders: mod.loaders.slice(0, 10),
    gameVersions: mod.gameVersions.slice(-16),
    versions: vviews,
    deps: deps.filter((d) => d.kind !== "embedded"),
    depsNote: note,
    badges: allBadges.map((b) => badgeView(family, b as LiveBadge)).filter((x): x is BadgeView => !!x),
    bestVersionId: best?.id ?? null,
    followers: mod.followers,
  };
}

/** Filter facets for the browser (cached aggregates from lib/mods-catalog.ts). */
export async function browseFacets(family: string) {
  const { listGameVersionCounts, listLoaderCounts, listCategoryCounts } = await import("./mods-catalog");
  const [versions, loaders, categories] = await Promise.all([
    VERSIONED_FAMILIES.has(family) ? listGameVersionCounts(family, 30) : Promise.resolve([]),
    listLoaderCounts(family),
    listCategoryCounts(family),
  ]);
  return { versions, loaders: loaders.filter((l) => l.loader !== "datapack" || family === "minecraft").slice(0, 16), categories: categories.slice(0, 60) };
}

input.content:
"use server";

/**
 * Server actions for the mod browser + preview modal in the server's
 * Mods & Plugins tab (components/customer/mods/browser/*). Read-only: the
 * Install / Update / Remove buttons call the existing installer actions in
 * lib/actions-mod-installs.ts, so there is exactly one write path.
 * Ownership is checked on every call (same rule as the installer actions).
 */
import { db } from "./db";
import { requireUser } from "./auth";
import { familyFor } from "./game-config";
import { serverFacts } from "./mods/facts";
import { browseFacets, browseMods, browseServerCtx, getModPreview, type BrowsePage, type BrowseQuery, type ModPreview } from "./mods-browse";

async function ctxFor(serverId: string) {
  const user = await requireUser();
  if (typeof serverId !== "string" || serverId.length > 64) throw new Error("Not found");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const family = familyFor(server);
  if (!family) return null;
  return browseServerCtx(serverId, family, serverFacts(server, family));
}

export async function browseServerMods(serverId: string, query: BrowseQuery): Promise<{ page?: BrowsePage; error?: string }> {
  const ctx = await ctxFor(serverId);
  if (!ctx) return { error: "This server doesn't support mods." };
  try {
    return { page: await browseMods(ctx.family, query, ctx) };
  } catch (e) {
    console.error("[mod-browse] search failed", e);
    return { error: "Search failed — try again." };
  }
}

export async function serverModFacets(serverId: string) {
  const ctx = await ctxFor(serverId);
  if (!ctx) return { error: "This server doesn't support mods." };
  const f = await browseFacets(ctx.family);
  return {
    facets: f,
    server: { family: ctx.family, variant: ctx.facts.variant, gameVersion: ctx.facts.pinnedVersion, accepted: ctx.accepted },
  };
}

export async function serverModPreview(serverId: string, slug: string): Promise<{ preview?: ModPreview; error?: string }> {
  const ctx = await ctxFor(serverId);
