"use server";

/**
 * Server actions for the mod browser + preview modal in the server's
 * Mods & Plugins tab (components/customer/mods/browser/*). Read-only: the
 * Install / Update / Remove buttons call the existing installer actions in
 * lib/actions-mod-installs.ts, so there is exactly one write path.
 * Ownership is checked on every call (same rule as the installer actions).
 */
import { db } from "./db";
import { requireUser } from "./auth";
import { familyFor } from "./game-config";
import { serverFacts } from "./mods/facts";
import { browseFacets, browseMods, browseServerCtx, getModPreview, type BrowsePage, type BrowseQuery, type ModPreview } from "./mods-browse";

async function ctxFor(serverId: string) {
  const user = await requireUser();
  if (typeof serverId !== "string" || serverId.length > 64) throw new Error("Not found");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const family = familyFor(server);
  if (!family) return null;
  return browseServerCtx(serverId, family, serverFacts(server, family));
}

export async function browseServerMods(serverId: string, query: BrowseQuery): Promise<{ page?: BrowsePage; error?: string }> {
  const ctx = await ctxFor(serverId);
  if (!ctx) return { error: "This server doesn't support mods." };
  try {
    return { page: await browseMods(ctx.family, query, ctx) };
  } catch (e) {
    console.error("[mod-browse] search failed", e);
    return { error: "Search failed — try again." };
  }
}

export async function serverModFacets(serverId: string) {
  const ctx = await ctxFor(serverId);
  if (!ctx) return { error: "This server doesn't support mods." };
  const f = await browseFacets(ctx.family);
  return {
    facets: f,
    server: { family: ctx.family, variant: ctx.facts.variant, gameVersion: ctx.facts.pinnedVersion, accepted: ctx.accepted },
  };
}

export async function serverModPreview(serverId: string, slug: string): Promise<{ preview?: ModPreview; error?: string }> {
  const ctx = await ctxFor(serverId);
  if (!ctx) return { error: "This server doesn't support mods." };
  if (typeof slug !== "string" || !/^[A-Za-z0-9._\-]{1,120}$/.test(slug)) return { error: "That mod isn't in the catalogue." };
  try {
    const p = await getModPreview(ctx.family, slug, ctx);
    return p ? { preview: p } : { error: "That mod isn't in the catalogue for this game." };
  } catch (e) {
    console.error("[mod-browse] preview failed", e);
    return { error: "Couldn't load this mod — try again." };
  }
}

