const fx = (n: string) => JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/modsync", n), "utf8"));

test("modrinth: project + versions normalise (license, compat matrix, newest-first, primary file)", () => {
  const p = fx("modrinth-project.json") as MrProject;
  const vs = fx("modrinth-versions.json") as MrVersion[];
