import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { makeZip } from "./_mods-zip-fixture";
import {
  checkArchive,
  checkBlocklist,
  checkCompat,
  checkIntegrity,
  checkLicense,
  checkMetadata,
  checkSource,
  isTraversalName,
  smokeOutcome,
  type Checks,
} from "../lib/mod-verify/checks";
import { badgeSentence, checkList, deriveStatus, expiryFrom, isBadgeLive, VERIFY_TTL_DAYS } from "../lib/mod-verify/status";
import { evaluateSmokeLog, runSmoke, type SmokeInfra, type SmokeTarget } from "../lib/mod-verify/smoke";
import { pickVersion } from "../lib/mod-verify/preflight";
import { hardenModHtml, safeHref } from "../lib/mod-html-harden";
import { buildBrowseWhere, normQuery, parseDeps, clientRequired } from "../lib/mods-browse";

const h = (b: Buffer) => ({
  sha1: createHash("sha1").update(b).digest("hex"),
  sha256: createHash("sha256").update(b).digest("hex"),
  sha512: createHash("sha512").update(b).digest("hex"),
});
const pass = { result: "pass" as const, detail: "" };

test("licence: open SPDX passes, ARR/unknown are unmet (never pass)", () => {
  assert.equal(checkLicense("MIT").result, "pass");
  assert.equal(checkLicense("LGPL-3.0-only").result, "pass");
  assert.equal(checkLicense("All Rights Reserved").result, "unmet");
  assert.equal(checkLicense("LicenseRef-Custom").result, "unmet");
  assert.equal(checkLicense(null).result, "unmet");
});

test("source: allow-listed source + https + allow-listed host only", () => {
  assert.equal(checkSource("modrinth", "https://cdn.modrinth.com/data/x/versions/y/a.jar").result, "pass");
  assert.equal(checkSource("modrinth", "http://cdn.modrinth.com/a.jar").result, "fail");
  assert.equal(checkSource("modrinth", "https://evil.example.com/a.jar").result, "fail");
  assert.equal(checkSource("spigotmc", "https://cdn.spiget.org/a.jar").result, "unmet");
  assert.equal(checkSource("modrinth", null).result, "unmet");
  assert.equal(checkSource("modrinth", "not a url").result, "fail");
});

test("integrity: mismatch fails, match passes, no published hash is unmet", () => {
  const b = Buffer.from("hello");
  const c = h(b);
  assert.equal(checkIntegrity({ sha512: c.sha512 }, c).result, "pass");
  assert.equal(checkIntegrity({ sha1: c.sha1, sha512: c.sha512 }, c).result, "pass");
  assert.equal(checkIntegrity({ sha512: "0".repeat(128) }, c).result, "fail");
  assert.equal(checkIntegrity({ sha1: c.sha1.toUpperCase() }, c).result, "pass");
  assert.equal(checkIntegrity({}, c).result, "unmet");
  assert.equal(checkIntegrity({ sha1: c.sha1 }, null).result, "pending");
});

test("blocklist: a blocked computed OR declared hash fails", () => {
  const c = h(Buffer.from("x"));
  assert.equal(checkBlocklist(c, {}, new Set()).result, "pass");
  assert.equal(checkBlocklist(c, {}, new Set([c.sha256])).result, "fail");
  assert.equal(checkBlocklist(null, { sha1: "ab".repeat(20) }, new Set(["ab".repeat(20)])).result, "fail");
  assert.equal(checkBlocklist(null, {}, new Set()).result, "pending");
});

test("archive: clean jar passes; traversal, bad CRC, scripts, wrong type are caught", () => {
  const jar = makeZip([{ name: "META-INF/MANIFEST.MF", data: "x" }, { name: "com/a/B.class", data: "y" }]);
  assert.equal(checkArchive("minecraft", "a.jar", jar).result, "pass");
  assert.equal(checkArchive("minecraft", "a.jar", makeZip([{ name: "../../etc/cron.d/x", data: "x" }])).result, "fail");
  assert.equal(checkArchive("minecraft", "a.jar", makeZip([{ name: "a.txt", data: "x", badCrc: true }])).result, "fail");
  assert.equal(checkArchive("minecraft", "a.jar", makeZip([{ name: "a.txt", data: "x", symlink: true }])).result, "fail");
  assert.equal(checkArchive("minecraft", "a.jar", makeZip([{ name: "run.bat", data: "x" }])).result, "unmet");
  assert.equal(checkArchive("minecraft", "a.exe", Buffer.from("MZ")).result, "unmet");
  assert.equal(checkArchive("minecraft", "a.jar", makeZip([{ name: "natives/sqlite.so", data: "x" }])).result, "warn");
  assert.equal(checkArchive("valheim", "p.zip", makeZip([{ name: "plugins/Mod.dll", data: "x" }])).result, "pass");
  assert.equal(checkArchive("rust", "Vanish.cs", Buffer.from("// plugin")).result, "pass");
  assert.equal(checkArchive("minecraft", "a.jar", null).result, "pending");
  assert.ok(isTraversalName("a/../../b"));
  assert.ok(isTraversalName("C:/x"));
  assert.ok(!isTraversalName("a/b..c/d"));
});

test("archive: zip bomb (ratio) is refused", () => {
  const big = Buffer.alloc(8 * 1024 * 1024, 0x61);
  assert.equal(checkArchive("minecraft", "a.jar", makeZip([{ name: "bomb.txt", data: big }])).result, "fail");
});

test("metadata: lists exactly what's missing", () => {
  const full = { name: "A", description: "d", license: "MIT", authorName: "x", iconUrl: "https://i", versionNumber: "1", fileName: "a.jar", fileBytes: 10 };
  assert.equal(checkMetadata(full).result, "pass");
  const r = checkMetadata({ ...full, license: null, iconUrl: null, fileBytes: 0 });
  assert.equal(r.result, "unmet");
  assert.match(r.detail, /licence, icon, file size/);
});

test("compat: versioned families need the exact version; loaders must overlap", () => {
  assert.equal(checkCompat("minecraft", "1.21.1", ["1.21", "1.21.1"], "paper", ["paper", "spigot"], ["paper", "spigot", "bukkit"]).result, "pass");
  assert.equal(checkCompat("minecraft", "1.21.4", ["1.21.1"], "paper", ["paper"]).result, "unmet");
  assert.equal(checkCompat("minecraft", "1.21.1", ["1.21.1"], "paper", ["fabric"], ["paper", "spigot", "bukkit"]).result, "unmet");
  assert.equal(checkCompat("minecraft", "any", ["1.21.1"], "", []).result, "unmet");
  assert.equal(checkCompat("valheim", "any", [], "", []).result, "pass");
});

const ALL_PASS: Checks = { license: pass, source: pass, integrity: pass, archive: pass, blocklist: pass, metadata: pass, compat: pass, smoke: pass };

test("status: VERIFIED only when every check passes incl. smoke; any fail flags; revoked is sticky", () => {
  assert.equal(deriveStatus(ALL_PASS), "VERIFIED");
  assert.equal(deriveStatus({ ...ALL_PASS, archive: { result: "warn", detail: "" } }), "VERIFIED");
  assert.equal(deriveStatus({ ...ALL_PASS, smoke: { result: "pending", detail: "" } }), "UNVERIFIED");
  assert.equal(deriveStatus({ ...ALL_PASS, license: { result: "unmet", detail: "" } }), "UNVERIFIED");
  assert.equal(deriveStatus({ ...ALL_PASS, metadata: { result: "warn", detail: "" } }), "UNVERIFIED");
  assert.equal(deriveStatus({ ...ALL_PASS, integrity: { result: "fail", detail: "" } }), "FLAGGED");
  const { smoke: _s, ...noSmoke } = ALL_PASS;
  assert.equal(deriveStatus(noSmoke), "UNVERIFIED");
  assert.equal(deriveStatus(ALL_PASS, "REVOKED"), "REVOKED");
});

test("badge: live only while VERIFIED and unexpired; copy never overclaims", () => {
  const at = new Date("2026-10-01T00:00:00Z");
  const row = { status: "VERIFIED", gameVersion: "1.21.1", loader: "paper", verifiedAt: at, expiresAt: expiryFrom(at) };
  assert.equal(VERIFY_TTL_DAYS, 30);
  assert.ok(isBadgeLive(row, new Date("2026-10-15T00:00:00Z")));
  assert.ok(!isBadgeLive(row, new Date("2026-11-01T00:00:00Z")));
  assert.ok(!isBadgeLive({ ...row, status: "REVOKED" }, at));
  assert.ok(!isBadgeLive({ ...row, status: "FLAGGED" }, at));
  assert.ok(!isBadgeLive({ ...row, expiresAt: null }, at));
  const s = badgeSentence("Minecraft", row);
  assert.equal(s, "Nxeon Verified: installed and started successfully on Minecraft 1.21.1 (paper) on Oct 1, 2026; licence and file integrity checked.");
  assert.doesNotMatch(s, /secure|safe|malware|guarantee/i);
  const list = checkList({ smoke: pass, license: pass, bogus: pass });
  assert.deepEqual(list.map((c) => c.key), ["smoke", "license"]);
});

test("smoke log evaluation: paper plugin enable, fabric mod list, crash, not loaded", () => {
  const t: SmokeTarget = { taskId: "t", gameModId: "m", modName: "LuckPerms", modSlug: "luckperms", sourceId: "luckperms", family: "minecraft", gameVersion: "1.21.1", loader: "paper" };
  const ok = '[12:00:01 INFO]: [LuckPerms] Enabling LuckPerms v5.4.141\n[12:00:09 INFO]: Done (8.123s)! For help, type "help"';
  assert.deepEqual({ ...evaluateSmokeLog(t, ok), detail: "" }, { started: true, loaded: true, crashed: false, detail: "" });
  const fabric = '[main/INFO]: Loading 3 mods:\n\t- fabric-api 0.100.0\n\t- lithium 0.13.0\n[Server thread/INFO]: Done (3.2s)! For help, type "help"';
  assert.equal(evaluateSmokeLog({ ...t, modName: "Lithium", modSlug: "lithium", loader: "fabric" }, fabric).loaded, true);
  const notLoaded = '[12:00:09 INFO]: Done (8.1s)! For help, type "help"';
  const r = evaluateSmokeLog(t, notLoaded);
  assert.equal(r.started, true);
  assert.equal(r.loaded, false);
  const errLine = '[ERROR]: Could not load plugin LuckPerms: Enabling LuckPerms failed\nDone (1s)! For help, type "help"';
  assert.equal(evaluateSmokeLog(t, errLine).loaded, false);
  const crash = "---- Minecraft Crash Report ----\nThis crash report has been saved to: crash.txt";
  assert.equal(evaluateSmokeLog(t, crash).crashed, true);
  assert.equal(evaluateSmokeLog({ ...t, family: "palworld" }, ok).started, false);
});

test("smoke outcome mapping", () => {
  assert.equal(smokeOutcome({ installed: true, started: true, loaded: true, crashed: false, detail: "" }).result, "pass");
  assert.equal(smokeOutcome({ installed: true, started: true, loaded: true, crashed: true, detail: "" }).result, "fail");
  assert.equal(smokeOutcome({ installed: true, started: false, loaded: null, crashed: false, detail: "" }).result, "fail");
  assert.equal(smokeOutcome({ installed: false, started: false, loaded: null, crashed: false, detail: "" }).result, "unmet");
  assert.equal(smokeOutcome({ installed: true, started: true, loaded: false, crashed: false, detail: "" }).result, "unmet");
});

function fakeInfra(over: Partial<SmokeInfra> = {}) {
  const calls: string[] = [];
  const infra: SmokeInfra = {
    provision: async () => (calls.push("provision"), { serverId: "srv1" }),
    install: async () => (calls.push("install"), { ok: true, detail: "installed" }),
    restart: async () => (calls.push("restart"), { ok: true }),
    readLog: async () => (calls.push("log"), '[LuckPerms] Enabling LuckPerms v5\nDone (2s)! For help, type "help"'),
    teardown: async () => void calls.push("teardown"),
    ...over,
  };
  return { infra, calls };
}
const T: SmokeTarget = { taskId: "t1", gameModId: "m", modName: "LuckPerms", modSlug: "luckperms", sourceId: "luckperms", family: "minecraft", gameVersion: "1.21.1", loader: "paper" };

test("smoke harness: full pass runs every step and tears down", async () => {
  const { infra, calls } = fakeInfra();
  const r = await runSmoke(T, infra);
  assert.equal(r.outcome.result, "pass");
  assert.deepEqual(calls, ["provision", "install", "restart", "log", "teardown"]);
  assert.ok(r.tornDown);
});

test("smoke harness: teardown still runs when install throws", async () => {
  const { infra, calls } = fakeInfra({ install: async () => { throw new Error("boom"); } });
  const r = await runSmoke(T, infra);
  assert.notEqual(r.outcome.result, "pass");
  assert.ok(calls.includes("teardown"));
  assert.ok(r.tornDown);
});

test("smoke harness: failed provision never tears down a server it didn't get; unsupported family is a no-op", async () => {
  const { infra, calls } = fakeInfra({ provision: async () => ({ error: "no capacity" }) });
  const r = await runSmoke(T, infra);
  assert.equal(r.outcome.result, "unmet");
  assert.ok(!calls.includes("teardown"));
  const u = fakeInfra();
  const r2 = await runSmoke({ ...T, family: "palworld" }, u.infra);
  assert.equal(r2.outcome.result, "unmet");
  assert.equal(u.calls.length, 0);
});

test("pickVersion: newest release that lists the version + loader", () => {
  const d = (s: string) => new Date(s);
  const vs = [
    { id: "a", gameVersions: ["1.21.1"], loaders: ["fabric"], channel: "release", publishedAt: d("2026-09-01") },
    { id: "b", gameVersions: ["1.21.1"], loaders: ["paper"], channel: "beta", publishedAt: d("2026-09-20") },
    { id: "c", gameVersions: ["1.21.1"], loaders: ["paper"], channel: "release", publishedAt: d("2026-09-10") },
    { id: "e", gameVersions: ["1.20.4"], loaders: ["paper"], channel: "release", publishedAt: d("2026-09-30") },
  ];
  assert.equal(pickVersion(vs, "minecraft", "1.21.1", "paper")?.id, "c");
  assert.equal(pickVersion(vs, "minecraft", "1.21.1", "fabric")?.id, "a");
  assert.equal(pickVersion(vs, "minecraft", "1.19", "paper"), null);
});

test("html harden: XSS vectors are neutralised, safe markup survives", () => {
  const bad = [
    '<script>alert(1)</script>ok',
    '<img src=x onerror=alert(1)>',
    '<img src="javascript:alert(1)">',
    '<a href="javascript:alert(1)">x</a>',
    '<a href="&#106;avascript:alert(1)">x</a>',
    '<a href="//evil.com">x</a>',
    '<iframe src="https://evil.com"></iframe>',
    '<svg><script>alert(1)</script></svg>',
    '<p onclick="alert(1)" style="x">hi</p>',
    '<style>body{display:none}</style>',
    '<img src="https://a/b.png" onerror="alert(1)">',
    '<a href="https://x.com" onmouseover="alert(1)">x</a>',
    '<div><img src=x onerror=alert(1)//',
  ];
  for (const b of bad) {
    const out = hardenModHtml(b);
    assert.doesNotMatch(out, /<script|onerror|onclick|onmouseover|javascript:|<iframe|<style|<svg|style=/i, `${b} -> ${out}`);
  }
  assert.equal(hardenModHtml('<script>alert(1)</script>ok'), "ok");
  const good = hardenModHtml('<h1 class="x">Title</h1><p>Hi <a href="https://modrinth.com/mod/x">link</a></p><img src="https://cdn.modrinth.com/a.png" alt="s"><ul><li>a</li></ul>');
  assert.match(good, /<h3>Title<\/h3>/);
  assert.match(good, /<a href="https:\/\/modrinth.com\/mod\/x" target="_blank" rel="noopener noreferrer nofollow ugc">link<\/a>/);
  assert.match(good, /<img src="https:\/\/cdn.modrinth.com\/a.png" alt="s" loading="lazy"/);
  assert.doesNotMatch(good, /class=/);
  assert.equal(hardenModHtml("<p>unclosed"), "<p>unclosed</p>");
  assert.equal(hardenModHtml("a < b > c"), "a &lt; b &gt; c");
  assert.equal(safeHref("/mods/x"), "/mods/x");
  assert.equal(safeHref("/\\evil.com"), null);
  // Output of the first-pass renderer (classes, escaped text) round-trips safely.
  assert.equal(hardenModHtml('<p class="mb-4">&lt;b&gt; &amp; x</p>'), "<p>&lt;b&gt; &amp; x</p>");
});

test("deps: modrinth / hangar / factorio shapes normalise", () => {
  const mr = parseDeps("modrinth", [
    { project_id: "P7dR8mSH", dependency_type: "required" },
    { project_id: "mOgUt4GM", dependency_type: "optional" },
    { project_id: "9s6osm5g", dependency_type: "embedded" },
    { project_id: "P7dR8mSH", dependency_type: "required" },
  ]);
  assert.deepEqual(mr.map((d) => [d.kind, d.projectId]), [["required", "P7dR8mSH"], ["optional", "mOgUt4GM"], ["embedded", "9s6osm5g"]]);
  const hg = parseDeps("hangar", { PAPER: [{ name: "Vault", required: true, externalUrl: "http://x.org/v" }, { name: "PlaceholderAPI", required: false }] });
  assert.deepEqual(hg.map((d) => [d.kind, d.name, d.url ?? null]), [["required", "Vault", "https://x.org/v"], ["optional", "PlaceholderAPI", null]]);
  const fz = parseDeps("factorio_portal", ["base >= 1.1", "? flib >= 0.12", "! bad-mod", "stdlib"]);
  assert.deepEqual(fz.map((d) => [d.kind, d.name]), [["optional", "flib"], ["incompatible", "bad-mod"], ["required", "stdlib"]]);
  assert.deepEqual(parseDeps("x", null), []);
});

test("browse query: untrusted input is normalised; compatible-only is the default", () => {
  const q = normQuery({ q: "  sodium ".repeat(30), sort: "drop table" as never, page: -5, gameVersion: "1.21.1; rm -rf", loader: "PAPER" });
  assert.equal(q.q.length, 80);
  assert.equal(q.sort, "popular");
  assert.equal(q.page, 1);
  assert.equal(q.gameVersion, null);
  assert.equal(q.loader, "paper");
  assert.equal(q.compatibleOnly, true);
  assert.equal(normQuery({ compatibleOnly: false }).compatibleOnly, false);
  const w = JSON.stringify(buildBrowseWhere("minecraft", normQuery({}), { variant: "paper", pinnedVersion: "1.21.1" }, ["a", "b"]));
  assert.match(w, /"has":"1.21.1"/);
  assert.match(w, /"hasSome":\["paper","spigot","bukkit","datapack"\]/);
  assert.match(w, /"in":\["a","b"\]/);
  const loose = JSON.stringify(buildBrowseWhere("minecraft", normQuery({ compatibleOnly: false }), { variant: "paper", pinnedVersion: "1.21.1" }, null));
  assert.doesNotMatch(loose, /hasSome|1\.21\.1/);
});

test("client-side flag degrades: unknown column => null", () => {
  assert.equal(clientRequired({}), null);
  assert.equal(clientRequired({ clientSide: "required" }), true);
