"use client";

import { useEffect, useId, useRef, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import type { BadgeView } from "@/lib/mods-browse";

const RESULT: Record<string, { icon: string; cls: string; label: string }> = {
  pass: { icon: "checkcircle", cls: "text-emerald-300", label: "Passed" },
  warn: { icon: "warncircle", cls: "text-amber-300", label: "Passed with a note" },
  unmet: { icon: "warncircle", cls: "text-tx-faint", label: "Not confirmed" },
  fail: { icon: "xcircle", cls: "text-red-300", label: "Failed" },
  pending: { icon: "clock", cls: "text-tx-faint", label: "Pending" },
  skipped: { icon: "dotgrey", cls: "text-tx-faint", label: "Not applicable" },
};

/**
 * The Nxeon Verified chip + an explainer popover saying EXACTLY what was
 * verified, on what, and when. Click/Enter toggles; Esc or an outside click
 * closes; focus returns to the chip. The popover is non-modal (role=dialog,
 * aria-modal=false) so it never traps the page.
 */
export function VerifiedBadge({ badge, size = "sm", stopPropagation = false }: { badge: BadgeView; size?: "sm" | "md"; stopPropagation?: boolean }) {
  const [open, setOpen] = useState(false);
  const btn = useRef<HTMLButtonElement>(null);
  const pop = useRef<HTMLDivElement>(null);
  const id = useId();

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.stopPropagation();
        setOpen(false);
        btn.current?.focus();
      }
    };
    const onDown = (e: MouseEvent) => {
      if (!pop.current?.contains(e.target as Node) && !btn.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("keydown", onKey, true);
    document.addEventListener("mousedown", onDown);
    return () => {
      document.removeEventListener("keydown", onKey, true);
      document.removeEventListener("mousedown", onDown);
    };
  }, [open]);

  const chip =
    size === "md"
      ? "gap-1.5 rounded-[9px] px-2.5 py-1 text-[11.5px]"
      : "gap-1 rounded-[7px] px-1.5 py-0.5 text-[10px]";

  return (
    <span className="relative inline-flex" onClick={(e) => stopPropagation && e.stopPropagation()}>
      <button
        ref={btn}
        type="button"
        aria-expanded={open}
        aria-controls={id}
        aria-label={`Nxeon Verified for ${badge.gameVersion === "any" ? "this game" : badge.gameVersion} — what this means`}
        onClick={(e) => {
          if (stopPropagation) e.stopPropagation();
          setOpen((o) => !o);
        }}
        className={"inline-flex items-center border border-cyan-300/45 bg-[linear-gradient(120deg,rgba(59,107,232,.28),rgba(123,63,239,.3))] font-bold uppercase tracking-wide text-cyan-100 shadow-[0_0_14px_-4px_rgba(62,220,242,.55)] transition hover:border-cyan-200/70 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cyan-300 " + chip}
      >
        <Icon name="shieldcheck" size={size === "md" ? 12 : 10} tone="inherit" />
        Nxeon Verified
      </button>
      {open && (
        <div
          ref={pop}
          id={id}
          role="dialog"
          aria-modal="false"
          aria-label="What Nxeon Verified means"
          className="nx-dark-island absolute left-0 top-[calc(100%+8px)] z-[70] w-[min(340px,calc(100vw-32px))] rounded-[14px] border border-cyan-300/30 bg-[linear-gradient(180deg,rgba(14,26,56,.98),rgba(4,10,26,.99))] p-3.5 text-left shadow-[0_18px_50px_-12px_rgba(0,0,0,.8)]"
        >
          <p className="flex items-center gap-1.5 text-[12.5px] font-extrabold text-white">
            <Icon name="shieldcheck" size={13} tone="inherit" className="text-cyan-300" /> Nxeon Verified
          </p>
          <p className="mt-1.5 text-[12px] leading-relaxed text-white/80">{badge.sentence}</p>
          {badge.versionNumber && <p className="mt-1 text-[11px] text-tx-faint">Build checked: <span className="font-mono text-white/70">{badge.versionNumber}</span></p>}
          {badge.checks.length > 0 && (
            <ul className="mt-2.5 flex flex-col gap-1.5 border-t border-white/10 pt-2.5">
              {badge.checks.map((c) => {
                const r = RESULT[c.result] ?? RESULT.pending;
                return (
                  <li key={c.key} className="flex items-start gap-2 text-[11.5px] leading-snug">
                    <span className={"mt-[1px] flex-none " + r.cls} aria-label={r.label}><Icon name={r.icon} size={11} tone="inherit" /></span>
                    <span className="min-w-0">
                      <span className="font-semibold text-white/90">{c.label}</span>
                      {c.detail && <span className="block text-tx-faint">{c.detail}</span>}
                    </span>
                  </li>
                );
              })}
            </ul>
          )}
          <p className="mt-2.5 border-t border-white/10 pt-2.5 text-[11px] leading-relaxed text-tx-faint">
            Checked {badge.verifiedAt} · expires {badge.expiresAt}. {badge.disclaimer}
          </p>
          <a href="/mods/verified" target="_blank" rel="noopener" className="mt-2 inline-flex items-center gap-1 text-[11.5px] font-semibold text-cyan-300 hover:text-white">
            How verification works <Icon name="external" size={10} tone="inherit" />
          </a>
        </div>
      )}
    </span>
  );
}

