"use client";

import { Icon } from "@/components/nx/Icon";
import type { Compat } from "@/lib/mods/types";

export const SOURCE_LABEL: Record<string, string> = {
  modrinth: "Modrinth", spigotmc: "SpigotMC", hangar: "Hangar", curseforge: "CurseForge", steam_workshop: "Steam Workshop",
  umod: "uMod", github: "GitHub", nexus: "Nexus Mods", thunderstore: "Thunderstore", codefling: "Codefling", mod_io: "mod.io",
  vintagestory_moddb: "Vintage Story ModDB", factorio_portal: "Factorio Mod Portal", ficsit: "ficsit.app", reforger_workshop: "Arma Reforger Workshop",
};

export function fileSize(bytes: number | null | undefined): string | null {
  if (!bytes || bytes <= 0) return null;
  return bytes >= 1024 ** 3 ? `${(bytes / 1024 ** 3).toFixed(1)} GB` : bytes >= 1024 * 1024 ? `${(bytes / 1024 / 1024).toFixed(bytes >= 10 * 1024 * 1024 ? 0 : 1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

export function compactNum(n: number | null | undefined): string | null {
  if (!n || n < 1) return null;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
  if (n >= 1_000) return `${(n / 1000).toFixed(n >= 10_000 ? 0 : 1)}k`;
  return String(n);
}

/** "3 days ago" from an ISO string, computed at render (client only). */
export function ago(iso: string | null | undefined, now = Date.now()): string | null {
  if (!iso) return null;
  const t = new Date(iso).getTime();
  if (!Number.isFinite(t)) return null;
  const d = Math.max(0, Math.round((now - t) / 86_400_000));
  if (d < 1) return "today";
  if (d < 2) return "yesterday";
  if (d < 31) return `${d} days ago`;
  if (d < 365) return `${Math.round(d / 30)} mo ago`;
  return `${(d / 365).toFixed(d >= 3650 ? 0 : 1)} yr ago`;
}

export const STATE: Record<string, { label: string; cls: string }> = {
  INSTALLED: { label: "Installed", cls: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300" },
  DISABLED: { label: "Disabled", cls: "border-white/20 bg-white/[0.06] text-tx-dim" },
  INSTALLING: { label: "Installing", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  UPDATING: { label: "Updating", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  ENABLING: { label: "Enabling", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  DISABLING: { label: "Disabling", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
  REMOVING: { label: "Removing", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
  FAILED: { label: "Failed", cls: "border-red-500/40 bg-red-500/10 text-red-300" },
};
export const PENDING = new Set(["INSTALLING", "UPDATING", "ENABLING", "DISABLING", "REMOVING"]);

export const COMPAT: Record<string, { icon: string; cls: string; label: string }> = {
  ok: { icon: "checkcircle", cls: "border-emerald-500/35 bg-emerald-500/10 text-emerald-300", label: "Fits your server" },
  mismatch: { icon: "warntriangle", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300", label: "Not for this server" },
  unknown: { icon: "warncircle", cls: "border-white/15 bg-white/[0.05] text-tx-dim", label: "Checked at install" },
  unsupported: { icon: "xcircle", cls: "border-red-500/35 bg-red-500/10 text-red-300", label: "Client-only" },
};

export function Chip({ cls, icon, children, title }: { cls: string; icon?: string; children: React.ReactNode; title?: string }) {
  return (
    <span title={title} className={"inline-flex items-center gap-1 whitespace-nowrap rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + cls}>
      {icon && <Icon name={icon} size={10} tone="inherit" />}
      {children}
    </span>
  );
}

export function CompatChip({ compat }: { compat: Compat | null }) {
  if (!compat) return null;
  const c = COMPAT[compat.verdict] ?? COMPAT.unknown;
  return <Chip cls={c.cls} icon={c.icon} title={compat.detail}>{c.label}</Chip>;
}

export function ModIcon({ src, size = 44, alt = "" }: { src: string | null; size?: number; alt?: string }) {
  return (
    <span className="grid flex-none place-items-center overflow-hidden rounded-[12px] border border-rim-hi bg-well" style={{ width: size, height: size }}>
      {src
        /* eslint-disable-next-line @next/next/no-img-element -- mirrored/upstream mod icon */
        ? <img src={src} alt={alt} loading="lazy" decoding="async" referrerPolicy="no-referrer" className="h-full w-full object-cover" />
        : <Icon name="cube" size={Math.round(size * 0.36)} />}
    </span>
  );
}

export const btnGhost = "rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white disabled:opacity-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand-400";

input.content:
"use client";

import { Icon } from "@/components/nx/Icon";
import type { BrowseCard } from "@/lib/mods-browse";
import { Chip, CompatChip, ModIcon, PENDING, SOURCE_LABEL, STATE, ago, compactNum, fileSize } from "./bits";
import { VerifiedBadge } from "./VerifiedBadge";

/**
 * One catalogue card. The whole card opens the preview (a real <button> for
 * the title so keyboard users get it); Install is its own button and does not
 * open the preview. Every number is the source's own, or absent.
 */
export function ModCard({ m, unavailable, busy, onOpen, onInstall }: { m: BrowseCard; unavailable: boolean; busy: boolean; onOpen: () => void; onInstall: () => void }) {
  const st = m.status ? STATE[m.status] : null;
  const installed = m.status === "INSTALLED" || m.status === "DISABLED" || (!!m.status && PENDING.has(m.status));
  const dl = compactNum(m.downloads);
  const up = ago(m.updatedAt);
  const size = fileSize(m.fileBytes);
  return (
    <article
      onClick={onOpen}
      className="group relative flex cursor-pointer flex-col gap-2.5 rounded-[15px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.55),rgba(2,7,20,.66))] p-3.5 transition hover:-translate-y-[1px] hover:border-brand-400/45 hover:shadow-[0_10px_30px_-18px_rgba(123,63,239,.7)]"
    >
      <div className="flex items-start gap-3">
        <ModIcon src={m.icon} />
        <div className="flex min-w-0 flex-1 flex-col">
          <h3 className="min-w-0">
            <button
              type="button"
              onClick={(e) => { e.stopPropagation(); onOpen(); }}
              className="block max-w-full truncate text-left text-[14px] font-bold text-white outline-none after:absolute after:inset-0 after:rounded-[15px] focus-visible:after:outline focus-visible:after:outline-2 focus-visible:after:outline-brand-400"
            >
              {m.name}
            </button>
          </h3>
          <p className="mt-0.5 truncate text-[11.5px] text-tx-faint">
            {m.author ? <>by <span className="text-tx-dim">{m.author}</span> · </> : null}
            {m.category} · {SOURCE_LABEL[m.source] ?? m.source}
          </p>
        </div>
      </div>

      <div className="relative z-[1] flex flex-wrap items-center gap-1.5">
        {m.verified && <VerifiedBadge badge={m.verified} stopPropagation />}
        {!unavailable && <CompatChip compat={m.compat} />}
        {st && <Chip cls={st.cls}>{st.label}{m.status === "INSTALLED" && m.version ? ` · ${m.version}` : ""}</Chip>}
        {m.featured && <Chip cls="border-[#a86bff]/45 bg-[#a86bff]/12 text-[#c4a6ff]">Featured</Chip>}
        {m.clientRequired && <Chip cls="border-amber-500/40 bg-amber-500/10 text-amber-200" icon="users" title="Players need this mod installed in their own game too">Players need it too</Chip>}
        {m.impact === "heavy" && <Chip cls="border-amber-500/45 bg-amber-500/12 text-amber-300">Heavy</Chip>}
      </div>

      {m.summary && <p className="line-clamp-2 text-[12.5px] leading-relaxed text-tx-dim">{m.summary}</p>}

      <div className="mt-auto flex flex-wrap items-center gap-x-3 gap-y-1 text-[11.5px] text-tx-faint">
        {dl && <span className="num inline-flex items-center gap-1"><Icon name="download" size={11} tone="inherit" />{dl}</span>}
        {up && <span className="inline-flex items-center gap-1"><Icon name="clock" size={11} tone="inherit" />{up}</span>}
        {size && <span className="num">{size}</span>}
        {m.dependencyCount > 0 && <span>+{m.dependencyCount} dep{m.dependencyCount === 1 ? "" : "s"}</span>}
      </div>

      {m.status === "FAILED" && m.error && <p className="relative z-[1] rounded-[9px] border border-red-500/30 bg-red-500/[0.07] px-2.5 py-1.5 text-[11.5px] leading-snug text-red-300">{m.error}</p>}

      <div className="relative z-[1] flex items-center gap-2 border-t border-white/[0.06] pt-2.5">
        {installed ? (
          <span className="text-[11.5px] text-tx-faint">{m.status === "INSTALLED" ? "On your server" : st?.label ?? ""}</span>
        ) : m.manualInstall ? (
          <span className="line-clamp-1 min-w-0 flex-1 text-[11.5px] leading-snug text-tx-faint" title={m.manualInstall}>{m.manualInstall}</span>
        ) : (
          <button
            type="button"
            disabled={busy}
            onClick={(e) => { e.stopPropagation(); onInstall(); }}
            className="nx-cta px-4 py-1.5 text-[12.5px] disabled:opacity-50"
            aria-label={`Install ${m.name}`}
          >
            {m.status === "FAILED" ? "Try again" : "Install"}
          </button>
        )}
        <span className="ml-auto inline-flex items-center gap-1 text-[11.5px] font-semibold text-tx-faint transition group-hover:text-white">
          Details <Icon name="external" size={10} tone="inherit" className="opacity-0" />
        </span>
      </div>
    </article>
  );
}

export function ModCardSkeleton() {
  return (
    <div aria-hidden className="flex animate-pulse flex-col gap-3 rounded-[15px] border border-rim-hi bg-[rgba(6,14,36,.55)] p-3.5">
      <div className="flex items-start gap-3">
        <span className="h-[44px] w-[44px] rounded-[12px] bg-white/[0.07]" />
        <div className="flex flex-1 flex-col gap-2 pt-1">
          <span className="h-3 w-2/3 rounded bg-white/[0.08]" />
          <span className="h-2.5 w-1/2 rounded bg-white/[0.05]" />
        </div>
      </div>
      <span className="h-2.5 w-full rounded bg-white/[0.05]" />
      <span className="h-2.5 w-4/5 rounded bg-white/[0.05]" />
      <div className="mt-1 flex gap-2 border-t border-white/[0.05] pt-3">
        <span className="h-7 w-20 rounded-[10px] bg-white/[0.07]" />
      </div>
    </div>
  );
}

