input.content:
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { browseServerMods, serverModFacets } from "@/lib/actions-mod-browse";
import type { BrowseCard, BrowseSort } from "@/lib/mods-browse";
import { ModCard, ModCardSkeleton } from "./ModCard";
import { ModPreviewModal } from "./ModPreviewModal";
import { btnGhost } from "./bits";

type Facets = Awaited<ReturnType<typeof serverModFacets>>;
export type ModOp = "install" | "remove" | "update" | "disable" | "enable";

const field = "flex h-[40px] items-center rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3 focus-within:border-brand-400/60";
const selectCls = "w-full min-w-0 cursor-pointer bg-transparent text-[12.5px] font-semibold text-tx-dim outline-none";

function Toggle({ on, onChange, label, icon, hint }: { on: boolean; onChange: (v: boolean) => void; label: string; icon: string; hint?: string }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      title={hint}
      onClick={() => onChange(!on)}
      className={
        "flex h-[40px] items-center gap-2 whitespace-nowrap rounded-[11px] border px-3 text-[12px] font-semibold transition focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand-400 " +
        (on ? "border-[#7b3fef]/60 bg-[#7b3fef]/20 text-white" : "border-rim-hi bg-[rgba(6,14,36,.72)] text-tx-dim hover:text-white")
      }
    >
      <span className={"relative h-[16px] w-[28px] flex-none rounded-full transition " + (on ? "bg-[linear-gradient(90deg,#3b6be8,#7b3fef)]" : "bg-white/15")}>
        <span className={"absolute top-[2px] h-[12px] w-[12px] rounded-full bg-white transition-all " + (on ? "left-[14px]" : "left-[2px]")} />
      </span>
      <Icon name={icon} size={12} tone="inherit" />
      {label}
    </button>
  );
}

/**
 * The customer mod browser: server-side search over the whole catalogue for
 * this game, filtered (version, loader, category, verified) and sorted in the
 * database, "fits my server" on by default, and a preview modal that opens on
 * card click and deep-links as ?mod=<slug>.
 */
export function ModBrowser({
  serverId,
  scope,
  unavailable,
  jobActive,
  refreshKey,
  defaultCategory,
  catalogTotal,
  onInstall,
  onAct,
  onTotal,
}: {
  serverId: string;
  scope: "mods" | "plugins";
  unavailable: boolean;
  jobActive: boolean;
  refreshKey: number;
  defaultCategory: string | null;
  catalogTotal: number;
  onInstall: (m: BrowseCard) => void;
  onAct: (modId: string, op: ModOp) => void;
  onTotal?: (n: number) => void;
}) {
  const [facets, setFacets] = useState<Facets | null>(null);
  const [q, setQ] = useState("");
  const [debQ, setDebQ] = useState("");
  const [category, setCategory] = useState(defaultCategory ?? "all");
  const [sort, setSort] = useState<BrowseSort>("popular");
  const [compatibleOnly, setCompatibleOnly] = useState(!unavailable);
  const [verifiedOnly, setVerifiedOnly] = useState(false);
  const [version, setVersion] = useState(""); // "" = server's own
  const [loader, setLoader] = useState("");
  const [items, setItems] = useState<BrowseCard[]>([]);
  const [total, setTotal] = useState<number | null>(null);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [applied, setApplied] = useState<string | null>(null);
  const [openSlug, setOpenSlug] = useState<string | null>(null);
  const seq = useRef(0);

  useEffect(() => {
    serverModFacets(serverId).then(setFacets).catch(() => setFacets(null));
  }, [serverId]);
  useEffect(() => {
    if (defaultCategory) setCategory(defaultCategory);
  }, [defaultCategory]);
  useEffect(() => {
    const t = setTimeout(() => setDebQ(q.trim()), 250);
    return () => clearTimeout(t);
  }, [q]);

  // Deep link: ?mod=<slug> opens the preview (read after mount — never in a useState initializer).
  useEffect(() => {
    const s = new URLSearchParams(window.location.search).get("mod");
    if (s && /^[A-Za-z0-9._\-]{1,120}$/.test(s)) setOpenSlug(s);
  }, []);
  const setUrlMod = (slug: string | null) => {
    try {
      const u = new URL(window.location.href);
      if (slug) u.searchParams.set("mod", slug);
      else u.searchParams.delete("mod");
      window.history.replaceState(window.history.state, "", u.pathname + u.search + u.hash);
    } catch {}
  };
  const open = (slug: string) => {
    setOpenSlug(slug);
    setUrlMod(slug);
  };
  const close = () => {
    setOpenSlug(null);
    setUrlMod(null);
  };

  const run = useCallback(
    async (p: number, append: boolean) => {
      const my = ++seq.current;
      setLoading(true);
      setError(null);
      const r = await browseServerMods(serverId, {
        q: debQ,
        category,
        sort,
        compatibleOnly,
        verifiedOnly,
        gameVersion: version || undefined,
        loader: loader || undefined,
        page: p,
      }).catch(() => ({ error: "Search failed — check your connection and try again." }) as { error: string });
      if (my !== seq.current) return;
      setLoading(false);
      if ("page" in r && r.page) {
        setItems((prev) => (append ? [...prev, ...r.page!.items] : r.page!.items));
        setTotal(r.page.total);
        setHasMore(r.page.hasMore);
        setPage(p);
        setApplied(r.page.appliedVersion);
        onTotal?.(r.page.total);
      } else {
        setError(("error" in r && r.error) || "Search failed.");
        if (!append) setItems([]);
      }
    },
    [serverId, debQ, category, sort, compatibleOnly, verifiedOnly, version, loader, onTotal],
  );
  useEffect(() => {
    void run(1, false);
  }, [run, refreshKey]);

  const server = facets && "server" in facets ? facets.server : null;
  const f = facets && "facets" in facets ? facets.facets : null;
  const filtered = !!debQ || category !== "all" || !!version || !!loader || verifiedOnly;
