function Toggle({ on, onChange, label, icon, hint }: { on: boolean; onChange: (v: boolean) => void; label: string; icon: string; hint?: string }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      title={hint}
      onClick={() => onChange(!on)}
      className={
        "flex h-[40px] items-center gap-2 whitespace-nowrap rounded-[11px] border px-3 text-[12px] font-semibold transition focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand-400 " +
        (on ? "border-[#7b3fef]/60 bg-[#7b3fef]/20 text-white" : "border-rim-hi bg-[rgba(6,14,36,.72)] text-tx-dim hover:text-white")
      }
    >
      <span className={"relative h-[16px] w-[28px] flex-none rounded-full transition " + (on ? "bg-[linear-gradient(90deg,#3b6be8,#7b3fef)]" : "bg-white/15")}>
        <span className={"absolute top-[2px] h-[12px] w-[12px] rounded-full bg-white transition-all " + (on ? "left-[14px]" : "left-[2px]")} />
