                      {c.featured && <Chip cls="border-[#a86bff]/45 bg-[#a86bff]/12 text-[#c4a6ff]">Featured</Chip>}
                      {c.paid && <Chip cls="border-amber-500/45 bg-amber-500/10 text-amber-300">Paid upstream</Chip>}
                    </div>
                  </div>
                </header>

                {c.summary && <p className="text-[13.5px] leading-relaxed text-white/80">{c.summary}</p>}

                <div className="flex flex-wrap items-center gap-3 rounded-[14px] border border-white/[0.08] bg-white/[0.03] p-3">
                  <div className="min-w-0 flex-1">{cta}</div>
