"use client";

import { useCallback, useEffect, useId, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { Icon } from "@/components/nx/Icon";
import { serverModPreview } from "@/lib/actions-mod-browse";
import type { BrowseCard, ModPreview } from "@/lib/mods-browse";
import { Chip, CompatChip, ModIcon, PENDING, SOURCE_LABEL, STATE, ago, btnGhost, compactNum, fileSize } from "./bits";
import { VerifiedBadge } from "./VerifiedBadge";
import type { ModOp } from "./ModBrowser";

type Tab = "overview" | "versions" | "changelog" | "deps";

/** Scoped typography for sanitised third-party HTML (no classes survive the harden pass). */
const PROSE =
  "text-[13px] leading-relaxed text-tx-dim [overflow-wrap:anywhere] [&_p]:mb-3 [&_h3]:mb-2 [&_h3]:mt-5 [&_h3]:text-[15px] [&_h3]:font-bold [&_h3]:text-white [&_h4]:mb-1.5 [&_h4]:mt-4 [&_h4]:text-[13.5px] [&_h4]:font-bold [&_h4]:text-white " +
  "[&_ul]:mb-3 [&_ul]:list-disc [&_ul]:pl-5 [&_ol]:mb-3 [&_ol]:list-decimal [&_ol]:pl-5 [&_li]:mb-1 [&_li]:marker:text-brand-400 [&_a]:font-semibold [&_a]:text-cyan-300 [&_a]:underline [&_a]:decoration-cyan-300/30 [&_a]:underline-offset-2 hover:[&_a]:text-white " +
  "[&_img]:my-3 [&_img]:inline-block [&_img]:h-auto [&_img]:max-w-full [&_img]:rounded-[10px] [&_strong]:font-semibold [&_strong]:text-white [&_code]:rounded [&_code]:bg-white/[0.07] [&_code]:px-1 [&_code]:py-0.5 [&_code]:font-mono [&_code]:text-[12px] [&_code]:text-cyan-100 " +
  "[&_pre]:mb-3 [&_pre]:overflow-x-auto [&_pre]:rounded-[10px] [&_pre]:border [&_pre]:border-white/10 [&_pre]:bg-black/40 [&_pre]:p-3 [&_pre_code]:bg-transparent [&_pre_code]:p-0 [&_blockquote]:mb-3 [&_blockquote]:border-l-2 [&_blockquote]:border-white/20 [&_blockquote]:pl-3 [&_blockquote]:italic " +
  "[&_hr]:my-4 [&_hr]:border-white/10 [&_table]:mb-3 [&_table]:block [&_table]:max-w-full [&_table]:overflow-x-auto [&_td]:border [&_td]:border-white/10 [&_td]:px-2 [&_td]:py-1 [&_th]:border [&_th]:border-white/10 [&_th]:px-2 [&_th]:py-1 [&_th]:text-left [&_details]:mb-3 [&_summary]:cursor-pointer [&_summary]:font-semibold [&_summary]:text-white";

const FOCUSABLE = 'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

function useFocusTrap(ref: React.RefObject<HTMLElement | null>, active: boolean, onEscape: () => void) {
  useEffect(() => {
    if (!active) return;
    const prev = document.activeElement as HTMLElement | null;
    const node = ref.current;
    const first = node?.querySelector<HTMLElement>("[data-autofocus]") ?? node?.querySelector<HTMLElement>(FOCUSABLE);
    first?.focus({ preventScroll: true });
    const onKey = (e: KeyboardEvent) => {
      if (!node) return;
      if (e.key === "Escape") {
        e.preventDefault();
        onEscape();
        return;
      }
      if (e.key !== "Tab") return;
      const els = [...node.querySelectorAll<HTMLElement>(FOCUSABLE)].filter((el) => el.offsetParent !== null || el === document.activeElement);
      if (!els.length) return;
      const a = els[0];
      const z = els[els.length - 1];
      if (e.shiftKey && document.activeElement === a) {
        e.preventDefault();
        z.focus();
      } else if (!e.shiftKey && document.activeElement === z) {
        e.preventDefault();
        a.focus();
      } else if (!node.contains(document.activeElement)) {
        e.preventDefault();
        a.focus();
      }
    };
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("keydown", onKey);
      prev?.focus?.({ preventScroll: true });
    };
  }, [ref, active, onEscape]);
}

function Lightbox({ images, index, onClose, onIndex }: { images: { src: string; alt: string }[]; index: number; onClose: () => void; onIndex: (i: number) => void }) {
  const ref = useRef<HTMLDivElement>(null);
  const n = images.length;
  const go = useCallback((d: number) => onIndex((index + d + n) % n), [index, n, onIndex]);
  useFocusTrap(ref, true, onClose);
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (e.key === "ArrowRight") go(1);
      if (e.key === "ArrowLeft") go(-1);
    };
    document.addEventListener("keydown", k);
    return () => document.removeEventListener("keydown", k);
  }, [go]);
  const img = images[index];
  return (
    <div ref={ref} role="dialog" aria-modal="true" aria-label={`Screenshot ${index + 1} of ${n}`} className="fixed inset-0 z-[90] flex flex-col bg-black/92 backdrop-blur-sm" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="flex items-center justify-between px-4 py-3 text-[12.5px] text-white/70">
        <span className="num">{index + 1} / {n}</span>
        <button type="button" data-autofocus onClick={onClose} aria-label="Close screenshot" className="grid h-9 w-9 place-items-center rounded-full border border-white/15 bg-white/10 text-white hover:bg-white/20">
          <Icon name="xcircle" size={14} tone="inherit" />
        </button>
      </div>
      <div className="relative flex min-h-0 flex-1 items-center justify-center px-2 pb-6 sm:px-14" onClick={(e) => e.target === e.currentTarget && onClose()}>
        {/* eslint-disable-next-line @next/next/no-img-element -- mirrored screenshot */}
        <img src={img.src} alt={img.alt} referrerPolicy="no-referrer" className="max-h-full max-w-full rounded-[10px] object-contain shadow-2xl" />
        {n > 1 && (
          <>
            <button type="button" onClick={() => go(-1)} aria-label="Previous screenshot" className="absolute left-2 top-1/2 grid h-11 w-11 -translate-y-1/2 place-items-center rounded-full border border-white/15 bg-black/50 text-[20px] text-white hover:bg-black/70 sm:left-4">‹</button>
            <button type="button" onClick={() => go(1)} aria-label="Next screenshot" className="absolute right-2 top-1/2 grid h-11 w-11 -translate-y-1/2 place-items-center rounded-full border border-white/15 bg-black/50 text-[20px] text-white hover:bg-black/70 sm:right-4">›</button>
          </>
        )}
      </div>
    </div>
  );
}

function Gallery({ p, onZoom }: { p: ModPreview; onZoom: (i: number) => void }) {
  const [i, setI] = useState(0);
  const [broken, setBroken] = useState<Record<number, boolean>>({});
  const imgs = p.gallery;
  if (!imgs.length || imgs.every((_, k) => broken[k])) {
    return (
      <div className="relative grid h-[120px] place-items-center overflow-hidden bg-[radial-gradient(70%_120%_at_20%_0%,rgba(123,63,239,.45),transparent_60%),radial-gradient(60%_120%_at_90%_10%,rgba(62,220,242,.22),transparent_60%),linear-gradient(180deg,#0b1636,#050b1d)] sm:h-[150px]">
        <span className="opacity-90"><ModIcon src={p.card.icon} size={64} alt="" /></span>
        <span className="absolute bottom-2 right-3 text-[10.5px] text-white/40">No screenshots published</span>
      </div>
    );
  }
  const cur = broken[i] ? imgs.findIndex((_, k) => !broken[k]) : i;
  return (
    <div className="bg-[#040a1c]">
      <button type="button" onClick={() => onZoom(cur)} className="group relative block aspect-[16/8] w-full overflow-hidden" aria-label={`Open screenshot ${cur + 1} of ${imgs.length} full size`}>
        {/* eslint-disable-next-line @next/next/no-img-element -- mirrored screenshot */}
        <img src={imgs[cur].src} alt={imgs[cur].alt} decoding="async" referrerPolicy="no-referrer" onError={() => setBroken((b) => ({ ...b, [cur]: true }))} className="h-full w-full object-cover transition duration-500 group-hover:scale-[1.015]" />
        <span className="pointer-events-none absolute inset-x-0 bottom-0 h-16 bg-gradient-to-t from-[#040a1c] to-transparent" />
        <span className="absolute bottom-2.5 right-3 rounded-full border border-white/15 bg-black/55 px-2 py-0.5 text-[10.5px] font-semibold text-white/80">{cur + 1} / {imgs.length} · tap to enlarge</span>
      </button>
      {imgs.length > 1 && (
        <div className="flex gap-1.5 overflow-x-auto px-3 pb-3 pt-1 [scrollbar-width:thin]" role="list" aria-label="Screenshots">
          {imgs.map((im, k) =>
            broken[k] ? null : (
              <button key={im.src} role="listitem" type="button" onClick={() => setI(k)} aria-label={`Show screenshot ${k + 1}`} aria-current={k === cur}
                className={"h-[46px] w-[78px] flex-none overflow-hidden rounded-[7px] border transition " + (k === cur ? "border-cyan-300/70" : "border-white/10 opacity-60 hover:opacity-100")}>
                {/* eslint-disable-next-line @next/next/no-img-element -- mirrored thumbnail */}
                <img src={im.src} alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer" onError={() => setBroken((b) => ({ ...b, [k]: true }))} className="h-full w-full object-cover" />
              </button>
            ),
          )}
        </div>
      )}
    </div>
  );
}

function Stat({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex min-w-0 flex-col rounded-[11px] border border-white/[0.07] bg-white/[0.03] px-3 py-2">
      <dt className="text-[10px] font-bold uppercase tracking-[0.12em] text-tx-faint">{label}</dt>
      <dd className="mt-0.5 truncate text-[13px] font-semibold text-white">{children}</dd>
    </div>
  );
}

const FIT: Record<string, { cls: string; label: string }> = {
  ok: { cls: "border-emerald-500/35 bg-emerald-500/10 text-emerald-300", label: "Fits" },
  mismatch: { cls: "border-amber-500/40 bg-amber-500/10 text-amber-300", label: "Not for this server" },
  unknown: { cls: "border-white/15 bg-white/[0.05] text-tx-dim", label: "Checked at install" },
};

export function ModPreviewModal({
  serverId,
  slug,
  unavailable,
  jobActive,
  refreshKey,
  onClose,
  onOpenOther,
  onInstall,
  onAct,
}: {
  serverId: string;
  slug: string;
  unavailable: boolean;
  jobActive: boolean;
  refreshKey: number;
  onClose: () => void;
  onOpenOther: (slug: string) => void;
  onInstall: (m: BrowseCard) => void;
  onAct: (modId: string, op: ModOp) => void;
}) {
  const [p, setP] = useState<ModPreview | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [tab, setTab] = useState<Tab>("overview");
  const [zoom, setZoom] = useState<number | null>(null);
  const [mounted, setMounted] = useState(false);
  const panel = useRef<HTMLDivElement>(null);
  const titleId = useId();
  const tabsId = useId();

  useEffect(() => setMounted(true), []);
  useEffect(() => {
    let live = true;
    setErr(null);
    serverModPreview(serverId, slug)
      .then((r) => {
        if (!live) return;
        if (r.preview) setP(r.preview);
        else setErr(r.error ?? "Couldn't load this mod.");
      })
      .catch(() => live && setErr("Couldn't load this mod — check your connection."));
    return () => { live = false; };
  }, [serverId, slug, refreshKey]);
  useEffect(() => {
    setTab("overview");
    panel.current?.querySelector("[data-scroll]")?.scrollTo({ top: 0 });
  }, [slug]);
  useEffect(() => {
    const o = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = o; };
  }, []);
  const esc = useCallback(() => {
    if (zoom === null) onClose();
  }, [zoom, onClose]);
  useFocusTrap(panel, mounted && zoom === null, esc);

  if (!mounted) return null;
  const c = p?.card;
  const st = c?.status ? STATE[c.status] : null;
  const pending = !!c?.status && PENDING.has(c.status);
  const installed = c?.status === "INSTALLED" || c?.status === "DISABLED";
  const required = p?.deps.filter((d) => d.kind === "required") ?? [];
  const optional = p?.deps.filter((d) => d.kind === "optional") ?? [];
  const incompatible = p?.deps.filter((d) => d.kind === "incompatible") ?? [];
  const changelogs = p?.versions.filter((v) => v.changelogHtml).slice(0, 12) ?? [];
  const best = p?.versions.find((v) => v.id === p.bestVersionId) ?? null;
  const tabs: { k: Tab; label: string; n?: number }[] = [
    { k: "overview", label: "Overview" },
    { k: "versions", label: "Versions", n: p?.versions.length },
    { k: "changelog", label: "Changelog", n: changelogs.length },
    { k: "deps", label: "Dependencies", n: p?.deps.length },
  ];

  const cta = !c ? null : unavailable || c.manualInstall ? (
    <p className="text-[12px] leading-snug text-tx-faint">{c.manualInstall}</p>
  ) : pending ? (
    <span className="inline-flex items-center gap-2 text-[12.5px] font-semibold text-sky-300"><Icon name="refresh" size={12} tone="inherit" className="animate-spin" />{st?.label}…</span>
  ) : installed ? (
    <div className="flex flex-wrap gap-2">
      {c.status === "INSTALLED" && <button type="button" disabled={jobActive} onClick={() => onAct(c.id, "update")} className={btnGhost}>Update</button>}
      {c.status === "DISABLED" && <button type="button" disabled={jobActive} onClick={() => onAct(c.id, "enable")} className={btnGhost}>Enable</button>}
      <button type="button" disabled={jobActive} onClick={() => onAct(c.id, "remove")} className="rounded-[10px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-red-500/50 hover:text-red-300 disabled:opacity-50">Remove</button>
    </div>
  ) : (
    <button type="button" disabled={jobActive} onClick={() => onInstall(c)} className="nx-cta px-5 py-2.5 text-[13px] disabled:opacity-50">
      {c.status === "FAILED" ? "Try again" : required.length ? `Install with ${required.length} dependenc${required.length === 1 ? "y" : "ies"}` : "Install"}
    </button>
  );

  return createPortal(
    <div className="fixed inset-0 z-[60] flex items-end justify-center bg-black/70 backdrop-blur-[3px] sm:items-center sm:p-5" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div
        ref={panel}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="nx-dark-island relative flex max-h-[92dvh] w-full flex-col overflow-hidden rounded-t-[22px] border border-[#7b3fef]/40 bg-[linear-gradient(180deg,rgba(12,24,54,.985),rgba(3,8,22,.995))] shadow-[0_30px_80px_-20px_rgba(0,0,0,.9)] sm:max-h-[88vh] sm:max-w-[920px] sm:rounded-[20px]"
      >
        <span aria-hidden className="mx-auto mt-2 h-1 w-10 flex-none rounded-full bg-white/20 sm:hidden" />
        <button type="button" data-autofocus onClick={onClose} aria-label="Close preview"
          className="absolute right-3 top-3 z-[5] grid h-9 w-9 place-items-center rounded-full border border-white/15 bg-black/55 text-white backdrop-blur hover:bg-black/75 sm:right-4 sm:top-4">
          <Icon name="xcircle" size={14} tone="inherit" />
        </button>

        <div data-scroll className="min-h-0 flex-1 overflow-y-auto overscroll-contain">
          {!p && !err && (
            <div className="animate-pulse" aria-busy="true" aria-label="Loading mod">
              <div className="h-[150px] bg-white/[0.04] sm:h-[220px]" />
              <div className="flex flex-col gap-3 p-5">
                <div className="flex gap-3"><span className="h-14 w-14 rounded-[14px] bg-white/[0.07]" /><span className="mt-2 h-4 w-1/3 rounded bg-white/[0.08]" /></div>
                <span className="h-3 w-full rounded bg-white/[0.05]" /><span className="h-3 w-4/5 rounded bg-white/[0.05]" /><span className="h-3 w-2/3 rounded bg-white/[0.05]" />
              </div>
              <h2 id={titleId} className="sr-only">Loading mod</h2>
            </div>
          )}
          {err && (
            <div className="flex flex-col items-center gap-3 px-6 py-16 text-center" role="alert">
              <Icon name="warntriangle" size={22} tone="inherit" className="text-amber-300" />
              <h2 id={titleId} className="text-[15px] font-bold text-white">{err}</h2>
              <button type="button" onClick={onClose} className={btnGhost}>Back to the catalogue</button>
            </div>
          )}
          {p && c && (
            <>
              <Gallery p={p} onZoom={setZoom} />
              <div className="flex flex-col gap-4 px-4 pb-5 pt-4 sm:px-6">
                <header className="flex items-start gap-3.5">
                  <ModIcon src={c.icon} size={58} alt="" />
                  <div className="min-w-0 flex-1 pr-8">
                    <h2 id={titleId} className="text-[20px] font-extrabold leading-tight tracking-[-0.02em] text-white sm:text-[22px]">{c.name}</h2>
                    <p className="mt-1 flex flex-wrap items-center gap-x-1.5 text-[12.5px] text-tx-faint">
                      {p.authors.length > 0 && <span>by {p.authors.map((a, i) => <span key={a.name}>{i > 0 && ", "}<span className="font-semibold text-tx-dim">{a.name}</span></span>)}</span>}
                      <span aria-hidden>·</span><span>{SOURCE_LABEL[c.source] ?? c.source}</span>
                      <span aria-hidden>·</span><span>{c.category}</span>
                    </p>
                    <div className="mt-2 flex flex-wrap items-center gap-1.5">
