                  <p className="rounded-[12px] border border-amber-500/35 bg-amber-500/[0.07] px-3.5 py-2.5 text-[12.5px] leading-relaxed text-amber-200">{c.compat.detail}</p>
                )}
                {c.status === "FAILED" && c.error && <p className="rounded-[12px] border border-red-500/35 bg-red-500/[0.08] px-3.5 py-2.5 text-[12.5px] text-red-300">{c.error}</p>}

                <dl className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-6">
                  <Stat label="Downloads">{compactNum(c.downloads) ?? "—"}</Stat>
                  <Stat label="Updated">{ago(c.updatedAt) ?? "—"}</Stat>
                  <Stat label="File size">{fileSize(best?.fileBytes ?? c.fileBytes) ?? "—"}</Stat>
                  <Stat label="Licence">
                    {p.license ? (p.licenseUrl ? <a href={p.licenseUrl} target="_blank" rel="noopener noreferrer nofollow" className="text-cyan-300 hover:text-white">{p.license}</a> : p.license) : "Not published"}
                  </Stat>
                  <Stat label="Latest">{c.latestVersion ?? p.versions[0]?.number ?? "—"}</Stat>
                  <Stat label="Followers">{compactNum(p.followers) ?? "—"}</Stat>
                </dl>

                <div role="tablist" aria-label="Mod details" className="-mx-1 flex gap-1 overflow-x-auto border-b border-white/10 px-1">
