                      onClick={() => setTab(t.k)}
                      onKeyDown={(e) => {
                        const i = tabs.findIndex((x) => x.k === tab);
                        if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
                          e.preventDefault();
                          const n = tabs[(i + (e.key === "ArrowRight" ? 1 : tabs.length - 1)) % tabs.length].k;
                          setTab(n);
                          document.getElementById(`${tabsId}-${n}`)?.focus();
                        }
                      }}
                      className={"relative whitespace-nowrap px-3 py-2.5 text-[12.5px] font-semibold transition " + (tab === t.k ? "text-white after:absolute after:inset-x-2 after:-bottom-px after:h-[2px] after:rounded-full after:bg-[linear-gradient(90deg,#3b6be8,#7b3fef)]" : "text-tx-faint hover:text-white")}>
                      {t.label}{t.n ? <span className="num ml-1 text-tx-faint">{t.n}</span> : null}
                    </button>
                  ))}
                </div>

                <div role="tabpanel" id={`${tabsId}-${tab}-panel`} aria-labelledby={`${tabsId}-${tab}`} className="min-h-[120px]">
                  {tab === "overview" && (
                    <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_240px]">
                      <div className="min-w-0">
                        {p.bodyHtml ? (
                          // Sanitised twice: lib/mod-markdown.ts at ingest, lib/mod-html-harden.ts on read.
                          <div className={PROSE} dangerouslySetInnerHTML={{ __html: p.bodyHtml }} />
                        ) : (
                          <p className="text-[13px] leading-relaxed text-tx-dim">{c.summary ?? "The author hasn't published a description."}</p>
                        )}
                        {p.bodyTruncated && c && <p className="mt-2 text-[12px] text-tx-faint">The rest of the description is on the project page.</p>}
                      </div>
                      <aside className="flex flex-col gap-4 text-[12.5px]">
                        {p.links.length > 0 && (
                          <div>
                            <h3 className="mb-1.5 text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Links</h3>
                            <ul className="flex flex-col gap-1">
                              {p.links.map((l) => (
                                <li key={l.href}><a href={l.href} target="_blank" rel="noopener noreferrer nofollow" className="inline-flex items-center gap-1.5 font-semibold text-cyan-300 hover:text-white">{l.label} <Icon name="external" size={10} tone="inherit" /></a></li>
                              ))}
                            </ul>
                          </div>
                        )}
                        {p.categories.length > 0 && (
                          <div>
                            <h3 className="mb-1.5 text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Categories</h3>
                            <div className="flex flex-wrap gap-1">{p.categories.map((x) => <Chip key={x} cls="border-white/12 bg-white/[0.05] text-tx-dim">{x}</Chip>)}</div>
                          </div>
                        )}
                        {p.loaders.length > 0 && (
                          <div>
                            <h3 className="mb-1.5 text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Loaders</h3>
                            <div className="flex flex-wrap gap-1">{p.loaders.map((x) => <Chip key={x} cls="border-white/12 bg-white/[0.05] text-tx-dim">{x}</Chip>)}</div>
                          </div>
                        )}
                        {p.gameVersions.length > 0 && (
                          <div>
                            <h3 className="mb-1.5 text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Game versions</h3>
                            <p className="text-tx-dim">{p.gameVersions.slice(-8).reverse().join(", ")}{p.gameVersions.length > 8 ? " …" : ""}</p>
                          </div>
                        )}
                        <div className="rounded-[12px] border border-white/[0.08] bg-white/[0.03] p-3">
                          <h3 className="mb-1 flex items-center gap-1.5 text-[12px] font-bold text-white"><Icon name="shieldcheck" size={12} tone="inherit" className="text-cyan-300" />Nxeon Verified</h3>
                          {p.badges.length ? (
                            <ul className="flex flex-col gap-1.5">{p.badges.slice(0, 4).map((b) => <li key={b.gameVersion + b.loader + b.verifiedAt} className="text-[11.5px] leading-snug text-tx-dim">{b.sentence}</li>)}</ul>
                          ) : (
                            <p className="text-[11.5px] leading-snug text-tx-faint">Not verified yet. Verification runs per build and per game version on a test server, so most of the catalogue hasn&apos;t been through it — this isn&apos;t a warning.</p>
                          )}
                          <a href="/mods/verified" target="_blank" rel="noopener" className="mt-1.5 inline-block text-[11.5px] font-semibold text-cyan-300 hover:text-white">What we check →</a>
                        </div>
                      </aside>
                    </div>
                  )}

                  {tab === "versions" && (
                    p.versions.length === 0 ? (
                      <p className="text-[12.5px] text-tx-faint">We don&apos;t hold per-build records for this mod yet — the installer picks the right build from {SOURCE_LABEL[c.source] ?? c.source} at install time.</p>
                    ) : (
                      <ul className="flex flex-col divide-y divide-white/[0.06] rounded-[12px] border border-white/[0.08]">
                        {p.versions.map((v) => {
                          const fit = FIT[v.fit];
                          return (
                            <li key={v.id} className="flex flex-col gap-1.5 px-3 py-2.5 sm:flex-row sm:items-center sm:gap-3">
                              <div className="min-w-0 flex-1">
                                <p className="flex flex-wrap items-center gap-1.5">
                                  <span className="font-mono text-[12.5px] font-semibold text-white">{v.number}</span>
                                  {v.channel !== "release" && <Chip cls="border-amber-500/35 bg-amber-500/10 text-amber-300">{v.channel}</Chip>}
                                  {v.id === p.bestVersionId && <Chip cls="border-cyan-400/40 bg-cyan-400/10 text-cyan-200">Best for you</Chip>}
                                </p>
                                <p className="mt-0.5 truncate text-[11.5px] text-tx-faint">
                                  {[v.loaders.join(", "), v.gameVersions.slice(-5).reverse().join(", ")].filter(Boolean).join(" · ")}
                                </p>
                              </div>
                              <div className="flex flex-wrap items-center gap-2 text-[11.5px] text-tx-faint">
                                {v.publishedAt && <span>{ago(v.publishedAt)}</span>}
                                {fileSize(v.fileBytes) && <span className="num">{fileSize(v.fileBytes)}</span>}
                                {compactNum(v.downloads) && <span className="num">{compactNum(v.downloads)} dl</span>}
                                <Chip cls={fit.cls} title={v.fitDetail}>{fit.label}</Chip>
                              </div>
                            </li>
                          );
                        })}
                      </ul>
                    )
                  )}

                  {tab === "changelog" && (
                    changelogs.length === 0 ? (
                      <p className="text-[12.5px] text-tx-faint">The author hasn&apos;t published changelogs for the builds we hold.</p>
                    ) : (
                      <div className="flex flex-col gap-2">
                        {changelogs.map((v, i) => (
                          <details key={v.id} open={i === 0} className="group rounded-[12px] border border-white/[0.08] bg-white/[0.02] px-3.5 py-2.5">
                            <summary className="flex cursor-pointer list-none items-center gap-2 text-[12.5px] font-semibold text-white">
                              <span className="font-mono">{v.number}</span>
                              {v.publishedAt && <span className="font-normal text-tx-faint">{ago(v.publishedAt)}</span>}
                              <span aria-hidden className="ml-auto text-tx-faint transition group-open:rotate-90">›</span>
                            </summary>
                            <div className={PROSE + " mt-2"} dangerouslySetInnerHTML={{ __html: v.changelogHtml! }} />
                          </details>
                        ))}
                      </div>
