                    ) : (
                      <div className="flex flex-col gap-4">
                        {[["Required", required, "Installed automatically with this mod."], ["Optional", optional, "Adds features if present — install separately if you want them."], ["Incompatible", incompatible, "Can't run alongside this mod."]].map(([label, list, hint]) =>
                          (list as ModPreview["deps"]).length ? (
                            <div key={label as string}>
                              <h3 className="text-[12.5px] font-bold text-white">{label as string}</h3>
                              <p className="mb-2 text-[11.5px] text-tx-faint">{hint as string}</p>
                              <ul className="flex flex-col gap-1.5">
                                {(list as ModPreview["deps"]).map((d) => {
                                  const s = d.status ? STATE[d.status] : null;
                                  return (
                                    <li key={d.kind + d.name} className="flex items-center gap-2.5 rounded-[11px] border border-white/[0.07] bg-white/[0.03] px-2.5 py-2">
                                      <ModIcon src={d.icon} size={30} />
                                      <span className="min-w-0 flex-1 truncate text-[12.5px] font-semibold text-white">{d.name}</span>
                                      {s && <Chip cls={s.cls}>{s.label}</Chip>}
                                      {d.slug ? (
                                        <button type="button" onClick={() => onOpenOther(d.slug!)} className={btnGhost + " py-1"}>View</button>
                                      ) : d.url ? (
                                        <a href={d.url} target="_blank" rel="noopener noreferrer nofollow" className="inline-flex items-center gap-1 text-[11.5px] font-semibold text-cyan-300 hover:text-white">Source <Icon name="external" size={10} tone="inherit" /></a>
                                      ) : null}
                                    </li>
                                  );
                                })}
                              </ul>
                            </div>
                          ) : null,
                        )}
                        {p.depsNote && <p className="text-[11.5px] text-tx-faint">{p.depsNote}</p>}
                      </div>
                    )
                  )}
                </div>
              </div>
            </>
          )}
        </div>
      </div>
      {zoom !== null && p && <Lightbox images={p.gallery} index={zoom} onIndex={setZoom} onClose={() => setZoom(null)} />}
    </div>,
    document.body,
  );
}

