input.content:
/**
 * Nxeon Verified — owner-run CLI. The web app NEVER runs any of this; the
 * admin queue (/admin/nxlabs/verified) only adds ModVerifyTask rows.
 *
 *   npx tsx scripts/mod-verify.ts status
 *   npx tsx scripts/mod-verify.ts queue --family minecraft --game-version 1.21.1 --loader paper [--limit 50] [--mod <slug>]
 *   npx tsx scripts/mod-verify.ts preflight [--limit 20]           # network only: download, hash, archive, licence...
 *   npx tsx scripts/mod-verify.ts smoke --plan                      # list queued smoke tests; changes nothing
 *   npx tsx scripts/mod-verify.ts smoke --confirm --region <r> [--limit 1]
 *        # REAL: orders a throwaway game server per task on a NON-primary node
 *        # (QA account, hostname qa-modverify-*), installs, restarts, reads logs,
 *        # ALWAYS deletes it. One at a time. Touch /tmp/mod-verify.STOP to halt.
 *   npx tsx scripts/mod-verify.ts lapse --family minecraft [--game-version 1.21.1]   # game updated: lapse badges
 *   npx tsx scripts/mod-verify.ts teardown-leftovers                # delete any qa-modverify-* server still alive
 *
 * Smoke-test prerequisites (owner): enough RAM on the chosen region's node,
 * ENABLE_REAL_GAMEMODS=1 on the worker, and a non-sandbox DB/worker. Brand-new
 * VMIDs only — allocation goes through the normal PROVISION job, never reuse.
 */
import { existsSync } from "node:fs";
import { db } from "../lib/db";
import { safeFetch } from "../lib/mods/safe-fetch";
import { runPreflight } from "../lib/mod-verify/preflight";
import { runSmoke, smokeSupported, type SmokeInfra, type SmokeTarget } from "../lib/mod-verify/smoke";
import { claimTask, enqueueVerifyTask, finishTask, lapseForGameUpdate, normKey, recordChecks, blockedHashes } from "../lib/mod-verify/store";

const STOP = "/tmp/mod-verify.STOP";
const QA_EMAIL = "qa-sweep@nxeon-internal.test";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const arg = (k: string) => {
  const i = process.argv.indexOf(`--${k}`);
  return i > 0 ? process.argv[i + 1] : undefined;
};
const flag = (k: string) => process.argv.includes(`--${k}`);
const SAFE = /^[0-9A-Za-z.\-+_]{1,40}$/;

async function status() {
  const [byStatus, tasks, blocked] = await Promise.all([
    db.modVerification.groupBy({ by: ["gameFamily", "status"], _count: { _all: true } }),
    db.modVerifyTask.groupBy({ by: ["kind", "status"], _count: { _all: true } }),
    db.modBlockedHash.count(),
  ]);
  const live = await db.modVerification.count({ where: { status: "VERIFIED", expiresAt: { gt: new Date() } } });
  console.log("verifications:", byStatus.map((r) => `${r.gameFamily}/${r.status}=${r._count._all}`).join("  ") || "none");
  console.log("live badges:", live);
  console.log("tasks:", tasks.map((r) => `${r.kind}/${r.status}=${r._count._all}`).join("  ") || "none");
  console.log("blocked hashes:", blocked);
}

async function queue() {
  const family = arg("family");
  const gameVersion = arg("game-version") ?? "any";
  const loader = (arg("loader") ?? "").toLowerCase();
  const limit = Math.min(500, Number(arg("limit") ?? 25));
  const slug = arg("mod");
  if (!family || !SAFE.test(family) || !SAFE.test(gameVersion) || (loader && !SAFE.test(loader))) throw new Error("--family required; values must be plain tokens");
  const mods = await db.gameMod.findMany({
    where: { gameFamily: family, active: true, upstreamOk: true, ...(slug ? { slug } : {}), ...(loader ? { loaders: { has: loader } } : {}) },
    orderBy: [{ downloads: { sort: "desc", nulls: "last" } }],
    take: limit,
    select: { id: true, slug: true },
  });
  let n = 0;
  for (const m of mods) {
    const r = await enqueueVerifyTask("PREFLIGHT", { ...normKey({ gameModId: m.id, gameVersion, loader }), gameFamily: family }, "cli");
    if (r.created) n++;
  }
  console.log(`queued ${n} preflight task(s) (${mods.length - n} already queued) for ${family} ${gameVersion}${loader ? ` ${loader}` : ""}`);
}

async function preflight() {
  const limit = Math.min(200, Number(arg("limit") ?? 20));
  const blocked = await blockedHashes();
  for (let i = 0; i < limit; i++) {
    if (existsSync(STOP)) return console.log("STOP file present — halting");
    const t = await claimTask("PREFLIGHT");
    if (!t) return console.log(i === 0 ? "no queued preflight tasks" : "queue drained");
    try {
      const r = await runPreflight({ gameModId: t.gameModId, modVersionId: t.modVersionId, gameVersion: t.gameVersion, loader: t.loader, requestedBy: t.requestedBy }, { fetcher: safeFetch, blocked });
      const summary = Object.fromEntries(Object.entries(r.checks).map(([k, v]) => [k, v?.result]));
      await finishTask(t.id, r.status === "FLAGGED" ? "FAILED" : "PASSED", { status: r.status, checks: summary, smokeQueued: r.smokeQueued }, r.error ?? null);
      console.log(`${t.id} ${r.status.padEnd(10)} smokeQueued=${r.smokeQueued} ${JSON.stringify(summary)}`);
    } catch (e) {
      await finishTask(t.id, "ERROR", null, e instanceof Error ? e.message : String(e));
      console.log(`${t.id} ERROR ${(e as Error).message}`);
    }
    await sleep(400); // polite to upstream CDNs
  }
}

// ── real smoke infrastructure (owner-run only) ───────────────────────────────
async function waitJob(id: string, ms: number): Promise<{ status: string; error?: string | null }> {
  const t0 = Date.now();
  while (Date.now() - t0 < ms) {
    const j = await db.job.findUnique({ where: { id }, select: { status: true, error: true } });
    if (!j) return { status: "GONE" };
    if (j.status === "DONE" || j.status === "FAILED") return j;
    await sleep(8000);
  }
  return { status: "TIMEOUT" };
}

async function realInfra(region: string): Promise<SmokeInfra> {
  const { placeGameOrder } = await import("../lib/game-order");
  const { enqueueModOp } = await import("../lib/mods/queue");
  const { withServerSsh } = await import("../lib/ssh-exec");
  const { controlSpec, readGameLogs } = await import("../lib/game-control");
  let user = await db.user.findUnique({ where: { email: QA_EMAIL } });
  if (!user) user = await db.user.create({ data: { email: QA_EMAIL, name: "QA Sweep", passwordHash: "!qa-sweep-no-login" } });
  const qa = user;
  return {
    log: (m) => console.log(m),
    async provision(t) {
      const plan = await db.gamePlan.findFirst({ where: { gameFamily: t.family, active: true }, orderBy: { priceCents: "asc" } });
      if (!plan) return { error: `no active plan for ${t.family}` };
      const rand = Math.random().toString(36).slice(2, 6);
      const hostname = `qa-modverify-${t.family.slice(0, 10)}-${rand}`;
      const config: Record<string, unknown> = t.gameVersion !== "any" ? { VERSION: t.gameVersion } : {};
      const intent = { gamePlanId: plan.id, termMonths: 1, region, hostname, serverName: hostname, variant: t.loader || undefined, config, ...(t.family === "minecraft" ? { subdomain: `qamv${rand}${Math.random().toString(36).slice(2, 6)}` } : {}) };
      try {
        const id = await placeGameOrder(qa, intent, { chargeCents: 0 });
        const pj = await db.job.findFirst({ where: { serverId: id, type: "PROVISION" }, orderBy: { createdAt: "desc" } });
        const r = pj ? await waitJob(pj.id, 40 * 60_000) : { status: "MISSING" };
        if (r.status !== "DONE") return { error: `provision ${r.status}${"error" in r && r.error ? `: ${r.error}` : ""}` };
        return { serverId: id };
      } catch (e) {
        return { error: e instanceof Error ? e.message : String(e) };
      }
    },
    async install(serverId, t) {
      const r = await enqueueModOp(serverId, t.gameModId, "install", { userId: qa.id, slug: t.modSlug });
      if (!r.ok) return { ok: false, error: r.error };
      const j = await waitJob(r.jobId, 20 * 60_000);
      const sm = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: t.gameModId } } });
      return j.status === "DONE" && sm?.status === "INSTALLED" ? { ok: true, detail: `installed ${sm.version ?? ""}`.trim() } : { ok: false, error: sm?.error ?? `install job ${j.status}` };
    },
    async restart(serverId) {
      const job = await db.job.create({ data: { type: "GAME_POWER", serverId, payload: { action: "restart", announce: false } } });
      const r = await waitJob(job.id, 15 * 60_000);
      if (r.status !== "DONE") return { ok: false, error: `restart ${r.status}` };
      await sleep(90_000); // let the game finish loading before reading logs
      return { ok: true };
    },
    async readLog(serverId, family) {
      const spec = controlSpec(family);
      if (!spec) return "";
      const s = await db.server.findUnique({ where: { id: serverId }, include: { node: true, dedicatedIp: true, portForwards: true } });
      if (!s) return "";
      const r = await withServerSsh(s as never, (conn) => readGameLogs(conn, spec, 500));
      return r.ok ? r.lines.join("\n") : "";
    },
    async teardown(serverId) {
      await db.$transaction(async (tx) => {
        const c = await tx.server.updateMany({ where: { id: serverId, userId: qa.id, hostname: { startsWith: "qa-modverify-" }, status: { not: "DELETING" } }, data: { status: "DELETING" } });
        if (c.count !== 1) return;
        await tx.job.create({ data: { type: "DELETE", serverId } });
        await tx.auditLog.create({ data: { userId: qa.id, action: "qa.modverify_teardown", detail: serverId } });
      });
    },
  };
}

async function smoke() {
  const queued = await db.modVerifyTask.findMany({ where: { kind: "SMOKE", status: "QUEUED" }, orderBy: { createdAt: "asc" }, take: 50 });
  if (flag("plan") || !flag("confirm")) {
    console.log(`${queued.length} queued smoke test(s):`);
    for (const t of queued) console.log(`  ${t.id} ${t.gameFamily} ${t.gameVersion} ${t.loader || "-"} mod=${t.gameModId} ${smokeSupported(t.gameFamily) ? "" : "(no load probe yet — will be marked unmet)"}`);
    if (!flag("confirm")) console.log("\nNothing run. Re-run with --confirm --region <region> to provision throwaway servers.");
    return;
  }
  const region = arg("region");
  if (!region || !SAFE.test(region)) throw new Error("--region required");
  const nodes = await db.node.findMany({ where: { region, enabled: true } });
  if (!nodes.length) throw new Error(`no enabled node in region ${region}`);
  if (nodes.some((n) => n.isPrimary)) throw new Error(`region ${region} contains the PRIMARY node — smoke tests never run there`);
  if (process.env.NXEON_SANDBOX === "1") console.log("NOTE: NXEON_SANDBOX=1 — provisioning is stubbed, so smoke results will not be real.");
  const infra = await realInfra(region);
  const limit = Math.min(10, Number(arg("limit") ?? 1));
  for (let i = 0; i < limit; i++) {
    if (existsSync(STOP)) return console.log("STOP file present — halting");
    const t = await claimTask("SMOKE");
    if (!t) return console.log("no queued smoke tests");
    const mod = await db.gameMod.findUnique({ where: { id: t.gameModId } });
    if (!mod) {
      await finishTask(t.id, "ERROR", null, "mod gone");
      continue;
    }
    const target: SmokeTarget = { taskId: t.id, gameModId: mod.id, modName: mod.name, modSlug: mod.slug, sourceId: mod.sourceId, family: t.gameFamily, gameVersion: t.gameVersion, loader: t.loader };
    const rep = await runSmoke(target, infra);
    const key = normKey({ gameModId: t.gameModId, modVersionId: t.modVersionId, gameVersion: t.gameVersion, loader: t.loader });
    const r = await recordChecks(key, { gameFamily: t.gameFamily, by: "system" }, { smoke: rep.outcome });
    await finishTask(t.id, rep.outcome.result === "pass" ? "PASSED" : "FAILED", { ...rep, status: r.status }, rep.outcome.result === "pass" ? null : rep.detail, rep.serverId);
    console.log(`${t.id} ${mod.slug} smoke=${rep.outcome.result} status=${r.status} tornDown=${rep.tornDown} — ${rep.detail}`);
  }
}

async function lapse() {
  const family = arg("family");
  if (!family || !SAFE.test(family)) throw new Error("--family required");
  const v = arg("game-version");
  console.log(`lapsed ${await lapseForGameUpdate(family, v && SAFE.test(v) ? v : undefined)} badge(s)`);
}

async function teardownLeftovers() {
  const qa = await db.user.findUnique({ where: { email: QA_EMAIL } });
  if (!qa) return console.log("no QA user");
  const left = await db.server.findMany({ where: { userId: qa.id, hostname: { startsWith: "qa-modverify-" }, status: { notIn: ["DELETING", "DELETED"] } }, select: { id: true, hostname: true } });
  const infra = await realInfra("unused");
  for (const s of left) {
    await infra.teardown(s.id);
    console.log("delete queued:", s.hostname);
  }
  if (!left.length) console.log("nothing left over");
}

const cmd = process.argv[2];
const run = { status, queue, preflight, smoke, lapse, "teardown-leftovers": teardownLeftovers }[cmd ?? ""];
if (!run) {
  console.log("usage: status | queue | preflight | smoke [--plan|--confirm --region r] | lapse | teardown-leftovers");
  process.exit(2);
}
run().then(() => process.exit(0)).catch((e) => { console.error("FATAL", e instanceof Error ? e.message : e); process.exit(1); });

