    const r = await recordChecks(normKey(t), { gameFamily: t.gameFamily }, { smoke: rep.outcome });
    await db.modVerifyTask.update({ where: { id: t.id }, data: { status: rep.outcome.result === "pass" ? "PASSED" : "FAILED", finishedAt: new Date(), result: { fixture: true, status: r.status } } });
    console.log("smoke fixture", mod.slug, rep.outcome.result, r.status);
  }
  // A flagged + a revoked example for the admin queue.
  const others = await db.modVerification.findMany({ where: { status: "UNVERIFIED" }, take: 2 });
  if (others[0]) await flagVerification(others[0].id, "Fixture: crash on start reported by a customer", admin.id);
  if (others[1]) await revokeVerification(others[1].id, "Fixture: upstream pulled this build", admin.id);
