  const tok = async (id: string) => new SignJWT({ sub: id, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(secret);
  writeFileSync("/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/modui/session.json", JSON.stringify({ customer: await tok(cust.id), admin: await tok(admin.id), mc: mc.id, mcf: mcf.id, vh: vh.id, cookie: process.env.NXEON_COOKIE_NAME ?? "nxeon_session" }, null, 1));
  console.log({ mc: mc.id, mcf: mcf.id, vh: vh.id });
}
main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
