"use server";

/**
 * Admin queue for Nxeon Verified (/admin/nxlabs/verified). ADMIN-only
 * ("platform" area). Every action is audited and idempotent. Nothing here
 * downloads files or touches a server: queueing writes ModVerifyTask rows the
 * owner's runner (scripts/mod-verify.ts) processes; revoke/flag only change
 * ModVerification rows, which takes the badge down on the next render.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";
import { enqueueVerifyTask, flagVerification, HASH_RE, normKey, resetVerification, revokeVerification } from "./mod-verify/store";

type Result = { ok?: true; error?: string; count?: number };
const SAFE = /^[0-9A-Za-z.\-+_]{1,40}$/;
const ids = (x: unknown, max = 200): string[] =>
  Array.isArray(x) ? [...new Set(x.filter((v): v is string => typeof v === "string" && /^[a-z0-9]{10,40}$/i.test(v)))].slice(0, max) : [];
const reasonOf = (r: unknown) => (typeof r === "string" ? r.trim().slice(0, 500) : "");
const PATH = "/admin/nxlabs/verified";

export async function adminQueueVerification(input: { modIds?: string[]; slugs?: string; family: string; gameVersion: string; loader: string }): Promise<Result> {
  const admin = await requireArea("platform");
  const family = String(input.family ?? "");
  const gv = String(input.gameVersion ?? "").trim() || "any";
  const loader = String(input.loader ?? "").trim().toLowerCase();
  if (!SAFE.test(family) || !SAFE.test(gv) || (loader && !SAFE.test(loader))) return { error: "Family, version and loader must be plain values." };
  const slugs = String(input.slugs ?? "").split(/[\s,]+/).map((s) => s.trim()).filter((s) => /^[A-Za-z0-9._\-]{1,120}$/.test(s)).slice(0, 200);
  const byId = ids(input.modIds);
  const mods = await db.gameMod.findMany({ where: { gameFamily: family, OR: [{ id: { in: byId } }, { slug: { in: slugs } }] }, select: { id: true } });
  if (!mods.length) return { error: "No matching mods for that game." };
  let n = 0;
  for (const m of mods) {
    const r = await enqueueVerifyTask("PREFLIGHT", { ...normKey({ gameModId: m.id, gameVersion: gv, loader }), gameFamily: family }, admin.id);
    if (r.created) n++;
  }
  await recordAudit(admin.id, "modverify.queue", `${family} ${gv} ${loader || "-"}: ${n} queued (${mods.length} requested)`);
  revalidatePath(PATH);
  return { ok: true, count: n };
}

export async function adminRevokeVerifications(verificationIds: string[], reason: string): Promise<Result> {
  const admin = await requireArea("platform");
  const list = ids(verificationIds);
  const why = reasonOf(reason);
  if (!list.length) return { error: "Nothing selected." };
  if (why.length < 4) return { error: "Give a reason (it's shown in the audit log and on the row)." };
  for (const id of list) await revokeVerification(id, why, admin.id).catch(() => null);
  await recordAudit(admin.id, "modverify.revoke", `${list.length} row(s): ${why}`);
  revalidatePath(PATH);
  return { ok: true, count: list.length };
}

export async function adminFlagVerifications(verificationIds: string[], reason: string): Promise<Result> {
  const admin = await requireArea("platform");
  const list = ids(verificationIds);
  const why = reasonOf(reason);
  if (!list.length) return { error: "Nothing selected." };
  if (why.length < 4) return { error: "Give a reason." };
  for (const id of list) await flagVerification(id, why, admin.id);
  await recordAudit(admin.id, "modverify.flag", `${list.length} row(s): ${why}`);
  revalidatePath(PATH);
  return { ok: true, count: list.length };
}

/** Clear a flag/revocation. The row returns to UNVERIFIED and must pass a NEW smoke test. */
export async function adminResetVerifications(verificationIds: string[]): Promise<Result> {
  const admin = await requireArea("platform");
  const list = ids(verificationIds);
  if (!list.length) return { error: "Nothing selected." };
  for (const id of list) await resetVerification(id, admin.id);
  await recordAudit(admin.id, "modverify.reset", `${list.length} row(s)`);
  revalidatePath(PATH);
  return { ok: true, count: list.length };
}

export async function adminCancelVerifyTasks(taskIds: string[]): Promise<Result> {
  const admin = await requireArea("platform");
  const list = ids(taskIds);
  if (!list.length) return { error: "Nothing selected." };
  const r = await db.modVerifyTask.updateMany({ where: { id: { in: list }, status: "QUEUED" }, data: { status: "CANCELLED", finishedAt: new Date() } });
  await recordAudit(admin.id, "modverify.cancel", `${r.count} task(s)`);
  revalidatePath(PATH);
  return { ok: true, count: r.count };
}

/**
 * Add a known-bad hash. Any verification of a build carrying that hash is
 * revoked at once (matched against ModVersion's published sha1/sha256/sha512).
 */
export async function adminBlockHash(hash: string, reason: string): Promise<Result> {
  const admin = await requireArea("platform");
  const h = String(hash ?? "").trim().toLowerCase();
  const why = reasonOf(reason);
  if (!HASH_RE.test(h)) return { error: "That isn't a SHA-1, SHA-256 or SHA-512 hex digest." };
  if (why.length < 4) return { error: "Give a reason." };
  await db.modBlockedHash.upsert({ where: { hash: h }, update: { reason: why }, create: { hash: h, reason: why, addedBy: admin.id } });
  const versions = await db.modVersion.findMany({ where: { OR: [{ sha1: h }, { sha256: h }, { sha512: h }, { mirrorSha256: h }] }, select: { id: true } });
  let revoked = 0;
  if (versions.length) {
    const rows = await db.modVerification.findMany({ where: { modVersionId: { in: versions.map((v) => v.id) }, status: { not: "REVOKED" } }, select: { id: true } });
    for (const r of rows) await revokeVerification(r.id, `Known-bad file: ${why}`, admin.id);
    revoked = rows.length;
  }
  await recordAudit(admin.id, "modverify.block_hash", `${h.slice(0, 16)}… (${why}); revoked ${revoked}`);
  revalidatePath(PATH);
  return { ok: true, count: revoked };
}

