"use client";

import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { ReactNode } from "react";

export type BulkColumn = { header: ReactNode; className?: string };
export type BulkRow = { id: string; cells: ReactNode[]; selectable?: boolean };
export type BulkAction = {
  label: string;
  /** Server action invoked with the selected row ids. */
  run: (ids: string[]) => Promise<unknown>;
  /** Confirmation prompt shown before running (skip when omitted). */
  confirm?: string;
  danger?: boolean;
};

/**
 * A self-contained, selectable admin table. The parent (a Server Component)
 * maps its data into `columns` + `rows` (cells may be arbitrary React nodes such
 * as <Link>s) and passes an `exportHref` and optional bulk `actions`. Selection
 * state, the select-all header checkbox and the floating action bar all live
 * here on the client; the export link points at the CSV route.
 */
export function BulkTable({
  columns,
  rows,
  exportHref,
  actions = [],
  minWidth = 720,
  empty = "Nothing to show.",
}: {
  columns: BulkColumn[];
  rows: BulkRow[];
  exportHref?: string;
  actions?: BulkAction[];
  minWidth?: number;
  empty?: string;
}) {
  const router = useRouter();
4:export function PageHeader({
24:export function StatCard({
101:export function StatusDot({ status, label }: { status: string; label?: string }) {
111:export function Badge({
132:export function EmptyState({
158:export function ComingSoon({ feature, note }: { feature: string; note?: string }) {
170:export function fmtBytes(b: number): string {
177:export function fmtMoney(cents: number): string {
181:export function timeAgo(d: Date): string {
                  <div className="flex flex-wrap items-center gap-2 font-medium">
                    {p.label}
                    <Badge tone={statusTone(r?.lastStatus)}>{r?.lastStatus ?? "never run"}</Badge>
                    {r?.paused && <Badge tone="amber">paused</Badge>}
                    {r && !r.enabled && <Badge tone="red">disabled</Badge>}
                    <Badge tone="brand">{p.policy === "mirror-if-licensed" ? "mirror if licensed" : "metadata only"}</Badge>
                  </div>
                  <div className="mt-1 text-xs text-slate-500">
                    games: {p.games.join(", ")} · {srcCount.get(p.key === "factorio" ? "factorio_portal" : p.key)?.n.toString() ?? "0"} rows ·
                    last run {r?.lastRunAt ? timeAgo(r.lastRunAt) : "never"} · next {r?.nextRunAt ? inFuture(r.nextRunAt) : "—"} ·
                    mode {String(s.mode ?? "—")} · seen {String(s.seen ?? 0)} / new {String(s.created ?? 0)} / upd {String(s.updated ?? 0)} / failed {String(s.failed ?? 0)} ·
                    mirrored {String(s.mirrored ?? 0)} · {String(s.requests ?? 0)} req ({String(s.retries ?? 0)} retried)
                    {r?.cursor ? " · resumable cursor saved" : ""}
                  </div>
                  {r?.lastError && <div className="mt-1 break-words text-xs text-red-400">{r.lastError}</div>}
                </div>
                {r && <NxLabsSyncControls providerKey={p.key} paused={r.paused} enabled={r.enabled} />}
              </div>
            </div>
          );
        })}
      </div>

