                  <td className="py-1">{l.label}</td>
                  <td>{c ? Number(c.n).toLocaleString() : 0}</td>
                  <td>{c?.last ? timeAgo(c.last) : "never"}</td>
                  <td className="text-slate-400">{l.verdict}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <h2 className="mb-2 text-lg font-semibold">Coverage by game</h2>
      <div className="card mb-8 overflow-x-auto">
