"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { BulkTable, type BulkColumn, type BulkRow } from "@/components/admin/BulkTable";
import {
  adminBlockHash,
  adminCancelVerifyTasks,
  adminFlagVerifications,
  adminQueueVerification,
  adminResetVerifications,
  adminRevokeVerifications,
} from "@/lib/actions-admin-mod-verify";

const unwrap = (r: { error?: string }) => {
  if (r.error) throw new Error(r.error);
};
const askReason = (what: string) => {
  const r = window.prompt(`${what} — reason (shown in the audit log and on the row):`);
  if (!r || r.trim().length < 4) throw new Error("Cancelled — a reason of at least 4 characters is required.");
  return r.trim();
};

/** Verification rows with bulk Revoke / Flag / Reset. */
export function VerificationTable({ columns, rows }: { columns: BulkColumn[]; rows: BulkRow[] }) {
  return (
    <BulkTable
      columns={columns}
      rows={rows}
      minWidth={980}
      empty="No verifications match these filters."
      actions={[
        { label: "Revoke", danger: true, run: async (ids) => unwrap(await adminRevokeVerifications(ids, askReason(`Revoke ${ids.length} verification(s)`))) },
        { label: "Flag for review", run: async (ids) => unwrap(await adminFlagVerifications(ids, askReason(`Flag ${ids.length} verification(s)`))) },
        { label: "Reset (re-test)", confirm: "Reset the selected rows to UNVERIFIED? They must pass a NEW install test to get the badge back.", run: async (ids) => unwrap(await adminResetVerifications(ids)) },
      ]}
    />
  );
}

export function TaskTable({ columns, rows }: { columns: BulkColumn[]; rows: BulkRow[] }) {
  return (
    <BulkTable
      columns={columns}
      rows={rows}
      minWidth={860}
      empty="The queue is empty."
      actions={[{ label: "Cancel", confirm: "Cancel the selected queued tasks?", run: async (ids) => unwrap(await adminCancelVerifyTasks(ids)) }]}
    />
  );
}

export function QueueForm({ families }: { families: string[] }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <form
      className="card grid gap-3 sm:grid-cols-[1fr_1fr_1fr_2fr_auto] sm:items-end"
      onSubmit={(e) => {
        e.preventDefault();
        const f = new FormData(e.currentTarget);
        start(async () => {
          const r = await adminQueueVerification({ family: String(f.get("family")), gameVersion: String(f.get("gameVersion")), loader: String(f.get("loader")), slugs: String(f.get("slugs")) });
          setMsg(r.error ?? `Queued ${r.count} preflight task(s). The owner's runner picks them up: npx tsx scripts/mod-verify.ts preflight`);
          router.refresh();
        });
      }}
    >
      <label className="text-xs text-slate-400">Game
        <select name="family" className="input mt-1">{families.map((f) => <option key={f}>{f}</option>)}</select>
      </label>
      <label className="text-xs text-slate-400">Game version
        <input name="gameVersion" className="input mt-1" placeholder="1.21.1 or any" defaultValue="1.21.1" />
      </label>
      <label className="text-xs text-slate-400">Loader
        <input name="loader" className="input mt-1" placeholder="paper / fabric / (blank)" />
      </label>
      <label className="text-xs text-slate-400">Mod slugs (comma or space separated)
        <input name="slugs" className="input mt-1" placeholder="luckperms, worldedit" required />
      </label>
      <button className="btn-primary" disabled={pending}>{pending ? "Queueing…" : "Queue checks"}</button>
      {msg && <p className="text-xs text-slate-400 sm:col-span-5">{msg}</p>}
    </form>
  );
}

export function BlockHashForm() {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <form
      className="card grid gap-3 sm:grid-cols-[2fr_2fr_auto] sm:items-end"
      onSubmit={(e) => {
        e.preventDefault();
        const f = new FormData(e.currentTarget);
        if (!window.confirm("Add this hash to the known-bad list? Any verification of a build with this hash is revoked immediately.")) return;
        start(async () => {
          const r = await adminBlockHash(String(f.get("hash")), String(f.get("reason")));
          setMsg(r.error ?? `Blocked. ${r.count} verification(s) revoked.`);
          router.refresh();
        });
      }}
    >
      <label className="text-xs text-slate-400">SHA-1 / SHA-256 / SHA-512
        <input name="hash" className="input mt-1 font-mono" required pattern="[a-fA-F0-9]{40}|[a-fA-F0-9]{64}|[a-fA-F0-9]{128}" />
      </label>
      <label className="text-xs text-slate-400">Reason
        <input name="reason" className="input mt-1" required minLength={4} maxLength={500} />
      </label>
      <button className="btn-danger" disabled={pending}>Block hash</button>
      {msg && <p className="text-xs text-slate-400 sm:col-span-3">{msg}</p>}
    </form>
  );
}

