import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, StatCard, timeAgo } from "@/components/ui/primitives";
import { VerificationTable, TaskTable, QueueForm, BlockHashForm } from "@/components/admin/ModVerifyControls";
import { checkList, isBadgeLive, VERIFY_STATUSES, VERIFY_TTL_DAYS } from "@/lib/mod-verify/status";

export const dynamic = "force-dynamic";

const PER = 50;
const tone = (s: string, live: boolean): "green" | "red" | "amber" | "slate" | "brand" =>
  s === "VERIFIED" ? (live ? "green" : "amber") : s === "FLAGGED" ? "amber" : s === "REVOKED" ? "red" : "slate";
const RES: Record<string, string> = { pass: "text-emerald-400", warn: "text-amber-300", unmet: "text-slate-500", fail: "text-red-400", pending: "text-slate-500", skipped: "text-slate-600" };

/** Nxeon Verified queue: verdicts per (build, game version, loader), the task queue, and the known-bad hash list. */
export default async function AdminModVerifiedPage({ searchParams }: { searchParams: Promise<Record<string, string | undefined>> }) {
  await requireArea("platform");
  const sp = await searchParams;
  const status = VERIFY_STATUSES.includes(sp.status as never) ? sp.status! : sp.status === "EXPIRED" ? "EXPIRED" : undefined;
  const family = sp.family && /^[a-z0-9\-]{1,40}$/.test(sp.family) ? sp.family : undefined;
  const page = Math.max(1, Math.min(200, Number(sp.page) || 1));
  const now = new Date();
  const soon = new Date(now.getTime() + 7 * 86_400_000);

  const where =
    status === "EXPIRED"
      ? { status: "VERIFIED", OR: [{ expiresAt: { lte: now } }, { expiresAt: null }], ...(family ? { gameFamily: family } : {}) }
      : { ...(status ? { status } : {}), ...(family ? { gameFamily: family } : {}) };

  const [counts, live, expiring, rows, total, tasks, taskCounts, blocked, families] = await Promise.all([
    db.modVerification.groupBy({ by: ["status"], _count: { _all: true } }),
    db.modVerification.count({ where: { status: "VERIFIED", expiresAt: { gt: now } } }),
    db.modVerification.count({ where: { status: "VERIFIED", expiresAt: { gt: now, lte: soon } } }),
    db.modVerification.findMany({ where, orderBy: { updatedAt: "desc" }, skip: (page - 1) * PER, take: PER }),
    db.modVerification.count({ where }),
    db.modVerifyTask.findMany({ where: { status: { in: ["QUEUED", "RUNNING"] } }, orderBy: { createdAt: "asc" }, take: 100 }),
    db.modVerifyTask.groupBy({ by: ["kind", "status"], _count: { _all: true } }),
    db.modBlockedHash.findMany({ orderBy: { createdAt: "desc" }, take: 20 }),
    db.gameMod.groupBy({ by: ["gameFamily"], where: { active: true }, _count: true, orderBy: { _count: { gameFamily: "desc" } } }),
  ]);
  const modIds = [...new Set([...rows.map((r) => r.gameModId), ...tasks.map((t) => t.gameModId)])];
  const mods = new Map((await db.gameMod.findMany({ where: { id: { in: modIds } }, select: { id: true, name: true, slug: true, gameFamily: true } })).map((m) => [m.id, m]));
  const c = new Map(counts.map((x) => [x.status, x._count._all]));
  const tc = (k: string, s: string) => taskCounts.find((x) => x.kind === k && x.status === s)?._count._all ?? 0;
  const q = (o: Record<string, string | undefined>) => {
    const u = new URLSearchParams();
    for (const [k, v] of Object.entries({ status, family, ...o })) if (v) u.set(k, v);
    const s = u.toString();
    return s ? `?${s}` : "";
  };

  return (
    <div>
      <PageHeader title="Nxeon Verified" sub={`Per build, per game version. VERIFIED needs every automated check AND an install smoke test; it expires after ${VERIFY_TTL_DAYS} days. Revoking takes the badge down on the next page load.`}>
        <Link href="/admin/nxlabs" className="btn-secondary py-1.5">← NX Labs ingestion</Link>
      </PageHeader>

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-6">
        <StatCard label="Live badges" value={live.toLocaleString()} />
        <StatCard label="Expiring in 7 days" value={expiring.toLocaleString()} />
        <StatCard label="Unverified" value={(c.get("UNVERIFIED") ?? 0).toLocaleString()} />
        <StatCard label="Flagged" value={(c.get("FLAGGED") ?? 0).toLocaleString()} />
        <StatCard label="Revoked" value={(c.get("REVOKED") ?? 0).toLocaleString()} />
        <StatCard label="Queued (preflight / smoke)" value={`${tc("PREFLIGHT", "QUEUED")} / ${tc("SMOKE", "QUEUED")}`} />
      </div>

      <div className="card mb-6 text-sm text-slate-400">
        <p className="font-medium text-slate-200">How the queue runs</p>
        <p className="mt-1">The web app never downloads files or creates servers. The owner runs <code className="text-brand-300">npx tsx scripts/mod-verify.ts preflight</code> (network only: download, checksum, archive, licence) and, when ready, <code className="text-brand-300">npx tsx scripts/mod-verify.ts smoke --confirm --region &lt;non-primary region&gt;</code>, which installs each build on a throwaway server, starts the game, reads its log, and always deletes the server. <code className="text-brand-300">smoke --plan</code> lists what would run.</p>
      </div>

      <h2 className="mb-2 text-lg font-semibold">Queue checks</h2>
      <div className="mb-8"><QueueForm families={families.map((f) => f.gameFamily)} /></div>

      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <h2 className="text-lg font-semibold">Verifications <span className="text-sm font-normal text-slate-500">({total.toLocaleString()})</span></h2>
        <div className="flex flex-wrap gap-1.5 text-xs">
          {[undefined, ...VERIFY_STATUSES, "EXPIRED"].map((s) => (
            <Link key={s ?? "all"} href={`/admin/nxlabs/verified${q({ status: s, page: undefined })}`} className={`rounded-full border px-2.5 py-1 ${status === s ? "border-brand-400 text-white" : "border-white/10 text-slate-400 hover:text-white"}`}>{s ?? "All"}</Link>
          ))}
          <form className="flex gap-1" action="/admin/nxlabs/verified">
            {status && <input type="hidden" name="status" value={status} />}
            <select name="family" defaultValue={family ?? ""} className="input py-1 text-xs">
              <option value="">All games</option>
              {families.map((f) => <option key={f.gameFamily} value={f.gameFamily}>{f.gameFamily}</option>)}
            </select>
            <button className="btn-secondary py-1 text-xs">Filter</button>
          </form>
        </div>
      </div>
      <div className="card mb-3 p-0">
        <VerificationTable
          columns={[{ header: "Mod" }, { header: "Target" }, { header: "Status" }, { header: "Checks" }, { header: "Verified / expires" }, { header: "Notes" }]}
          rows={rows.map((r) => {
            const m = mods.get(r.gameModId);
            const isLive = isBadgeLive(r);
            return {
              id: r.id,
              cells: [
                <div key="m" className="min-w-0">
                  <div className="font-medium text-slate-200">{m?.name ?? "(mod removed)"}</div>
                  <div className="text-xs text-slate-500">{r.gameFamily}/{m?.slug ?? r.gameModId}{r.versionNumber ? ` · ${r.versionNumber}` : ""}</div>
                </div>,
                <span key="t" className="text-xs">{r.gameVersion}{r.loader ? ` · ${r.loader}` : ""}</span>,
                <Badge key="s" tone={tone(r.status, isLive)}>{r.status === "VERIFIED" && !isLive ? "EXPIRED" : r.status}</Badge>,
                <div key="c" className="flex flex-wrap gap-x-2 gap-y-0.5 text-[11px]">
                  {checkList(r.checks).map((x) => <span key={x.key} title={x.detail} className={RES[x.result] ?? "text-slate-500"}>{x.key}:{x.result}</span>)}
                </div>,
                <span key="d" className="text-xs text-slate-400">{r.verifiedAt ? `${timeAgo(r.verifiedAt)}` : "—"}{r.expiresAt ? ` / ${r.expiresAt.toISOString().slice(0, 10)}` : ""}</span>,
                <span key="n" className="text-xs text-slate-500">{r.revokedReason ?? r.notes ?? ""}</span>,
              ],
            };
          })}
        />
      </div>
      <div className="mb-8 flex items-center gap-2 text-sm text-slate-400">
        {page > 1 && <Link className="btn-secondary py-1" href={`/admin/nxlabs/verified${q({ page: String(page - 1) })}`}>← Prev</Link>}
        <span>Page {page} of {Math.max(1, Math.ceil(total / PER))}</span>
        {page * PER < total && <Link className="btn-secondary py-1" href={`/admin/nxlabs/verified${q({ page: String(page + 1) })}`}>Next →</Link>}
      </div>

      <h2 className="mb-2 text-lg font-semibold">Task queue <span className="text-sm font-normal text-slate-500">(queued + running)</span></h2>
      <div className="card mb-8 p-0">
        <TaskTable
          columns={[{ header: "Kind" }, { header: "Mod" }, { header: "Target" }, { header: "Status" }, { header: "Queued" }, { header: "Attempts" }]}
          rows={tasks.map((t) => {
            const m = mods.get(t.gameModId);
            return {
              id: t.id,
              selectable: t.status === "QUEUED",
              cells: [
                <Badge key="k" tone={t.kind === "SMOKE" ? "brand" : "slate"}>{t.kind}</Badge>,
                <span key="m">{m?.name ?? t.gameModId}</span>,
                <span key="t" className="text-xs">{t.gameFamily} {t.gameVersion}{t.loader ? ` · ${t.loader}` : ""}</span>,
                <Badge key="s" tone={t.status === "RUNNING" ? "amber" : "slate"}>{t.status}</Badge>,
                <span key="q" className="text-xs text-slate-400">{timeAgo(t.createdAt)}</span>,
                <span key="a" className="text-xs">{t.attempts}</span>,
              ],
            };
          })}
        />
      </div>

      <h2 className="mb-2 text-lg font-semibold">Known-bad hashes</h2>
      <div className="mb-3"><BlockHashForm /></div>
      <div className="card overflow-x-auto">
        {blocked.length === 0 ? (
          <p className="text-sm text-slate-500">None.</p>
        ) : (
          <table className="w-full text-left text-sm">
            <thead className="text-xs text-slate-500"><tr><th className="py-1">Hash</th><th>Reason</th><th>Added</th></tr></thead>
            <tbody>
              {blocked.map((b) => (
                <tr key={b.id} className="border-t border-white/5">
                  <td className="py-1 font-mono text-xs">{b.hash.slice(0, 24)}…</td>
                  <td className="text-slate-400">{b.reason}</td>
                  <td className="text-xs text-slate-500">{timeAgo(b.createdAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

