import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
import fs from "node:fs";
const S = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/modui";
const OUT = `${S}/shots`;
fs.mkdirSync(OUT, { recursive: true });
const seed = JSON.parse(fs.readFileSync(`${S}/session.json`, "utf8"));
const base = "http://localhost:3047";
const only = process.argv[2];
const errors = [];
const log = (o) => console.log(JSON.stringify(o));

const browser = await chromium.launch({ args: ["--host-resolver-rules=MAP admin.modui.test 127.0.0.1"] });

async function ctxFor(vp, token = seed.customer, domain = "localhost") {
  const ctx = await browser.newContext({ viewport: vp, deviceScaleFactor: 1 });
  await ctx.addCookies([{ name: seed.cookie, value: token, domain, path: "/" }]);
  const page = await ctx.newPage();
  page.on("pageerror", (e) => errors.push(`pageerror: ${e.message.slice(0, 200)}`));
  page.on("console", (m) => { if (m.type() === "error") errors.push(`console: ${m.text().slice(0, 220)}`); });
  return { ctx, page };
}
const overflow = (page) => page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
const cards = (page) => page.locator("article").filter({ has: page.locator("h3 button") });

async function gotoMods(page, server, extra = "") {
  await page.goto(`${base}/dashboard/servers/${server}?tab=mods${extra}`, { waitUntil: "domcontentloaded", timeout: 240_000 });
  await page.waitForSelector("section[aria-label^='Browse']", { timeout: 120_000 });
  await page.waitForFunction(() => document.querySelectorAll("section[aria-label^='Browse'] article").length > 0 || document.querySelector("section[aria-label^='Browse'] [role=alert]") || /\b0 (mods|plugins)\b/.test(document.body.innerText), null, { timeout: 120_000 });
  await page.waitForTimeout(600);
}
async function shotSection(page, name) {
  const sec = page.locator("section[aria-label^='Browse']");
  await sec.screenshot({ path: `${OUT}/${name}.png` });
}

if (!only || only === "desktop") {
  const { ctx, page } = await ctxFor({ width: 1440, height: 1000 });
  await gotoMods(page, seed.mc);
  log({ step: "desktop grid", cards: await cards(page).count(), overflow: await overflow(page) });
  await page.screenshot({ path: `${OUT}/01-desktop-tab.png`, fullPage: false });
  await shotSection(page, "02-desktop-grid");

  // verified only
  await page.getByRole("switch", { name: /Nxeon Verified only/ }).click();
  await page.waitForTimeout(1500);
  log({ step: "verified-only", cards: await cards(page).count() });
  await shotSection(page, "03-desktop-verified-only");
  // badge popover
  const badge = page.getByRole("button", { name: /Nxeon Verified for/ }).first();
  if (await badge.count()) {
    await badge.click();
    await page.waitForTimeout(300);
    await page.screenshot({ path: `${OUT}/04-badge-popover.png`, clip: await (async () => { const b = await page.locator("[role=dialog][aria-label='What Nxeon Verified means']").boundingBox(); const c = await badge.boundingBox(); const x = Math.max(0, Math.min(b.x, c.x) - 24), y = Math.max(0, c.y - 200); return { x, y, width: Math.min(760, 1440 - x), height: Math.min(1000 - y, b.y + b.height - y + 40) }; })() });
    await page.keyboard.press("Escape");
    log({ step: "popover closes on Esc", open: await page.locator("[aria-label='What Nxeon Verified means']").count() });
  }
  await page.getByRole("switch", { name: /Nxeon Verified only/ }).click();
  await page.waitForTimeout(1200);

  // empty state
  await page.getByRole("searchbox").fill("zzqxqzz nothing matches");
  await page.waitForTimeout(1800);
  await shotSection(page, "05-empty-state");
  await page.getByRole("searchbox").fill("");
  await page.waitForTimeout(1500);

  // modal via deep link
  await page.goto(`${base}/dashboard/servers/${seed.mc}?tab=mods&mod=veinminer-enchantment`, { waitUntil: "domcontentloaded", timeout: 240_000 });
  await page.waitForSelector("[role=dialog][aria-modal=true] h2", { timeout: 120_000 });
  await page.waitForFunction(() => !document.querySelector("[aria-label='Loading mod']"), null, { timeout: 60_000 });
  await page.waitForTimeout(1500);
  const focusedInDialog = await page.evaluate(() => !!document.activeElement?.closest("[role=dialog]"));
  log({ step: "modal deep link", title: await page.locator("[role=dialog] h2").first().innerText(), focusedInDialog, url: page.url() });
  await page.screenshot({ path: `${OUT}/06-modal-desktop.png` });
  const scroller = page.locator("[data-scroll]");
  await scroller.evaluate((el) => el.scrollTo({ top: 520 }));
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${OUT}/07-modal-desktop-overview.png` });
  for (const [tab, n] of [["Versions", "08"], ["Changelog", "09"], ["Dependencies", "10"]]) {
    await page.getByRole("tab", { name: new RegExp(`^${tab}`) }).click();
    await page.waitForTimeout(500);
    await page.screenshot({ path: `${OUT}/${n}-modal-${tab.toLowerCase()}.png` });
  }
  // focus trap: tab many times, focus must remain inside
  for (let i = 0; i < 40; i++) await page.keyboard.press("Tab");
  log({ step: "focus trap", inside: await page.evaluate(() => !!document.activeElement?.closest("[role=dialog]")) });
  // lightbox
  await page.getByRole("tab", { name: /^Overview/ }).click();
  await scroller.evaluate((el) => el.scrollTo({ top: 0 }));
  const zoom = page.getByRole("button", { name: /full size/ });
  if (await zoom.count()) {
    await zoom.click();
    await page.waitForTimeout(800);
    await page.screenshot({ path: `${OUT}/11-lightbox.png` });
    await page.keyboard.press("ArrowRight");
    await page.waitForTimeout(400);
    await page.keyboard.press("Escape");
    await page.waitForTimeout(200);
    log({ step: "lightbox esc", lightbox: await page.locator("[aria-label^='Screenshot ']").count(), modal: await page.locator("[role=dialog][aria-modal=true]").count() });
  }
  await page.keyboard.press("Escape");
  await page.waitForTimeout(300);
  log({ step: "modal esc closes", modal: await page.locator("[role=dialog][aria-modal=true]").count(), url: page.url() });

  // loading skeleton: delay server actions
  await page.route("**/dashboard/servers/**", async (route) => {
    if (route.request().method() === "POST") await new Promise((r) => setTimeout(r, 2500));
    await route.continue();
  });
  await page.getByRole("searchbox").fill("map");
  await page.waitForTimeout(900);
  await shotSection(page, "12-loading-skeleton");
  await page.unroute("**/dashboard/servers/**");
  await page.waitForTimeout(3000);
  // error state: abort action POSTs
  await page.route("**/dashboard/servers/**", (route) => (route.request().method() === "POST" ? route.abort() : route.continue()));
  await page.getByRole("searchbox").fill("mapx");
  await page.waitForTimeout(1500);
  await shotSection(page, "13-error-state");
  await page.unroute("**/dashboard/servers/**");
  await ctx.close();
}

if (!only || only === "mobile") {
  const { ctx, page } = await ctxFor({ width: 390, height: 844 });
  await gotoMods(page, seed.mc);
  log({ step: "mobile grid", cards: await cards(page).count(), overflow: await overflow(page) });
  await page.locator("section[aria-label^='Browse']").scrollIntoViewIfNeeded();
  await page.screenshot({ path: `${OUT}/20-mobile-grid.png`, fullPage: false });
  await shotSection(page, "21-mobile-section");
  await cards(page).first().click();
  await page.waitForSelector("[role=dialog][aria-modal=true] h2", { timeout: 60_000 });
  await page.waitForFunction(() => !document.querySelector("[aria-label='Loading mod']"), null, { timeout: 60_000 });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/22-mobile-sheet.png` });
  await page.locator("[data-scroll]").evaluate((el) => el.scrollTo({ top: 600 }));
  await page.waitForTimeout(300);
  await page.screenshot({ path: `${OUT}/23-mobile-sheet-scrolled.png` });
  log({ step: "mobile sheet", overflow: await overflow(page) });
  await page.keyboard.press("Escape");
  await page.goto(`${base}/dashboard/servers/${seed.mc}?tab=mods&mod=veinminer-enchantment`, { waitUntil: "domcontentloaded", timeout: 240_000 });
  await page.waitForSelector("[role=dialog][aria-modal=true] h2", { timeout: 120_000 });
  await page.waitForFunction(() => !document.querySelector("[aria-label='Loading mod']"), null, { timeout: 60_000 });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${OUT}/24-mobile-sheet-verified.png` });
  const b = page.getByRole("button", { name: /Nxeon Verified for/ }).first();
  if (await b.count()) { await b.click(); await page.waitForTimeout(300); await page.screenshot({ path: `${OUT}/25-mobile-popover.png` }); }
  await ctx.close();
}

if (!only || only === "light") {
  const { ctx, page } = await ctxFor({ width: 1280, height: 900 });
  await gotoMods(page, seed.mcf);
  await page.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
  await page.waitForTimeout(400);
  await shotSection(page, "30-light-fabric-grid");
  await cards(page).nth(1).click();
  await page.waitForSelector("[role=dialog][aria-modal=true] h2", { timeout: 60_000 });
  await page.waitForFunction(() => !document.querySelector("[aria-label='Loading mod']"), null, { timeout: 60_000 });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/31-light-modal.png` });
  await ctx.close();
  const v = await ctxFor({ width: 1280, height: 900 });
  await gotoMods(v.page, seed.vh);
  await shotSection(v.page, "32-valheim-grid");
  await v.ctx.close();
}

if (!only || only === "admin") {
  const { ctx, page } = await ctxFor({ width: 1440, height: 1000 }, seed.admin, "admin.modui.test");
  await page.goto(`http://admin.modui.test:3047/admin/nxlabs/verified`, { waitUntil: "domcontentloaded", timeout: 240_000 });
  await page.waitForSelector("h1", { timeout: 120_000 });
  await page.waitForTimeout(1000);
  await page.screenshot({ path: `${OUT}/40-admin-queue.png`, fullPage: true });
  log({ step: "admin", title: await page.locator("h1").first().innerText() });
  await ctx.close();
}

await browser.close();
console.log("ERRORS", JSON.stringify([...new Set(errors)], null, 1));

