  return rows.filter((r) => {
    if (!r.modVersionId) return false; // no exact build => never a live badge
    const mine = byId.get(r.modVersionId);
    if (!mine) return false; // build row gone upstream
    const t = mine.publishedAt?.getTime() ?? 0;
    return !versions.some((v) => v.gameModId === r.gameModId && v.id !== mine.id && (v.publishedAt?.getTime() ?? 0) > t && (r.gameVersion === "any" || v.gameVersions.includes(r.gameVersion)));
